insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (170, 15, 1, 18, 'سورة الحجر ١ – ١٨', 'تمنّي الكافرين الإسلام، وحفظ الله للقرآن، وحفظ السماء من الشياطين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 170) = $j$[{"lbl": "الآيات ١ – ٥", "q": "الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ وَقُرۡءَانٖ مُّبِينٖ ﴿١﴾ رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُواْ لَوۡ كَانُواْ مُسۡلِمِينَ ﴿٢﴾ ذَرۡهُمۡ يَأۡكُلُواْ وَيَتَمَتَّعُواْ وَيُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ يَعۡلَمُونَ ﴿٣﴾ وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا وَلَهَا كِتَابٞ مَّعۡلُومٞ ﴿٤﴾ مَّا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ ﴿٥﴾", "w": [["الر", "الله أعلم بمراده بذلك، تُكتب «الر» وتُقرأ: ألف، لام، را."], ["تلك آيات الكتاب", "الآيات المؤلفة من مثل هذه الحروف المقطعة تلك آيات الكتاب."], ["يودّ", "يحب ويرغب متمنياً أن لو كان من المسلمين."], ["ويتمتعوا", "بالملذات والشهوات."], ["ويُلههم الأمل", "بطول العمر وبلوغ الأوطار وإدراك الرغائب الدنيوية."], ["إلا ولها كتاب معلوم", "أجل محدود لإهلاكها."], ["ما تسبق من أمة أجلها", "لا يتقدّم أجلها المحدد لها."]], "m": "السورة مكية تعالج قضايا العقيدة: التوحيد والنبوة والبعث. الله أعلم بمراده بـ«الر»، ومن فوائد هذه الحروف تنبيه السامع وشدّه إلى سماع ما بعدها، إذ كانوا يمتنعون عن سماعه خشية التأثر به. تلك آيات الكتاب وقرآن مبين للحق والباطل والهدى والضلال. ربما يودّ الذين كفروا، يوم القيامة حين يرون المسلمين يدخلون الجنة ويدخلون هم النار، لو كانوا مسلمين، وقد يُحدث الله في الدنيا ظروفاً يتمنى فيها الكافر ذلك. ذرهم يأكلوا ويتمتعوا بالشهوات، ويُلههم الأمل في طول الأعمار وتحقيق الأوطار عن التفكير في عاقبة أمرهم، فسوف يعلمون إذا رُدّوا إلى الله أنهم كانوا مخطئين. وما أهلكنا من أهل قرية بعذاب الإبادة إلا ولها أجل مكتوب في كتاب المقادير، لا يتقدّم ولا يتأخر ولو ساعة، وفي هذا تهديد لأهل مكة وهم يحاربون دعوة الحق، لعل قريتهم قد كُتب لها أجل وهم لا يشعرون.", "h": ["القرآن الكريم مبيّن لكل ما يُحتاج إليه في إسعاد الإنسان وإكماله.", "إنذار الكافرين وتحذيرهم من مواصلة كفرهم وحربهم للإسلام، فإن يوماً سيأتي يتمنون فيه أن لو كانوا مسلمين.", "تقرير عقيدة القضاء والقدر، فما من شيء إلا وسبق به علم الله وكتبه عنده في كتاب المقادير: الحياة كالموت، والربح كالخسارة، والسعادة كالشقاء."], "k": "«ويُلههم الأمل»… أمل طويل يشغلني عن آخرتي؛ ما هو، وكيف أقصّره؟"}, {"lbl": "الآيات ٦ – ١١", "q": "وَقَالُواْ يَـٰٓأَيُّهَا ٱلَّذِي نُزِّلَ عَلَيۡهِ ٱلذِّكۡرُ إِنَّكَ لَمَجۡنُونٞ ﴿٦﴾ لَّوۡمَا تَأۡتِينَا بِٱلۡمَلَـٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٧﴾ مَا نُنَزِّلُ ٱلۡمَلَـٰٓئِكَةَ إِلَّا بِٱلۡحَقِّ وَمَا كَانُوٓاْ إِذٗا مُّنظَرِينَ ﴿٨﴾ إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ﴿٩﴾ وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي شِيَعِ ٱلۡأَوَّلِينَ ﴿١٠﴾ وَمَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿١١﴾", "w": [["نُزّل عليه الذكر", "القرآن الكريم."], ["لو ما تأتينا بالملائكة", "هلّا تأتينا بالملائكة تشهد لك أنك نبي الله."], ["وما كانوا إذاً منظرين", "ممهلين، بل يأخذهم العذاب فور نزول الملائكة."], ["إنا نحن نزّلنا الذكر", "القرآن."], ["في شيع الأولين", "في فرق وطوائف الأولين."]], "m": "قال الكافرون المنكرون للوحي والنبوة: يا أيها الذي نُزّل عليه الذكر إنك لمجنون، وإلا لما ادّعيت النبوة، وفي قولهم استهزاء ظاهر ثمرة ظلمة الكفر في قلوبهم. هلّا تأتينا بالملائكة نراهم عياناً يشهدون لك إن كنت من الصادقين! قال تعالى: ما ننزّل الملائكة إلا بالحق، لإحقاق الحق وإبطال الباطل، لا لمجرد تشهّي الناس، ولو نزلت ولم يؤمنوا لنزل بهم العذاب فوراً وما كانوا ممهلين. إنا نحن نزّلنا القرآن، وإنا له لحافظون من الضياع ومن الزيادة والنقصان، لأنه حجتنا على خلقنا إلى يوم القيامة، أنزلناه هدى ورحمة وشفاء ونوراً، هم يريدون العذاب والله يريد الرحمة. ولقد أرسلنا من قبلك في فرق الأولين وأممهم، وما يأتيهم من رسول إلا كانوا به يستهزئون، لأن علة المرض واحدة، فلا تيأس يا رسول الله ولا تحزن، بل اصبر وانتظر وعد الله لك بالنصر.", "h": ["بيان ما كان يلقاه رسول الله ﷺ من استهزاء وسخرية من المشركين.", "مظهر من مظاهر رحمة الله بالإنسان: يطلب نزول العذاب والله ينزل الرحمة.", "بيان حفظ الله تعالى للقرآن الكريم من الزيادة والنقصان ومن الضياع.", "بيان سنة الله تعالى في الأمم والشعوب، وهي أنهم ما يأتيهم من رسول ينكر عليهم مألوفهم ويدعوهم إلى جديد من الخير والهدى إلا وينكرون ويستهزئون."], "k": "«إنا نحن نزّلنا الذكر وإنا له لحافظون»… حفظه الله في السطور؛ فهل أحفظه أنا في صدري وعملي؟"}, {"lbl": "الآيات ١٢ – ١٨", "q": "كَذَٰلِكَ نَسۡلُكُهُۥ فِي قُلُوبِ ٱلۡمُجۡرِمِينَ ﴿١٢﴾ لَا يُؤۡمِنُونَ بِهِۦ وَقَدۡ خَلَتۡ سُنَّةُ ٱلۡأَوَّلِينَ ﴿١٣﴾ وَلَوۡ فَتَحۡنَا عَلَيۡهِم بَابٗا مِّنَ ٱلسَّمَآءِ فَظَلُّواْ فِيهِ يَعۡرُجُونَ ﴿١٤﴾ لَقَالُوٓاْ إِنَّمَا سُكِّرَتۡ أَبۡصَٰرُنَا بَلۡ نَحۡنُ قَوۡمٞ مَّسۡحُورُونَ ﴿١٥﴾ وَلَقَدۡ جَعَلۡنَا فِي ٱلسَّمَآءِ بُرُوجٗا وَزَيَّنَّـٰهَا لِلنَّـٰظِرِينَ ﴿١٦﴾ وَحَفِظۡنَٰهَا مِن كُلِّ شَيۡطَٰنٖ رَّجِيمٍ ﴿١٧﴾ إِلَّا مَنِ ٱسۡتَرَقَ ٱلسَّمۡعَ فَأَتۡبَعَهُۥ شِهَابٞ مُّبِينٞ ﴿١٨﴾", "w": [["كذلك نسلكه", "التكذيب بالقرآن أو النبي ﷺ."], ["وقد خلت سنة الأولين", "مضت سنة الأمم السابقة."], ["فظلّوا فيه يعرجون", "يصعدون."], ["إنما سُكّرت", "سُدّت كما يُسكّر النهر أو الباب."], ["في السماء بروجاً", "كواكب ينزلها الشمس والقمر."], ["شيطان رجيم", "مرجوم بالشهب."], ["شهاب مبين", "كوكب يُرجم به الشيطان يحرقه أو يمزّقه أو يخبله."]], "m": "ما زال السياق في المكذّبين المطالبين بنزول الملائكة: كذلك نسلك التكذيب في قلوب المجرمين من قومك، كما سلكناه في قلوب من كذّبوا الرسل من قبلك، فلا يؤمنون، وقد مضت سنة الأولين في تعذيب المكذّبين المستهزئين، لأنهم لا يؤمنون حتى يروا العذاب الأليم. ولو فتحنا عليهم باباً من السماء فظلّوا فيه يصعدون طوال النهار، لقالوا في المساء: إنما سُدّت أبصارنا فلم نر حقيقة، بل نحن قوم مسحورون. ولقد جعلنا في السماء كواكب هي منازل للشمس والقمر، يُعرف بها عدد السنين والحساب، وزيّناها بالنجوم للناظرين، وحفظناها من كل شيطان مرجوم ملعون، إلا مارداً طلع لاستراق السمع من الملائكة لينزل بالخبر إلى وليّه من الكهان، فأتبعه شهاب من نار يبين أثره فيه بإخباله أو إحراقه. والقصد من هذا السياق إظهار قدرة الله وعلمه وحكمته ورحمته، وكلها مقتضية لإرسال الرسول وإنزال الكتاب لهداية الناس.", "h": ["بيان سنة الله تعالى في المكذّبين المعاندين، وهي أنهم لا يؤمنون حتى يروا العذاب.", "مطالبة المكذّبين المجرمين بالآيات كرؤية الملائكة لا معنى لها، إذ القرآن أكبر آية ولم يؤمنوا به، فلو فُتح باب من السماء فظلّوا فيه يعرجون لما آمنوا.", "بيان مظاهر قدرة الله تعالى وعلمه وحكمته ورحمته فيما حملت الآيات من مظاهر لذلك، بدءاً من قوله: «ولقد جعلنا في السماء بروجاً»."], "k": "«ولقد جعلنا في السماء بروجاً وزيّناها للناظرين»… متى رفعت عينيّ إلى السماء ليلاً وتفكّرت؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 170;
insert into public.tdb_cards(topic, i, body) select 170, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "الٓرۚ تِلۡكَ ءَايَٰتُ ٱلۡكِتَٰبِ وَقُرۡءَانٖ مُّبِينٖ ﴿١﴾ رُّبَمَا يَوَدُّ ٱلَّذِينَ كَفَرُواْ لَوۡ كَانُواْ مُسۡلِمِينَ ﴿٢﴾ ذَرۡهُمۡ يَأۡكُلُواْ وَيَتَمَتَّعُواْ وَيُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ يَعۡلَمُونَ ﴿٣﴾ وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا وَلَهَا كِتَابٞ مَّعۡلُومٞ ﴿٤﴾ مَّا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ ﴿٥﴾", "w": [["الر", "الله أعلم بمراده بذلك، تُكتب «الر» وتُقرأ: ألف، لام، را."], ["تلك آيات الكتاب", "الآيات المؤلفة من مثل هذه الحروف المقطعة تلك آيات الكتاب."], ["يودّ", "يحب ويرغب متمنياً أن لو كان من المسلمين."], ["ويتمتعوا", "بالملذات والشهوات."], ["ويُلههم الأمل", "بطول العمر وبلوغ الأوطار وإدراك الرغائب الدنيوية."], ["إلا ولها كتاب معلوم", "أجل محدود لإهلاكها."], ["ما تسبق من أمة أجلها", "لا يتقدّم أجلها المحدد لها."]], "m": "السورة مكية تعالج قضايا العقيدة: التوحيد والنبوة والبعث. الله أعلم بمراده بـ«الر»، ومن فوائد هذه الحروف تنبيه السامع وشدّه إلى سماع ما بعدها، إذ كانوا يمتنعون عن سماعه خشية التأثر به. تلك آيات الكتاب وقرآن مبين للحق والباطل والهدى والضلال. ربما يودّ الذين كفروا، يوم القيامة حين يرون المسلمين يدخلون الجنة ويدخلون هم النار، لو كانوا مسلمين، وقد يُحدث الله في الدنيا ظروفاً يتمنى فيها الكافر ذلك. ذرهم يأكلوا ويتمتعوا بالشهوات، ويُلههم الأمل في طول الأعمار وتحقيق الأوطار عن التفكير في عاقبة أمرهم، فسوف يعلمون إذا رُدّوا إلى الله أنهم كانوا مخطئين. وما أهلكنا من أهل قرية بعذاب الإبادة إلا ولها أجل مكتوب في كتاب المقادير، لا يتقدّم ولا يتأخر ولو ساعة، وفي هذا تهديد لأهل مكة وهم يحاربون دعوة الحق، لعل قريتهم قد كُتب لها أجل وهم لا يشعرون.", "h": ["القرآن الكريم مبيّن لكل ما يُحتاج إليه في إسعاد الإنسان وإكماله.", "إنذار الكافرين وتحذيرهم من مواصلة كفرهم وحربهم للإسلام، فإن يوماً سيأتي يتمنون فيه أن لو كانوا مسلمين.", "تقرير عقيدة القضاء والقدر، فما من شيء إلا وسبق به علم الله وكتبه عنده في كتاب المقادير: الحياة كالموت، والربح كالخسارة، والسعادة كالشقاء."], "k": "«ويُلههم الأمل»… أمل طويل يشغلني عن آخرتي؛ ما هو، وكيف أقصّره؟"}, {"lbl": "الآيات ٦ – ١١", "q": "وَقَالُواْ يَـٰٓأَيُّهَا ٱلَّذِي نُزِّلَ عَلَيۡهِ ٱلذِّكۡرُ إِنَّكَ لَمَجۡنُونٞ ﴿٦﴾ لَّوۡمَا تَأۡتِينَا بِٱلۡمَلَـٰٓئِكَةِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٧﴾ مَا نُنَزِّلُ ٱلۡمَلَـٰٓئِكَةَ إِلَّا بِٱلۡحَقِّ وَمَا كَانُوٓاْ إِذٗا مُّنظَرِينَ ﴿٨﴾ إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ ﴿٩﴾ وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ فِي شِيَعِ ٱلۡأَوَّلِينَ ﴿١٠﴾ وَمَا يَأۡتِيهِم مِّن رَّسُولٍ إِلَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿١١﴾", "w": [["نُزّل عليه الذكر", "القرآن الكريم."], ["لو ما تأتينا بالملائكة", "هلّا تأتينا بالملائكة تشهد لك أنك نبي الله."], ["وما كانوا إذاً منظرين", "ممهلين، بل يأخذهم العذاب فور نزول الملائكة."], ["إنا نحن نزّلنا الذكر", "القرآن."], ["في شيع الأولين", "في فرق وطوائف الأولين."]], "m": "قال الكافرون المنكرون للوحي والنبوة: يا أيها الذي نُزّل عليه الذكر إنك لمجنون، وإلا لما ادّعيت النبوة، وفي قولهم استهزاء ظاهر ثمرة ظلمة الكفر في قلوبهم. هلّا تأتينا بالملائكة نراهم عياناً يشهدون لك إن كنت من الصادقين! قال تعالى: ما ننزّل الملائكة إلا بالحق، لإحقاق الحق وإبطال الباطل، لا لمجرد تشهّي الناس، ولو نزلت ولم يؤمنوا لنزل بهم العذاب فوراً وما كانوا ممهلين. إنا نحن نزّلنا القرآن، وإنا له لحافظون من الضياع ومن الزيادة والنقصان، لأنه حجتنا على خلقنا إلى يوم القيامة، أنزلناه هدى ورحمة وشفاء ونوراً، هم يريدون العذاب والله يريد الرحمة. ولقد أرسلنا من قبلك في فرق الأولين وأممهم، وما يأتيهم من رسول إلا كانوا به يستهزئون، لأن علة المرض واحدة، فلا تيأس يا رسول الله ولا تحزن، بل اصبر وانتظر وعد الله لك بالنصر.", "h": ["بيان ما كان يلقاه رسول الله ﷺ من استهزاء وسخرية من المشركين.", "مظهر من مظاهر رحمة الله بالإنسان: يطلب نزول العذاب والله ينزل الرحمة.", "بيان حفظ الله تعالى للقرآن الكريم من الزيادة والنقصان ومن الضياع.", "بيان سنة الله تعالى في الأمم والشعوب، وهي أنهم ما يأتيهم من رسول ينكر عليهم مألوفهم ويدعوهم إلى جديد من الخير والهدى إلا وينكرون ويستهزئون."], "k": "«إنا نحن نزّلنا الذكر وإنا له لحافظون»… حفظه الله في السطور؛ فهل أحفظه أنا في صدري وعملي؟"}, {"lbl": "الآيات ١٢ – ١٨", "q": "كَذَٰلِكَ نَسۡلُكُهُۥ فِي قُلُوبِ ٱلۡمُجۡرِمِينَ ﴿١٢﴾ لَا يُؤۡمِنُونَ بِهِۦ وَقَدۡ خَلَتۡ سُنَّةُ ٱلۡأَوَّلِينَ ﴿١٣﴾ وَلَوۡ فَتَحۡنَا عَلَيۡهِم بَابٗا مِّنَ ٱلسَّمَآءِ فَظَلُّواْ فِيهِ يَعۡرُجُونَ ﴿١٤﴾ لَقَالُوٓاْ إِنَّمَا سُكِّرَتۡ أَبۡصَٰرُنَا بَلۡ نَحۡنُ قَوۡمٞ مَّسۡحُورُونَ ﴿١٥﴾ وَلَقَدۡ جَعَلۡنَا فِي ٱلسَّمَآءِ بُرُوجٗا وَزَيَّنَّـٰهَا لِلنَّـٰظِرِينَ ﴿١٦﴾ وَحَفِظۡنَٰهَا مِن كُلِّ شَيۡطَٰنٖ رَّجِيمٍ ﴿١٧﴾ إِلَّا مَنِ ٱسۡتَرَقَ ٱلسَّمۡعَ فَأَتۡبَعَهُۥ شِهَابٞ مُّبِينٞ ﴿١٨﴾", "w": [["كذلك نسلكه", "التكذيب بالقرآن أو النبي ﷺ."], ["وقد خلت سنة الأولين", "مضت سنة الأمم السابقة."], ["فظلّوا فيه يعرجون", "يصعدون."], ["إنما سُكّرت", "سُدّت كما يُسكّر النهر أو الباب."], ["في السماء بروجاً", "كواكب ينزلها الشمس والقمر."], ["شيطان رجيم", "مرجوم بالشهب."], ["شهاب مبين", "كوكب يُرجم به الشيطان يحرقه أو يمزّقه أو يخبله."]], "m": "ما زال السياق في المكذّبين المطالبين بنزول الملائكة: كذلك نسلك التكذيب في قلوب المجرمين من قومك، كما سلكناه في قلوب من كذّبوا الرسل من قبلك، فلا يؤمنون، وقد مضت سنة الأولين في تعذيب المكذّبين المستهزئين، لأنهم لا يؤمنون حتى يروا العذاب الأليم. ولو فتحنا عليهم باباً من السماء فظلّوا فيه يصعدون طوال النهار، لقالوا في المساء: إنما سُدّت أبصارنا فلم نر حقيقة، بل نحن قوم مسحورون. ولقد جعلنا في السماء كواكب هي منازل للشمس والقمر، يُعرف بها عدد السنين والحساب، وزيّناها بالنجوم للناظرين، وحفظناها من كل شيطان مرجوم ملعون، إلا مارداً طلع لاستراق السمع من الملائكة لينزل بالخبر إلى وليّه من الكهان، فأتبعه شهاب من نار يبين أثره فيه بإخباله أو إحراقه. والقصد من هذا السياق إظهار قدرة الله وعلمه وحكمته ورحمته، وكلها مقتضية لإرسال الرسول وإنزال الكتاب لهداية الناس.", "h": ["بيان سنة الله تعالى في المكذّبين المعاندين، وهي أنهم لا يؤمنون حتى يروا العذاب.", "مطالبة المكذّبين المجرمين بالآيات كرؤية الملائكة لا معنى لها، إذ القرآن أكبر آية ولم يؤمنوا به، فلو فُتح باب من السماء فظلّوا فيه يعرجون لما آمنوا.", "بيان مظاهر قدرة الله تعالى وعلمه وحكمته ورحمته فيما حملت الآيات من مظاهر لذلك، بدءاً من قوله: «ولقد جعلنا في السماء بروجاً»."], "k": "«ولقد جعلنا في السماء بروجاً وزيّناها للناظرين»… متى رفعت عينيّ إلى السماء ليلاً وتفكّرت؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (171, 15, 19, 44, 'سورة الحجر ١٩ – ٤٤', 'خزائن الله وإنزال الرزق بقدر، وخلق آدم، وإبليس وأبواب جهنم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 171) = $j$[{"lbl": "الآيات ١٩ – ٢٥", "q": "وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ شَيۡءٖ مَّوۡزُونٖ ﴿١٩﴾ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَٰزِقِينَ ﴿٢٠﴾ وَإِن مِّن شَيۡءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٖ مَّعۡلُومٖ ﴿٢١﴾ وَأَرۡسَلۡنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ لَهُۥ بِخَٰزِنِينَ ﴿٢٢﴾ وَإِنَّا لَنَحۡنُ نُحۡيِۦ وَنُمِيتُ وَنَحۡنُ ٱلۡوَٰرِثُونَ ﴿٢٣﴾ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِينَ مِنكُمۡ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَـٔۡخِرِينَ ﴿٢٤﴾ وَإِنَّ رَبَّكَ هُوَ يَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ﴿٢٥﴾", "w": [["والأرض مددناها", "بسطناها."], ["وألقينا فيها رواسي", "جبالاً ثوابت لئلا تتحرك الأرض."], ["موزون", "مقدّر معلوم المقدار لله تعالى."], ["معايش", "جمع معيشة، ما يعيش عليه الإنسان من الأغذية."], ["ومن لستم له برازقين", "كالعبيد والإماء والبهائم."], ["وما ننزله إلا بقدر معلوم", "أي المطر."], ["وأرسلنا الرياح لواقح", "تلقّح السحاب فيمتلئ ماءً، كما تنقل مادة اللقاح من ذكر الشجر إلى أنثاه."], ["وما أنتم له بخازنين", "لا تملكون خزائنه فتمنعونه أو تعطونه من تشاؤون."], ["المستقدمين منكم والمستأخرين", "من هلكوا من بني آدم إلى يومكم هذا، ومن هم أحياء ومن لم يوجدوا بعد."]], "m": "ما زال السياق في ذكر مظاهر قدرة الله وعلمه وحكمته ورحمته، وهي موجبات الإيمان به وعبادته وتوحيده: والأرض بسطناها، وألقينا فيها جبالاً ثوابت تثبّتها حتى لا تميد بأهلها، وأنبتنا فيها من كل شيء مقدّر معلوم المقدار، وجعلنا لكم فيها معايش من الحبوب والثمار، ومن لستم له برازقين من العبيد والإماء والبهائم، بل الله يرزقه وإياكم. وما من شيء نافع للبشرية إلا عند الله خزائنه، ومن ذلك الأمطار، وما ننزله إلا بقدر معلوم حسب حاجة المخلوقات. وأرسلنا الرياح لواقح للسحاب، فأنزلنا من السماء ماءً فأسقيناكموه، وما أنتم له بخازنين فتمنعونه من تشاؤون. وإنا لنحن نحيي ونميت ونحن الوارثون، ولقد علمنا من مات منكم من لدن آدم، ومن هم أحياء ومن سيوجدون إلى يوم القيامة، الجميع علمهم الله وغيره لا يعلم، فلذا استحق العبادة وحده. وإن ربك هو يحشرهم ليحاسبهم ويجازيهم، فالذي أحياهم ثم أماتهم قادر على إحيائهم مرة أخرى، والحكيم لا يخلقهم عبثاً، بل ليبلوهم ثم يجزيهم.", "h": ["بيان مظاهر قدرة الله وعلمه وحكمته ورحمته المتجلّية في: خلق الأرض ومدّها وإلقاء الجبال فيها، وإرسال الرياح لواقح للسحب، وإنبات النباتات بموازين دقيقة، وإحياء المخلوقات ثم إماتتها، وإنزال المطر بمقادير معيّنة، وعلمه تعالى بمن مات ومن سيموت.", "تقرير التوحيد، وأن من هذه آثار قدرته هو الواجب أن يُعبد وحده دون سواه.", "تقرير عقيدة البعث والجزاء.", "تقرير نبوة الرسول ﷺ، إذ هذا الكلام كلام الله أوحاه إليه ﷺ."], "k": "«وإن من شيء إلا عندنا خزائنه»… ما أحتاجه كله في خزائن ربي؛ فلماذا أطلبه من غيره؟"}, {"lbl": "الآيات ٢٦ – ٣٣", "q": "وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ ﴿٢٦﴾ وَٱلۡجَآنَّ خَلَقۡنَٰهُ مِن قَبۡلُ مِن نَّارِ ٱلسَّمُومِ ﴿٢٧﴾ وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ ﴿٢٨﴾ فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ ﴿٢٩﴾ فَسَجَدَ ٱلۡمَلَـٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ ﴿٣٠﴾ إِلَّآ إِبۡلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّـٰجِدِينَ ﴿٣١﴾ قَالَ يَـٰٓإِبۡلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّـٰجِدِينَ ﴿٣٢﴾ قَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ ﴿٣٣﴾", "w": [["ولقد خلقنا الإنسان", "آدم ﵇."], ["من صلصال من حمأ مسنون", "طين يابس له صلصلة، من حمأ أي طين أسود متغيّر."], ["من نار السموم", "نار لا دخان لها، تنفذ في المسام وهي ثقب الجلد."], ["فإذا سوّيته", "أتممت خلقه."], ["فقعوا له ساجدين", "خرّوا له ساجدين."]], "m": "ما زال السياق في ذكر مظاهر قدرة الله وعلمه وحكمته: ولقد خلقنا آدم من طين يابس يُسمع له صوت صلصلة، من طين أسود متغيّر الريح، والجان، أبا الجن، خلقناه من قبل آدم من نار لا دخان لها تنفذ في مسام الجسم. واذكر إذ قال ربك للملائكة: إني خالق بشراً من صلصال، فإذا أتممت خلقه ونفخت فيه من روحي فخرّوا له ساجدين، سجود تحية وتعظيم لا سجود عبادة، إذ المعبود هو الآمر المطاع وهو الله. فسجد الملائكة كلهم أجمعون إلا إبليس أبى أن يكون مع الساجدين. قال: يا إبليس ما لك ألا تكون مع الساجدين؟ فأظهر سبب امتناعه، وهو حسده لآدم واستكباره، فقال: لم أكن لأسجد لبشر خلقته من صلصال من حمأ مسنون.", "h": ["بيان أصل خلق الإنسان وهو الطين، والجان وهو لهب النار.", "فضل السجود، إذ أمر تعالى به الملائكة فسجدوا أجمعون إلا إبليس.", "ذم الحسد، وأنه شر الذنوب وأكثرها ضرراً.", "ذم الكبر، وأنه عائق لصاحبه عن الكمال في الدنيا والسعادة في الآخرة.", "فضل الطين على النار، لأن من الطين خُلق آدم، ومن النار خُلق إبليس."], "k": "«لم أكن لأسجد لبشر»… الكبر أخرج إبليس من الرحمة؛ فأين يختبئ الكبر في نفسي؟"}, {"lbl": "الآيات ٣٤ – ٤٤", "q": "قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ ﴿٣٤﴾ وَإِنَّ عَلَيۡكَ ٱللَّعۡنَةَ إِلَىٰ يَوۡمِ ٱلدِّينِ ﴿٣٥﴾ قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿٣٦﴾ قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ ﴿٣٧﴾ إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ ﴿٣٨﴾ قَالَ رَبِّ بِمَآ أَغۡوَيۡتَنِي لَأُزَيِّنَنَّ لَهُمۡ فِي ٱلۡأَرۡضِ وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ﴿٣٩﴾ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ ﴿٤٠﴾ قَالَ هَٰذَا صِرَٰطٌ عَلَيَّ مُسۡتَقِيمٌ ﴿٤١﴾ إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلۡغَاوِينَ ﴿٤٢﴾ وَإِنَّ جَهَنَّمَ لَمَوۡعِدُهُمۡ أَجۡمَعِينَ ﴿٤٣﴾ لَهَا سَبۡعَةُ أَبۡوَٰبٖ لِّكُلِّ بَابٖ مِّنۡهُمۡ جُزۡءٞ مَّقۡسُومٌ ﴿٤٤﴾", "w": [["قال فاخرج منها", "من الجنة."], ["فإنك رجيم", "مرجوم مطرود ملعون."], ["إلى يوم الوقت المعلوم", "وقت النفخة الأولى التي تموت فيها الخلائق كلها."], ["بما أغويتني", "بسبب إغوائك لي، أي إضلالك وإفسادك لي."], ["المخلَصين", "الذين استخلصتهم لطاعتك، فإن كيدي لا يعمل فيهم."], ["هذا صراط عليّ مستقيم", "هذا طريق مستقيم موصل إليّ، وعليّ مراعاته وحفظه."], ["لها سبعة أبواب", "أبواب طبقاتها السبع، وهي: جهنم، ثم لظى، ثم الحطمة، ثم السعير، ثم سقر، ثم الجحيم، ثم الهاوية."]], "m": "جواباً عن قول إبليس: «لم أكن لأسجد لبشر»، قال الله: فاخرج من الجنة فإنك مرجوم مطرود مبعد، وإن عليك لعنتي إلى يوم القيامة. قال: رب فأمهلني ولا تمتني إلى يوم يبعثون، قال: فإنك من الممهلين إلى يوم الوقت المعلوم، عند النفخة الأولى. فلما سمع اللعين حكم ربه قال: رب بسبب إغوائك لي لأزيّننّ لهم في الأرض الكفر والشرك وكبائر الذنوب، ولأضلّنّهم أجمعين، إلا عبادك منهم الذين استخلصتهم لطاعتك، الذين لا يستعبدهم غضب ولا تتحكم فيهم شهوة ولا هوى. قال الله: هذا طريق مستقيم إليّ أرعاه وأحفظه: إن عبادي ليس لك عليهم سلطان إلا من اتبعك من الغاوين، وإن جهنم لموعدك وموعد أتباعك أجمعين، لها سبعة أبواب، إذ هي سبع طبقات لكل طبقة باب فوقها يدخل معه أهلها، لكل باب منهم نصيب معيّن.", "h": ["حرمان إبليس من التوبة لاستمرار غضب الله عليه إلى يوم القيامة.", "استجاب الله لشر خلقه وهو إبليس، فمن الجائز أن يستجيب الله دعاء الكافر لحكمة يريدها الله تعالى.", "أمضى سلاح يغوي به إبليس بني آدم هو التزيين للأشياء، حتى ولو كانت دميمة قبيحة يصيّرها بوسواسه زينة حسنة حتى يأتيها الآدمي.", "عصمة الرسل، وحفظ الله للأولياء حتى لا يتلوثوا بأوضار الذنوب.", "طريق الله مستقيم إلى الله تعالى، يسلكه الناس حتى ينتهوا إلى الله سبحانه فيحاسبهم ويجزيهم بكسبهم.", "بيان أن لجهنم طبقات واحدة فوق أخرى، ولكل طبقة بابها فوقها يدخل معه أهل تلك الطبقة."], "k": "«لأزيّننّ لهم في الأرض»… معصية تبدو لي جميلة الآن؛ هل أراها بعين الشرع لا بتزيين الشيطان؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 171;
insert into public.tdb_cards(topic, i, body) select 171, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٩ – ٢٥", "q": "وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ شَيۡءٖ مَّوۡزُونٖ ﴿١٩﴾ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَٰزِقِينَ ﴿٢٠﴾ وَإِن مِّن شَيۡءٍ إِلَّا عِندَنَا خَزَآئِنُهُۥ وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٖ مَّعۡلُومٖ ﴿٢١﴾ وَأَرۡسَلۡنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ لَهُۥ بِخَٰزِنِينَ ﴿٢٢﴾ وَإِنَّا لَنَحۡنُ نُحۡيِۦ وَنُمِيتُ وَنَحۡنُ ٱلۡوَٰرِثُونَ ﴿٢٣﴾ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِينَ مِنكُمۡ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَـٔۡخِرِينَ ﴿٢٤﴾ وَإِنَّ رَبَّكَ هُوَ يَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ﴿٢٥﴾", "w": [["والأرض مددناها", "بسطناها."], ["وألقينا فيها رواسي", "جبالاً ثوابت لئلا تتحرك الأرض."], ["موزون", "مقدّر معلوم المقدار لله تعالى."], ["معايش", "جمع معيشة، ما يعيش عليه الإنسان من الأغذية."], ["ومن لستم له برازقين", "كالعبيد والإماء والبهائم."], ["وما ننزله إلا بقدر معلوم", "أي المطر."], ["وأرسلنا الرياح لواقح", "تلقّح السحاب فيمتلئ ماءً، كما تنقل مادة اللقاح من ذكر الشجر إلى أنثاه."], ["وما أنتم له بخازنين", "لا تملكون خزائنه فتمنعونه أو تعطونه من تشاؤون."], ["المستقدمين منكم والمستأخرين", "من هلكوا من بني آدم إلى يومكم هذا، ومن هم أحياء ومن لم يوجدوا بعد."]], "m": "ما زال السياق في ذكر مظاهر قدرة الله وعلمه وحكمته ورحمته، وهي موجبات الإيمان به وعبادته وتوحيده: والأرض بسطناها، وألقينا فيها جبالاً ثوابت تثبّتها حتى لا تميد بأهلها، وأنبتنا فيها من كل شيء مقدّر معلوم المقدار، وجعلنا لكم فيها معايش من الحبوب والثمار، ومن لستم له برازقين من العبيد والإماء والبهائم، بل الله يرزقه وإياكم. وما من شيء نافع للبشرية إلا عند الله خزائنه، ومن ذلك الأمطار، وما ننزله إلا بقدر معلوم حسب حاجة المخلوقات. وأرسلنا الرياح لواقح للسحاب، فأنزلنا من السماء ماءً فأسقيناكموه، وما أنتم له بخازنين فتمنعونه من تشاؤون. وإنا لنحن نحيي ونميت ونحن الوارثون، ولقد علمنا من مات منكم من لدن آدم، ومن هم أحياء ومن سيوجدون إلى يوم القيامة، الجميع علمهم الله وغيره لا يعلم، فلذا استحق العبادة وحده. وإن ربك هو يحشرهم ليحاسبهم ويجازيهم، فالذي أحياهم ثم أماتهم قادر على إحيائهم مرة أخرى، والحكيم لا يخلقهم عبثاً، بل ليبلوهم ثم يجزيهم.", "h": ["بيان مظاهر قدرة الله وعلمه وحكمته ورحمته المتجلّية في: خلق الأرض ومدّها وإلقاء الجبال فيها، وإرسال الرياح لواقح للسحب، وإنبات النباتات بموازين دقيقة، وإحياء المخلوقات ثم إماتتها، وإنزال المطر بمقادير معيّنة، وعلمه تعالى بمن مات ومن سيموت.", "تقرير التوحيد، وأن من هذه آثار قدرته هو الواجب أن يُعبد وحده دون سواه.", "تقرير عقيدة البعث والجزاء.", "تقرير نبوة الرسول ﷺ، إذ هذا الكلام كلام الله أوحاه إليه ﷺ."], "k": "«وإن من شيء إلا عندنا خزائنه»… ما أحتاجه كله في خزائن ربي؛ فلماذا أطلبه من غيره؟"}, {"lbl": "الآيات ٢٦ – ٣٣", "q": "وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ ﴿٢٦﴾ وَٱلۡجَآنَّ خَلَقۡنَٰهُ مِن قَبۡلُ مِن نَّارِ ٱلسَّمُومِ ﴿٢٧﴾ وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰٓئِكَةِ إِنِّي خَٰلِقُۢ بَشَرٗا مِّن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ ﴿٢٨﴾ فَإِذَا سَوَّيۡتُهُۥ وَنَفَخۡتُ فِيهِ مِن رُّوحِي فَقَعُواْ لَهُۥ سَٰجِدِينَ ﴿٢٩﴾ فَسَجَدَ ٱلۡمَلَـٰٓئِكَةُ كُلُّهُمۡ أَجۡمَعُونَ ﴿٣٠﴾ إِلَّآ إِبۡلِيسَ أَبَىٰٓ أَن يَكُونَ مَعَ ٱلسَّـٰجِدِينَ ﴿٣١﴾ قَالَ يَـٰٓإِبۡلِيسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّـٰجِدِينَ ﴿٣٢﴾ قَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَٰلٖ مِّنۡ حَمَإٖ مَّسۡنُونٖ ﴿٣٣﴾", "w": [["ولقد خلقنا الإنسان", "آدم ﵇."], ["من صلصال من حمأ مسنون", "طين يابس له صلصلة، من حمأ أي طين أسود متغيّر."], ["من نار السموم", "نار لا دخان لها، تنفذ في المسام وهي ثقب الجلد."], ["فإذا سوّيته", "أتممت خلقه."], ["فقعوا له ساجدين", "خرّوا له ساجدين."]], "m": "ما زال السياق في ذكر مظاهر قدرة الله وعلمه وحكمته: ولقد خلقنا آدم من طين يابس يُسمع له صوت صلصلة، من طين أسود متغيّر الريح، والجان، أبا الجن، خلقناه من قبل آدم من نار لا دخان لها تنفذ في مسام الجسم. واذكر إذ قال ربك للملائكة: إني خالق بشراً من صلصال، فإذا أتممت خلقه ونفخت فيه من روحي فخرّوا له ساجدين، سجود تحية وتعظيم لا سجود عبادة، إذ المعبود هو الآمر المطاع وهو الله. فسجد الملائكة كلهم أجمعون إلا إبليس أبى أن يكون مع الساجدين. قال: يا إبليس ما لك ألا تكون مع الساجدين؟ فأظهر سبب امتناعه، وهو حسده لآدم واستكباره، فقال: لم أكن لأسجد لبشر خلقته من صلصال من حمأ مسنون.", "h": ["بيان أصل خلق الإنسان وهو الطين، والجان وهو لهب النار.", "فضل السجود، إذ أمر تعالى به الملائكة فسجدوا أجمعون إلا إبليس.", "ذم الحسد، وأنه شر الذنوب وأكثرها ضرراً.", "ذم الكبر، وأنه عائق لصاحبه عن الكمال في الدنيا والسعادة في الآخرة.", "فضل الطين على النار، لأن من الطين خُلق آدم، ومن النار خُلق إبليس."], "k": "«لم أكن لأسجد لبشر»… الكبر أخرج إبليس من الرحمة؛ فأين يختبئ الكبر في نفسي؟"}, {"lbl": "الآيات ٣٤ – ٤٤", "q": "قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِيمٞ ﴿٣٤﴾ وَإِنَّ عَلَيۡكَ ٱللَّعۡنَةَ إِلَىٰ يَوۡمِ ٱلدِّينِ ﴿٣٥﴾ قَالَ رَبِّ فَأَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿٣٦﴾ قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِينَ ﴿٣٧﴾ إِلَىٰ يَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ ﴿٣٨﴾ قَالَ رَبِّ بِمَآ أَغۡوَيۡتَنِي لَأُزَيِّنَنَّ لَهُمۡ فِي ٱلۡأَرۡضِ وَلَأُغۡوِيَنَّهُمۡ أَجۡمَعِينَ ﴿٣٩﴾ إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِينَ ﴿٤٠﴾ قَالَ هَٰذَا صِرَٰطٌ عَلَيَّ مُسۡتَقِيمٌ ﴿٤١﴾ إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلۡغَاوِينَ ﴿٤٢﴾ وَإِنَّ جَهَنَّمَ لَمَوۡعِدُهُمۡ أَجۡمَعِينَ ﴿٤٣﴾ لَهَا سَبۡعَةُ أَبۡوَٰبٖ لِّكُلِّ بَابٖ مِّنۡهُمۡ جُزۡءٞ مَّقۡسُومٌ ﴿٤٤﴾", "w": [["قال فاخرج منها", "من الجنة."], ["فإنك رجيم", "مرجوم مطرود ملعون."], ["إلى يوم الوقت المعلوم", "وقت النفخة الأولى التي تموت فيها الخلائق كلها."], ["بما أغويتني", "بسبب إغوائك لي، أي إضلالك وإفسادك لي."], ["المخلَصين", "الذين استخلصتهم لطاعتك، فإن كيدي لا يعمل فيهم."], ["هذا صراط عليّ مستقيم", "هذا طريق مستقيم موصل إليّ، وعليّ مراعاته وحفظه."], ["لها سبعة أبواب", "أبواب طبقاتها السبع، وهي: جهنم، ثم لظى، ثم الحطمة، ثم السعير، ثم سقر، ثم الجحيم، ثم الهاوية."]], "m": "جواباً عن قول إبليس: «لم أكن لأسجد لبشر»، قال الله: فاخرج من الجنة فإنك مرجوم مطرود مبعد، وإن عليك لعنتي إلى يوم القيامة. قال: رب فأمهلني ولا تمتني إلى يوم يبعثون، قال: فإنك من الممهلين إلى يوم الوقت المعلوم، عند النفخة الأولى. فلما سمع اللعين حكم ربه قال: رب بسبب إغوائك لي لأزيّننّ لهم في الأرض الكفر والشرك وكبائر الذنوب، ولأضلّنّهم أجمعين، إلا عبادك منهم الذين استخلصتهم لطاعتك، الذين لا يستعبدهم غضب ولا تتحكم فيهم شهوة ولا هوى. قال الله: هذا طريق مستقيم إليّ أرعاه وأحفظه: إن عبادي ليس لك عليهم سلطان إلا من اتبعك من الغاوين، وإن جهنم لموعدك وموعد أتباعك أجمعين، لها سبعة أبواب، إذ هي سبع طبقات لكل طبقة باب فوقها يدخل معه أهلها، لكل باب منهم نصيب معيّن.", "h": ["حرمان إبليس من التوبة لاستمرار غضب الله عليه إلى يوم القيامة.", "استجاب الله لشر خلقه وهو إبليس، فمن الجائز أن يستجيب الله دعاء الكافر لحكمة يريدها الله تعالى.", "أمضى سلاح يغوي به إبليس بني آدم هو التزيين للأشياء، حتى ولو كانت دميمة قبيحة يصيّرها بوسواسه زينة حسنة حتى يأتيها الآدمي.", "عصمة الرسل، وحفظ الله للأولياء حتى لا يتلوثوا بأوضار الذنوب.", "طريق الله مستقيم إلى الله تعالى، يسلكه الناس حتى ينتهوا إلى الله سبحانه فيحاسبهم ويجزيهم بكسبهم.", "بيان أن لجهنم طبقات واحدة فوق أخرى، ولكل طبقة بابها فوقها يدخل معه أهل تلك الطبقة."], "k": "«لأزيّننّ لهم في الأرض»… معصية تبدو لي جميلة الآن؛ هل أراها بعين الشرع لا بتزيين الشيطان؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (172, 15, 45, 66, 'سورة الحجر ٤٥ – ٦٦', 'نعيم المتقين، و«نبّئ عبادي أني أنا الغفور الرحيم»، وضيف إبراهيم ﵇ ورسل لوط ﵇', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 172) = $j$[{"lbl": "الآيات ٤٥ – ٥٦", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَعُيُونٍ ﴿٤٥﴾ ٱدۡخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ ﴿٤٦﴾ وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلٍّ إِخۡوَٰنًا عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ ﴿٤٧﴾ لَا يَمَسُّهُمۡ فِيهَا نَصَبٞ وَمَا هُم مِّنۡهَا بِمُخۡرَجِينَ ﴿٤٨﴾ ۞نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٤٩﴾ وَأَنَّ عَذَابِي هُوَ ٱلۡعَذَابُ ٱلۡأَلِيمُ ﴿٥٠﴾ وَنَبِّئۡهُمۡ عَن ضَيۡفِ إِبۡرَٰهِيمَ ﴿٥١﴾ إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ ﴿٥٢﴾ قَالُواْ لَا تَوۡجَلۡ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمٖ ﴿٥٣﴾ قَالَ أَبَشَّرۡتُمُونِي عَلَىٰٓ أَن مَّسَّنِيَ ٱلۡكِبَرُ فَبِمَ تُبَشِّرُونَ ﴿٥٤﴾ قَالُواْ بَشَّرۡنَٰكَ بِٱلۡحَقِّ فَلَا تَكُن مِّنَ ٱلۡقَٰنِطِينَ ﴿٥٥﴾ قَالَ وَمَن يَقۡنَطُ مِن رَّحۡمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ ﴿٥٦﴾", "w": [["إن المتقين", "الذين خافوا ربهم فعبدوه وحده بما شرع لهم من العبادات."], ["ونزعنا ما في صدورهم من غل", "حقد وحسد وعداوة وبغضاء."], ["على سرر متقابلين", "ينظر بعضهم إلى بعض ما داموا جالسين، وإذا انصرفوا دارت بهم الأسرّة فلا ينظر بعضهم إلى قفا بعض."], ["لا يمسّهم فيها نصب", "تعب."], ["العذاب الأليم", "الموجع شديد الإيجاع."], ["ضيف إبراهيم", "ملائكة نزلوا عليه وهم في طريقهم إلى قوم لوط لإهلاكهم، من بينهم جبريل، في صورة شباب."], ["إنا منكم وجلون", "خائفون، وذلك لما رفضوا أن يأكلوا."], ["بغلام عليم", "لذي علم كثير، هو إسحاق ﵇."], ["من القانطين", "الآيسين."]], "m": "لما ذكر جزاء أتباع إبليس الغاوين، ذكر جزاء أهل التقوى: إن المتقين الله بترك الشرك والمعاصي في جنات وعيون، يقال لهم: ادخلوها بسلام آمنين من الخوف والفزع، ونزعنا ما في صدورهم من حقد أو حسد أو عداوة يكدّر صفو النعيم، فأصبحوا إخواناً يجلسون على سرر متقابلين وجهاً لوجه، لا يمسّهم فيها تعب، وما هم منها بمخرجين، فهما نعيمان: الراحة الأبدية، والبقاء والخلد. نبّئ عبادي المؤمنين الموحّدين أني أنا الغفور لهم إن عصوا وتابوا، الرحيم بهم، وأن عذابي هو العذاب الأليم، فليحذروا معصيتي. ونبّئهم عن ضيف إبراهيم إذ دخلوا عليه فقالوا سلاماً، فردّ السلام وقدّم لهم عجلاً حنيذاً، فلما امتنعوا من الأكل قال: إنا منكم خائفون، لأن العادة أن الضيف إذا لم يأكل دلّ على أنه يريد سوءاً. قالوا: لا تخف، إنا نبشّرك بغلام ذي علم كثير. قال متعجباً: أبشّرتموني على أن مسّني الكبر؟ قالوا: بشّرناك بالحق فلا تكن من الآيسين. قال نافياً القنوط عنه: ومن يقنط من رحمة ربه إلا الضالون الجاهلون بربهم وصفاته.", "h": ["تقرير نعيم الجنة، وأن نعيمها جسماني روحاني معاً، دائم أبداً.", "صفاء نعيم الجنة من كل ما ينغّصه أو يكدّره.", "وعد الله بالمغفرة لمن تاب من أهل الإيمان والتقوى من موحّديه.", "وعيده لأهل معاصيه إذا لم يتوبوا إليه قبل موتهم.", "مشروعية الضيافة، وأنها من خلال البر والكرم.", "حرمة القنوط واليأس من رحمة الله تعالى."], "k": "«ومن يقنط من رحمة ربه إلا الضالون»… ذنب أو همّ يكاد يُقنطني؛ أليس ربي الغفور الرحيم؟"}, {"lbl": "الآيات ٥٧ – ٦٦", "q": "قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ ﴿٥٧﴾ قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ ﴿٥٨﴾ إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمۡ أَجۡمَعِينَ ﴿٥٩﴾ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَآ إِنَّهَا لَمِنَ ٱلۡغَٰبِرِينَ ﴿٦٠﴾ فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلۡمُرۡسَلُونَ ﴿٦١﴾ قَالَ إِنَّكُمۡ قَوۡمٞ مُّنكَرُونَ ﴿٦٢﴾ قَالُواْ بَلۡ جِئۡنَٰكَ بِمَا كَانُواْ فِيهِ يَمۡتَرُونَ ﴿٦٣﴾ وَأَتَيۡنَٰكَ بِٱلۡحَقِّ وَإِنَّا لَصَٰدِقُونَ ﴿٦٤﴾ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَٱتَّبِعۡ أَدۡبَٰرَهُمۡ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٞ وَٱمۡضُواْ حَيۡثُ تُؤۡمَرُونَ ﴿٦٥﴾ وَقَضَيۡنَآ إِلَيۡهِ ذَٰلِكَ ٱلۡأَمۡرَ أَنَّ دَابِرَ هَـٰٓؤُلَآءِ مَقۡطُوعٞ مُّصۡبِحِينَ ﴿٦٦﴾", "w": [["فما خطبكم", "ما شأنكم؟"], ["إلى قوم مجرمين", "هم قوم لوط ﵇."], ["إنا لمنجّوهم أجمعين", "لإيمانهم وصالح أعمالهم."], ["الغابرين", "الباقين في العذاب."], ["قوم منكرون", "لا أعرفكم."], ["بما كانوا فيه يمترون", "بالعذاب الذي كانوا يشكّون في وقوعه بهم."], ["حيث تؤمرون", "إلى الشام حيث أُمروا بالخروج إليه."], ["وقضينا إليه ذلك الأمر", "فرغنا إلى لوط من ذلك الأمر، وأوحينا إليه أن دابر هؤلاء مقطوع مصبحين."]], "m": "قال إبراهيم: فما شأنكم أيها المرسلون؟ قالوا: إنا أُرسلنا إلى قوم مجرمين على أنفسهم وعلى غيرهم، هم قوم لوط، إلا آل لوط والمؤمنين معه إنا لمنجّوهم أجمعين، إلا امرأته قضينا إنها من الباقين في العذاب لأنها كافرة مثلهم. ثم انتقلوا إلى مدينة لوط، فلما دخلوا عليه قال: إنكم قوم لا أعرفكم، قالوا: بل جئناك بالعذاب الذي كان قومك يشكّون فيه، وأتيناك بالحق الثابت وإنا لصادقون، فاسرِ بأهلك في جزء من الليل، وامشِ خلفهم وهم أمامك، ولا يلتفت منكم أحد فيرى ما يسوؤه عند نزول العذاب، وامضوا حيث تُؤمرون، إلى الشام. وفرغنا إلى لوط من ذلك الأمر، وأوحينا إليه أن هؤلاء مُهلكون عن آخرهم في الصباح الباكر.", "h": ["التنديد بالإجرام، وبيان عقوبة المجرمين.", "لا قيمة للنسب ولا للمصاهرة ولا عبرة بالقرابة إذا فصل الكفر والإجرام بين الأنساب والأقرباء، فامرأة لوط هلكت مع الهالكين ولم يشفع لها أنها زوجة نبي ورسول.", "مشروعية المشي بالليل لقطع المسافات البعيدة.", "مشروعية مشي المسؤول وكبير القوم وراء الجيش والقافلة لتفقّد أحوالهم، والاطلاع على من يتخلّف منهم لأمر، وكذا كان رسول الله ﷺ يفعل.", "كراهية الإشفاق على الظلمة الهالكين، لقوله: «ولا يلتفت منكم أحد» أي بقلبه."], "k": "«واتبع أدبارهم»… القائد يمشي خلف قومه يتفقّدهم؛ فهل أتفقّد من أنا مسؤول عنهم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 172;
insert into public.tdb_cards(topic, i, body) select 172, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٥ – ٥٦", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَعُيُونٍ ﴿٤٥﴾ ٱدۡخُلُوهَا بِسَلَٰمٍ ءَامِنِينَ ﴿٤٦﴾ وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلٍّ إِخۡوَٰنًا عَلَىٰ سُرُرٖ مُّتَقَٰبِلِينَ ﴿٤٧﴾ لَا يَمَسُّهُمۡ فِيهَا نَصَبٞ وَمَا هُم مِّنۡهَا بِمُخۡرَجِينَ ﴿٤٨﴾ ۞نَبِّئۡ عِبَادِيٓ أَنِّيٓ أَنَا ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٤٩﴾ وَأَنَّ عَذَابِي هُوَ ٱلۡعَذَابُ ٱلۡأَلِيمُ ﴿٥٠﴾ وَنَبِّئۡهُمۡ عَن ضَيۡفِ إِبۡرَٰهِيمَ ﴿٥١﴾ إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ ﴿٥٢﴾ قَالُواْ لَا تَوۡجَلۡ إِنَّا نُبَشِّرُكَ بِغُلَٰمٍ عَلِيمٖ ﴿٥٣﴾ قَالَ أَبَشَّرۡتُمُونِي عَلَىٰٓ أَن مَّسَّنِيَ ٱلۡكِبَرُ فَبِمَ تُبَشِّرُونَ ﴿٥٤﴾ قَالُواْ بَشَّرۡنَٰكَ بِٱلۡحَقِّ فَلَا تَكُن مِّنَ ٱلۡقَٰنِطِينَ ﴿٥٥﴾ قَالَ وَمَن يَقۡنَطُ مِن رَّحۡمَةِ رَبِّهِۦٓ إِلَّا ٱلضَّآلُّونَ ﴿٥٦﴾", "w": [["إن المتقين", "الذين خافوا ربهم فعبدوه وحده بما شرع لهم من العبادات."], ["ونزعنا ما في صدورهم من غل", "حقد وحسد وعداوة وبغضاء."], ["على سرر متقابلين", "ينظر بعضهم إلى بعض ما داموا جالسين، وإذا انصرفوا دارت بهم الأسرّة فلا ينظر بعضهم إلى قفا بعض."], ["لا يمسّهم فيها نصب", "تعب."], ["العذاب الأليم", "الموجع شديد الإيجاع."], ["ضيف إبراهيم", "ملائكة نزلوا عليه وهم في طريقهم إلى قوم لوط لإهلاكهم، من بينهم جبريل، في صورة شباب."], ["إنا منكم وجلون", "خائفون، وذلك لما رفضوا أن يأكلوا."], ["بغلام عليم", "لذي علم كثير، هو إسحاق ﵇."], ["من القانطين", "الآيسين."]], "m": "لما ذكر جزاء أتباع إبليس الغاوين، ذكر جزاء أهل التقوى: إن المتقين الله بترك الشرك والمعاصي في جنات وعيون، يقال لهم: ادخلوها بسلام آمنين من الخوف والفزع، ونزعنا ما في صدورهم من حقد أو حسد أو عداوة يكدّر صفو النعيم، فأصبحوا إخواناً يجلسون على سرر متقابلين وجهاً لوجه، لا يمسّهم فيها تعب، وما هم منها بمخرجين، فهما نعيمان: الراحة الأبدية، والبقاء والخلد. نبّئ عبادي المؤمنين الموحّدين أني أنا الغفور لهم إن عصوا وتابوا، الرحيم بهم، وأن عذابي هو العذاب الأليم، فليحذروا معصيتي. ونبّئهم عن ضيف إبراهيم إذ دخلوا عليه فقالوا سلاماً، فردّ السلام وقدّم لهم عجلاً حنيذاً، فلما امتنعوا من الأكل قال: إنا منكم خائفون، لأن العادة أن الضيف إذا لم يأكل دلّ على أنه يريد سوءاً. قالوا: لا تخف، إنا نبشّرك بغلام ذي علم كثير. قال متعجباً: أبشّرتموني على أن مسّني الكبر؟ قالوا: بشّرناك بالحق فلا تكن من الآيسين. قال نافياً القنوط عنه: ومن يقنط من رحمة ربه إلا الضالون الجاهلون بربهم وصفاته.", "h": ["تقرير نعيم الجنة، وأن نعيمها جسماني روحاني معاً، دائم أبداً.", "صفاء نعيم الجنة من كل ما ينغّصه أو يكدّره.", "وعد الله بالمغفرة لمن تاب من أهل الإيمان والتقوى من موحّديه.", "وعيده لأهل معاصيه إذا لم يتوبوا إليه قبل موتهم.", "مشروعية الضيافة، وأنها من خلال البر والكرم.", "حرمة القنوط واليأس من رحمة الله تعالى."], "k": "«ومن يقنط من رحمة ربه إلا الضالون»… ذنب أو همّ يكاد يُقنطني؛ أليس ربي الغفور الرحيم؟"}, {"lbl": "الآيات ٥٧ – ٦٦", "q": "قَالَ فَمَا خَطۡبُكُمۡ أَيُّهَا ٱلۡمُرۡسَلُونَ ﴿٥٧﴾ قَالُوٓاْ إِنَّآ أُرۡسِلۡنَآ إِلَىٰ قَوۡمٖ مُّجۡرِمِينَ ﴿٥٨﴾ إِلَّآ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمۡ أَجۡمَعِينَ ﴿٥٩﴾ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَآ إِنَّهَا لَمِنَ ٱلۡغَٰبِرِينَ ﴿٦٠﴾ فَلَمَّا جَآءَ ءَالَ لُوطٍ ٱلۡمُرۡسَلُونَ ﴿٦١﴾ قَالَ إِنَّكُمۡ قَوۡمٞ مُّنكَرُونَ ﴿٦٢﴾ قَالُواْ بَلۡ جِئۡنَٰكَ بِمَا كَانُواْ فِيهِ يَمۡتَرُونَ ﴿٦٣﴾ وَأَتَيۡنَٰكَ بِٱلۡحَقِّ وَإِنَّا لَصَٰدِقُونَ ﴿٦٤﴾ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَٱتَّبِعۡ أَدۡبَٰرَهُمۡ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٞ وَٱمۡضُواْ حَيۡثُ تُؤۡمَرُونَ ﴿٦٥﴾ وَقَضَيۡنَآ إِلَيۡهِ ذَٰلِكَ ٱلۡأَمۡرَ أَنَّ دَابِرَ هَـٰٓؤُلَآءِ مَقۡطُوعٞ مُّصۡبِحِينَ ﴿٦٦﴾", "w": [["فما خطبكم", "ما شأنكم؟"], ["إلى قوم مجرمين", "هم قوم لوط ﵇."], ["إنا لمنجّوهم أجمعين", "لإيمانهم وصالح أعمالهم."], ["الغابرين", "الباقين في العذاب."], ["قوم منكرون", "لا أعرفكم."], ["بما كانوا فيه يمترون", "بالعذاب الذي كانوا يشكّون في وقوعه بهم."], ["حيث تؤمرون", "إلى الشام حيث أُمروا بالخروج إليه."], ["وقضينا إليه ذلك الأمر", "فرغنا إلى لوط من ذلك الأمر، وأوحينا إليه أن دابر هؤلاء مقطوع مصبحين."]], "m": "قال إبراهيم: فما شأنكم أيها المرسلون؟ قالوا: إنا أُرسلنا إلى قوم مجرمين على أنفسهم وعلى غيرهم، هم قوم لوط، إلا آل لوط والمؤمنين معه إنا لمنجّوهم أجمعين، إلا امرأته قضينا إنها من الباقين في العذاب لأنها كافرة مثلهم. ثم انتقلوا إلى مدينة لوط، فلما دخلوا عليه قال: إنكم قوم لا أعرفكم، قالوا: بل جئناك بالعذاب الذي كان قومك يشكّون فيه، وأتيناك بالحق الثابت وإنا لصادقون، فاسرِ بأهلك في جزء من الليل، وامشِ خلفهم وهم أمامك، ولا يلتفت منكم أحد فيرى ما يسوؤه عند نزول العذاب، وامضوا حيث تُؤمرون، إلى الشام. وفرغنا إلى لوط من ذلك الأمر، وأوحينا إليه أن هؤلاء مُهلكون عن آخرهم في الصباح الباكر.", "h": ["التنديد بالإجرام، وبيان عقوبة المجرمين.", "لا قيمة للنسب ولا للمصاهرة ولا عبرة بالقرابة إذا فصل الكفر والإجرام بين الأنساب والأقرباء، فامرأة لوط هلكت مع الهالكين ولم يشفع لها أنها زوجة نبي ورسول.", "مشروعية المشي بالليل لقطع المسافات البعيدة.", "مشروعية مشي المسؤول وكبير القوم وراء الجيش والقافلة لتفقّد أحوالهم، والاطلاع على من يتخلّف منهم لأمر، وكذا كان رسول الله ﷺ يفعل.", "كراهية الإشفاق على الظلمة الهالكين، لقوله: «ولا يلتفت منكم أحد» أي بقلبه."], "k": "«واتبع أدبارهم»… القائد يمشي خلف قومه يتفقّدهم؛ فهل أتفقّد من أنا مسؤول عنهم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (173, 15, 67, 99, 'سورة الحجر ٦٧ – ٩٩', 'هلاك قوم لوط وأصحاب الأيكة والحِجر، و«ولقد آتيناك سبعاً من المثاني»، و«فاصدع بما تؤمر»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 173) = $j$[{"lbl": "الآيات ٦٧ – ٧٩", "q": "وَجَآءَ أَهۡلُ ٱلۡمَدِينَةِ يَسۡتَبۡشِرُونَ ﴿٦٧﴾ قَالَ إِنَّ هَـٰٓؤُلَآءِ ضَيۡفِي فَلَا تَفۡضَحُونِ ﴿٦٨﴾ وَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ ﴿٦٩﴾ قَالُوٓاْ أَوَلَمۡ نَنۡهَكَ عَنِ ٱلۡعَٰلَمِينَ ﴿٧٠﴾ قَالَ هَـٰٓؤُلَآءِ بَنَاتِيٓ إِن كُنتُمۡ فَٰعِلِينَ ﴿٧١﴾ لَعَمۡرُكَ إِنَّهُمۡ لَفِي سَكۡرَتِهِمۡ يَعۡمَهُونَ ﴿٧٢﴾ فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُشۡرِقِينَ ﴿٧٣﴾ فَجَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهِمۡ حِجَارَةٗ مِّن سِجِّيلٍ ﴿٧٤﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡمُتَوَسِّمِينَ ﴿٧٥﴾ وَإِنَّهَا لَبِسَبِيلٖ مُّقِيمٍ ﴿٧٦﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ ﴿٧٧﴾ وَإِن كَانَ أَصۡحَٰبُ ٱلۡأَيۡكَةِ لَظَٰلِمِينَ ﴿٧٨﴾ فَٱنتَقَمۡنَا مِنۡهُمۡ وَإِنَّهُمَا لَبِإِمَامٖ مُّبِينٖ ﴿٧٩﴾", "w": [["وجاء أهل المدينة يستبشرون", "مدينة سدوم، فرحين بطمعهم في إتيان الفاحشة."], ["واتقوا الله ولا تخزون", "لا تذلّوني في انتهاك حرمة ضيفي."], ["أوَلم ننهك عن العالمين", "عن إجارتك لهم واستضافتك."], ["لفي سكرتهم يعمهون", "في غوايتهم وشدة غلمتهم التي أزالت عقولهم."], ["مشرقين", "وقت شروق الشمس."], ["من سجيل", "طين طُبخ بالنار."], ["لآيات للمتوسّمين", "للناظرين المعتبرين."], ["لبسبيل مقيم", "طريق قريش إلى الشام، مقيم دائم ثابت."], ["أصحاب الأيكة", "قوم شعيب ﵇، والأيكة غيضة شجر بقرب مدين."], ["وإنهما لبإمام مبين", "قوم لوط وأصحاب الأيكة لبطريق مبين واضح."]], "m": "وجاء أهل مدينة سدوم فرحين لطمعهم في إتيان الفاحشة، فقال لهم لوط: إن هؤلاء ضيفي فلا تفضحون فيهم، واتقوا الله ولا تذلّوني. قالوا: أوَلم ننهك أن تستضيف أحداً من الناس؟ قال: هؤلاء بناتي فتزوّجوهن إن كنتم فاعلين ما أرشدكم إليه. لعمرك يا رسولنا، أقسم الله بحياته، إنهم لفي غوايتهم التي أذهبت عقولهم يتردّدون حيارى، فأخذتهم صيحة جبريل مع إشراق الشمس، فجعلنا عالي مدنهم سافلها، وأمطرنا عليهم حجارة من طين مطبوخ بالنار. إن في ذلك لآيات للناظرين نظر تفكّر وتأمّل، وإن تلك القرى الهالكة لبطريق ثابت باقٍ يمرّ به أهل مكة إلى الشام، إن في ذلك لعبرة للمؤمنين فلا يقدمون على محارم الله. وإن كان أصحاب الأيكة، قوم شعيب، لظالمين لأنفسهم بعبادة غير الله، فانتقمنا منهم بحرّ شديد يوم الظلّة، وإنهما، قوم لوط وأصحاب الأيكة، لبطريق واضح، طريق قريش إلى الشام، والقصد وعظ قريش وتذكيرها.", "h": ["بيان إهلاك قوم لوط.", "إنكار الفاحشة، وأن أقبح فاحشة تعرفها الإنسانية هي إتيان الذكور.", "بيان دفاع لوط ﵇ عن ضيفه حتى فداهم ببناته.", "شرف النبي ﷺ حيث أقسم الله تعالى بحياته في قوله: «لعمرك».", "الحث على نظر التفكر والاعتبار والتفرّس، فإنه أنفع للعقل البشري.", "بيان نقمة الله تعالى من الظالمين للاعتبار والاتعاظ.", "تقرير نبوة الرسول ﷺ، إذ مثل هذه الأخبار لن تكون إلا عن وحي."], "k": "«إن في ذلك لآيات للمتوسّمين»… حين أمرّ بآثار الهالكين، هل أمرّ معتبراً أم سائحاً لاهياً؟"}, {"lbl": "الآيات ٨٠ – ٨٨", "q": "وَلَقَدۡ كَذَّبَ أَصۡحَٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِينَ ﴿٨٠﴾ وَءَاتَيۡنَٰهُمۡ ءَايَٰتِنَا فَكَانُواْ عَنۡهَا مُعۡرِضِينَ ﴿٨١﴾ وَكَانُواْ يَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتًا ءَامِنِينَ ﴿٨٢﴾ فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُصۡبِحِينَ ﴿٨٣﴾ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ ﴿٨٤﴾ وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّۗ وَإِنَّ ٱلسَّاعَةَ لَأٓتِيَةٞۖ فَٱصۡفَحِ ٱلصَّفۡحَ ٱلۡجَمِيلَ ﴿٨٥﴾ إِنَّ رَبَّكَ هُوَ ٱلۡخَلَّـٰقُ ٱلۡعَلِيمُ ﴿٨٦﴾ وَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعٗا مِّنَ ٱلۡمَثَانِي وَٱلۡقُرۡءَانَ ٱلۡعَظِيمَ ﴿٨٧﴾ لَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ ﴿٨٨﴾", "w": [["أصحاب الحِجر", "قوم صالح، ومنازلهم بين المدينة النبوية والشام."], ["وآتيناهم آياتنا", "في الناقة، وهي أعظم آية."], ["ما أغنى عنهم ما كانوا يكسبون", "من بناء الحصون وجمع الأموال."], ["الصفح الجميل", "الإعراض عنهم إعراضاً لا جزع فيه، وهذا قبل الأمر بالجهاد."], ["سبعاً من المثاني", "هي آيات سورة الفاتحة السبع."], ["أزواجاً منهم", "أصنافاً من الكفار."], ["واخفض جناحك", "ألن جانبك للمؤمنين."]], "m": "هذا موجز قصة أصحاب الحِجر، ثمود قوم صالح: ولقد كذّب أصحاب الحجر المرسلين، ولم يكذّبوا إلا صالحاً، لكن من كذّب رسولاً فقد كذّب عامة الرسل لأن دعوتهم واحدة، وفي هذا موعظة لرسول الله ﷺ ليصبر على تكذيب قومه. وآتيناهم آياتنا في الناقة: خرجت من صخرة، وتشرب ماء البلد يوماً، وتقف أمام كل بيت ليحلب أهله منها، فكانوا عنها معرضين، وكانوا ينحتون من الجبال بيوتاً آمنين، فأخذتهم الصيحة صبيحة اليوم الرابع، فما أغنى عنهم ما كانوا يكسبون من المال وبناء الحصون. وما خلقنا السماوات والأرض وما بينهما إلا بالحق، من أجل أن أُذكر وأُشكر، وإن الساعة لآتية لا محالة ليُجزى كلٌّ بما كسب، فلا تحزن على قومك، واصفح عنهم الصفح الذي لا جزع معه، إن ربك هو الخلّاق العليم. ولقد آتيناك سورة الفاتحة والقرآن العظيم، وهو خير لا يقادر قدره، فلا تمدّنّ عينيك متطلّعاً إلى ما متّعنا به أصنافاً من رجالات قريش من المال والطعام والشراب، ولا تحزن عليهم إن لم يؤمنوا، وألن جانبك للمؤمنين واعطف عليهم، فإن الخير فيهم.", "h": ["إذا أراد الله هلاك أمة فإن قوتها المادية لا تغني عنها شيئاً.", "لم يخلق الله الخلق عبثاً، بل خلقه ليُعبد بالذكر والشكر، فمن عبده نجا، ومن أعرض عن ذكره أذاقه عذاب الخزي في الدنيا والآخرة، أو في الآخرة وهو أشد.", "بيان أن الصفح الجميل هو الذي لا جزع معه.", "بيان أن من أوتي القرآن لم يؤت أحد مثله من الخير قط.", "فضل الفاتحة، إذ هي السبع المثاني.", "على الدعاة إلى الله ألا يلتفتوا إلى ما في أيدي الناس من مال ومتاع، فإن ما آتاهم الله من الإيمان والعلم والتقوى خير مما آتى أولئك من المال والمتاع.", "استحباب لين الجانب للمؤمنين، والعطف عليهم، والرحمة لهم."], "k": "«ولقد آتيناك سبعاً من المثاني والقرآن العظيم»… أوتيت القرآن؛ فلماذا تمتدّ عيني إلى ما في أيدي الناس؟"}, {"lbl": "الآيات ٨٩ – ٩٩", "q": "وَقُلۡ إِنِّيٓ أَنَا ٱلنَّذِيرُ ٱلۡمُبِينُ ﴿٨٩﴾ كَمَآ أَنزَلۡنَا عَلَى ٱلۡمُقۡتَسِمِينَ ﴿٩٠﴾ ٱلَّذِينَ جَعَلُواْ ٱلۡقُرۡءَانَ عِضِينَ ﴿٩١﴾ فَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِينَ ﴿٩٢﴾ عَمَّا كَانُواْ يَعۡمَلُونَ ﴿٩٣﴾ فَٱصۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ ﴿٩٤﴾ إِنَّا كَفَيۡنَٰكَ ٱلۡمُسۡتَهۡزِءِينَ ﴿٩٥﴾ ٱلَّذِينَ يَجۡعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۚ فَسَوۡفَ يَعۡلَمُونَ ﴿٩٦﴾ وَلَقَدۡ نَعۡلَمُ أَنَّكَ يَضِيقُ صَدۡرُكَ بِمَا يَقُولُونَ ﴿٩٧﴾ فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَكُن مِّنَ ٱلسَّـٰجِدِينَ ﴿٩٨﴾ وَٱعۡبُدۡ رَبَّكَ حَتَّىٰ يَأۡتِيَكَ ٱلۡيَقِينُ ﴿٩٩﴾", "w": [["النذير المبين", "البيّن النذارة."], ["على المقتسمين", "الذين قسموا كتاب الله فقالوا: فيه شعر، وسحر."], ["جعلوا القرآن عضين", "جمع عِضة، وهي القطعة والجزء من الشيء."], ["فاصدع بما تؤمر", "اجهر به واعرضه كما أمرك ربك."], ["يضيق صدرك بما يقولون", "من الاستهزاء بك والتكذيب لك."], ["حتى يأتيك اليقين", "الموت، أي إلى أن تُتوفّى وأنت تعبد ربك."]], "m": "ما زال السياق في إرشاد الرسول ﷺ: وقل لقومك إني أنا النذير البيّن النذارة أن ينزل بكم عذاب الله إن أصررتم على الشرك، عذاباً كالذي أنزله على المقتسمين: الذين قسموا التوراة والإنجيل فآمنوا ببعض وكفروا ببعض، والذين تقاسموا أن يبيّتوا صالحاً، والذين جعلوا القرآن أجزاءً فقالوا: شعر وسحر وكهانة، والذين قسموا طرق مكة يصدّون عن سبيل الله من جاء يريد الإسلام. فوربك لنسألنّهم أجمعين يوم القيامة عما كانوا يعملون، فلا يهولنّك أمرهم. فاجهر بدعوة لا إله إلا الله محمد رسول الله، وأعرض عن المشركين ولا تبال بهم، إنا كفيناك المستهزئين، كالوليد بن المغيرة والعاص بن وائل، ماتوا بآفات مختلفة في أمد يسير. ولقد نعلم أنك يضيق صدرك بما يقولون من الاستهزاء، فنرشدك إلى ما يخفّف عنك: فسبّح بحمد ربك، أكثر من قول: سبحان الله وبحمده، وكن من المصلّين، فافزع عند الضيق إلى الصلاة، وكان ﷺ إذا حزبه أمر فزع إلى الصلاة، واعبد ربك حتى يأتيك الموت.", "h": ["حرمة الاختلاف في كتاب الله تعالى على نحو ما اختلف فيه أهل الكتاب.", "فضل التسبيح بجملة: سبحان الله وبحمده، ومن قالها مائة مرة غُفرت ذنوبه ولو كانت مثل زبد البحر، وهذا مروي في الصحيح.", "مشروعية صلاة الحاجة، فمن حزبه أمر أو ضاق به فليصلّ صلاة يفرّج الله تعالى بها ما به أو يقضي حاجته إن شاء، وهو العليم الحكيم."], "k": "«فسبّح بحمد ربك وكن من الساجدين»… حين يضيق صدري، هل أفزع إلى الصلاة قبل أي أحد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 173;
insert into public.tdb_cards(topic, i, body) select 173, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٧ – ٧٩", "q": "وَجَآءَ أَهۡلُ ٱلۡمَدِينَةِ يَسۡتَبۡشِرُونَ ﴿٦٧﴾ قَالَ إِنَّ هَـٰٓؤُلَآءِ ضَيۡفِي فَلَا تَفۡضَحُونِ ﴿٦٨﴾ وَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ ﴿٦٩﴾ قَالُوٓاْ أَوَلَمۡ نَنۡهَكَ عَنِ ٱلۡعَٰلَمِينَ ﴿٧٠﴾ قَالَ هَـٰٓؤُلَآءِ بَنَاتِيٓ إِن كُنتُمۡ فَٰعِلِينَ ﴿٧١﴾ لَعَمۡرُكَ إِنَّهُمۡ لَفِي سَكۡرَتِهِمۡ يَعۡمَهُونَ ﴿٧٢﴾ فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُشۡرِقِينَ ﴿٧٣﴾ فَجَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهِمۡ حِجَارَةٗ مِّن سِجِّيلٍ ﴿٧٤﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّلۡمُتَوَسِّمِينَ ﴿٧٥﴾ وَإِنَّهَا لَبِسَبِيلٖ مُّقِيمٍ ﴿٧٦﴾ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّلۡمُؤۡمِنِينَ ﴿٧٧﴾ وَإِن كَانَ أَصۡحَٰبُ ٱلۡأَيۡكَةِ لَظَٰلِمِينَ ﴿٧٨﴾ فَٱنتَقَمۡنَا مِنۡهُمۡ وَإِنَّهُمَا لَبِإِمَامٖ مُّبِينٖ ﴿٧٩﴾", "w": [["وجاء أهل المدينة يستبشرون", "مدينة سدوم، فرحين بطمعهم في إتيان الفاحشة."], ["واتقوا الله ولا تخزون", "لا تذلّوني في انتهاك حرمة ضيفي."], ["أوَلم ننهك عن العالمين", "عن إجارتك لهم واستضافتك."], ["لفي سكرتهم يعمهون", "في غوايتهم وشدة غلمتهم التي أزالت عقولهم."], ["مشرقين", "وقت شروق الشمس."], ["من سجيل", "طين طُبخ بالنار."], ["لآيات للمتوسّمين", "للناظرين المعتبرين."], ["لبسبيل مقيم", "طريق قريش إلى الشام، مقيم دائم ثابت."], ["أصحاب الأيكة", "قوم شعيب ﵇، والأيكة غيضة شجر بقرب مدين."], ["وإنهما لبإمام مبين", "قوم لوط وأصحاب الأيكة لبطريق مبين واضح."]], "m": "وجاء أهل مدينة سدوم فرحين لطمعهم في إتيان الفاحشة، فقال لهم لوط: إن هؤلاء ضيفي فلا تفضحون فيهم، واتقوا الله ولا تذلّوني. قالوا: أوَلم ننهك أن تستضيف أحداً من الناس؟ قال: هؤلاء بناتي فتزوّجوهن إن كنتم فاعلين ما أرشدكم إليه. لعمرك يا رسولنا، أقسم الله بحياته، إنهم لفي غوايتهم التي أذهبت عقولهم يتردّدون حيارى، فأخذتهم صيحة جبريل مع إشراق الشمس، فجعلنا عالي مدنهم سافلها، وأمطرنا عليهم حجارة من طين مطبوخ بالنار. إن في ذلك لآيات للناظرين نظر تفكّر وتأمّل، وإن تلك القرى الهالكة لبطريق ثابت باقٍ يمرّ به أهل مكة إلى الشام، إن في ذلك لعبرة للمؤمنين فلا يقدمون على محارم الله. وإن كان أصحاب الأيكة، قوم شعيب، لظالمين لأنفسهم بعبادة غير الله، فانتقمنا منهم بحرّ شديد يوم الظلّة، وإنهما، قوم لوط وأصحاب الأيكة، لبطريق واضح، طريق قريش إلى الشام، والقصد وعظ قريش وتذكيرها.", "h": ["بيان إهلاك قوم لوط.", "إنكار الفاحشة، وأن أقبح فاحشة تعرفها الإنسانية هي إتيان الذكور.", "بيان دفاع لوط ﵇ عن ضيفه حتى فداهم ببناته.", "شرف النبي ﷺ حيث أقسم الله تعالى بحياته في قوله: «لعمرك».", "الحث على نظر التفكر والاعتبار والتفرّس، فإنه أنفع للعقل البشري.", "بيان نقمة الله تعالى من الظالمين للاعتبار والاتعاظ.", "تقرير نبوة الرسول ﷺ، إذ مثل هذه الأخبار لن تكون إلا عن وحي."], "k": "«إن في ذلك لآيات للمتوسّمين»… حين أمرّ بآثار الهالكين، هل أمرّ معتبراً أم سائحاً لاهياً؟"}, {"lbl": "الآيات ٨٠ – ٨٨", "q": "وَلَقَدۡ كَذَّبَ أَصۡحَٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِينَ ﴿٨٠﴾ وَءَاتَيۡنَٰهُمۡ ءَايَٰتِنَا فَكَانُواْ عَنۡهَا مُعۡرِضِينَ ﴿٨١﴾ وَكَانُواْ يَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُيُوتًا ءَامِنِينَ ﴿٨٢﴾ فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُصۡبِحِينَ ﴿٨٣﴾ فَمَآ أَغۡنَىٰ عَنۡهُم مَّا كَانُواْ يَكۡسِبُونَ ﴿٨٤﴾ وَمَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّۗ وَإِنَّ ٱلسَّاعَةَ لَأٓتِيَةٞۖ فَٱصۡفَحِ ٱلصَّفۡحَ ٱلۡجَمِيلَ ﴿٨٥﴾ إِنَّ رَبَّكَ هُوَ ٱلۡخَلَّـٰقُ ٱلۡعَلِيمُ ﴿٨٦﴾ وَلَقَدۡ ءَاتَيۡنَٰكَ سَبۡعٗا مِّنَ ٱلۡمَثَانِي وَٱلۡقُرۡءَانَ ٱلۡعَظِيمَ ﴿٨٧﴾ لَا تَمُدَّنَّ عَيۡنَيۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦٓ أَزۡوَٰجٗا مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِينَ ﴿٨٨﴾", "w": [["أصحاب الحِجر", "قوم صالح، ومنازلهم بين المدينة النبوية والشام."], ["وآتيناهم آياتنا", "في الناقة، وهي أعظم آية."], ["ما أغنى عنهم ما كانوا يكسبون", "من بناء الحصون وجمع الأموال."], ["الصفح الجميل", "الإعراض عنهم إعراضاً لا جزع فيه، وهذا قبل الأمر بالجهاد."], ["سبعاً من المثاني", "هي آيات سورة الفاتحة السبع."], ["أزواجاً منهم", "أصنافاً من الكفار."], ["واخفض جناحك", "ألن جانبك للمؤمنين."]], "m": "هذا موجز قصة أصحاب الحِجر، ثمود قوم صالح: ولقد كذّب أصحاب الحجر المرسلين، ولم يكذّبوا إلا صالحاً، لكن من كذّب رسولاً فقد كذّب عامة الرسل لأن دعوتهم واحدة، وفي هذا موعظة لرسول الله ﷺ ليصبر على تكذيب قومه. وآتيناهم آياتنا في الناقة: خرجت من صخرة، وتشرب ماء البلد يوماً، وتقف أمام كل بيت ليحلب أهله منها، فكانوا عنها معرضين، وكانوا ينحتون من الجبال بيوتاً آمنين، فأخذتهم الصيحة صبيحة اليوم الرابع، فما أغنى عنهم ما كانوا يكسبون من المال وبناء الحصون. وما خلقنا السماوات والأرض وما بينهما إلا بالحق، من أجل أن أُذكر وأُشكر، وإن الساعة لآتية لا محالة ليُجزى كلٌّ بما كسب، فلا تحزن على قومك، واصفح عنهم الصفح الذي لا جزع معه، إن ربك هو الخلّاق العليم. ولقد آتيناك سورة الفاتحة والقرآن العظيم، وهو خير لا يقادر قدره، فلا تمدّنّ عينيك متطلّعاً إلى ما متّعنا به أصنافاً من رجالات قريش من المال والطعام والشراب، ولا تحزن عليهم إن لم يؤمنوا، وألن جانبك للمؤمنين واعطف عليهم، فإن الخير فيهم.", "h": ["إذا أراد الله هلاك أمة فإن قوتها المادية لا تغني عنها شيئاً.", "لم يخلق الله الخلق عبثاً، بل خلقه ليُعبد بالذكر والشكر، فمن عبده نجا، ومن أعرض عن ذكره أذاقه عذاب الخزي في الدنيا والآخرة، أو في الآخرة وهو أشد.", "بيان أن الصفح الجميل هو الذي لا جزع معه.", "بيان أن من أوتي القرآن لم يؤت أحد مثله من الخير قط.", "فضل الفاتحة، إذ هي السبع المثاني.", "على الدعاة إلى الله ألا يلتفتوا إلى ما في أيدي الناس من مال ومتاع، فإن ما آتاهم الله من الإيمان والعلم والتقوى خير مما آتى أولئك من المال والمتاع.", "استحباب لين الجانب للمؤمنين، والعطف عليهم، والرحمة لهم."], "k": "«ولقد آتيناك سبعاً من المثاني والقرآن العظيم»… أوتيت القرآن؛ فلماذا تمتدّ عيني إلى ما في أيدي الناس؟"}, {"lbl": "الآيات ٨٩ – ٩٩", "q": "وَقُلۡ إِنِّيٓ أَنَا ٱلنَّذِيرُ ٱلۡمُبِينُ ﴿٨٩﴾ كَمَآ أَنزَلۡنَا عَلَى ٱلۡمُقۡتَسِمِينَ ﴿٩٠﴾ ٱلَّذِينَ جَعَلُواْ ٱلۡقُرۡءَانَ عِضِينَ ﴿٩١﴾ فَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِينَ ﴿٩٢﴾ عَمَّا كَانُواْ يَعۡمَلُونَ ﴿٩٣﴾ فَٱصۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِينَ ﴿٩٤﴾ إِنَّا كَفَيۡنَٰكَ ٱلۡمُسۡتَهۡزِءِينَ ﴿٩٥﴾ ٱلَّذِينَ يَجۡعَلُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَۚ فَسَوۡفَ يَعۡلَمُونَ ﴿٩٦﴾ وَلَقَدۡ نَعۡلَمُ أَنَّكَ يَضِيقُ صَدۡرُكَ بِمَا يَقُولُونَ ﴿٩٧﴾ فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَكُن مِّنَ ٱلسَّـٰجِدِينَ ﴿٩٨﴾ وَٱعۡبُدۡ رَبَّكَ حَتَّىٰ يَأۡتِيَكَ ٱلۡيَقِينُ ﴿٩٩﴾", "w": [["النذير المبين", "البيّن النذارة."], ["على المقتسمين", "الذين قسموا كتاب الله فقالوا: فيه شعر، وسحر."], ["جعلوا القرآن عضين", "جمع عِضة، وهي القطعة والجزء من الشيء."], ["فاصدع بما تؤمر", "اجهر به واعرضه كما أمرك ربك."], ["يضيق صدرك بما يقولون", "من الاستهزاء بك والتكذيب لك."], ["حتى يأتيك اليقين", "الموت، أي إلى أن تُتوفّى وأنت تعبد ربك."]], "m": "ما زال السياق في إرشاد الرسول ﷺ: وقل لقومك إني أنا النذير البيّن النذارة أن ينزل بكم عذاب الله إن أصررتم على الشرك، عذاباً كالذي أنزله على المقتسمين: الذين قسموا التوراة والإنجيل فآمنوا ببعض وكفروا ببعض، والذين تقاسموا أن يبيّتوا صالحاً، والذين جعلوا القرآن أجزاءً فقالوا: شعر وسحر وكهانة، والذين قسموا طرق مكة يصدّون عن سبيل الله من جاء يريد الإسلام. فوربك لنسألنّهم أجمعين يوم القيامة عما كانوا يعملون، فلا يهولنّك أمرهم. فاجهر بدعوة لا إله إلا الله محمد رسول الله، وأعرض عن المشركين ولا تبال بهم، إنا كفيناك المستهزئين، كالوليد بن المغيرة والعاص بن وائل، ماتوا بآفات مختلفة في أمد يسير. ولقد نعلم أنك يضيق صدرك بما يقولون من الاستهزاء، فنرشدك إلى ما يخفّف عنك: فسبّح بحمد ربك، أكثر من قول: سبحان الله وبحمده، وكن من المصلّين، فافزع عند الضيق إلى الصلاة، وكان ﷺ إذا حزبه أمر فزع إلى الصلاة، واعبد ربك حتى يأتيك الموت.", "h": ["حرمة الاختلاف في كتاب الله تعالى على نحو ما اختلف فيه أهل الكتاب.", "فضل التسبيح بجملة: سبحان الله وبحمده، ومن قالها مائة مرة غُفرت ذنوبه ولو كانت مثل زبد البحر، وهذا مروي في الصحيح.", "مشروعية صلاة الحاجة، فمن حزبه أمر أو ضاق به فليصلّ صلاة يفرّج الله تعالى بها ما به أو يقضي حاجته إن شاء، وهو العليم الحكيم."], "k": "«فسبّح بحمد ربك وكن من الساجدين»… حين يضيق صدري، هل أفزع إلى الصلاة قبل أي أحد؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (174, 16, 1, 13, 'سورة النحل ١ – ١٣', '«أتى أمر الله فلا تستعجلوه»، ونعم الله في الأنعام والمراكب والماء والنجوم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 174) = $j$[{"lbl": "الآيات ١ – ٧", "q": "أَتَىٰٓ أَمۡرُ ٱللَّهِ فَلَا تَسۡتَعۡجِلُوهُۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿١﴾ يُنَزِّلُ ٱلۡمَلَـٰٓئِكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ أَنۡ أَنذِرُوٓاْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ ﴿٢﴾ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ تَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٣﴾ خَلَقَ ٱلۡإِنسَٰنَ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ ﴿٤﴾ وَٱلۡأَنۡعَٰمَ خَلَقَهَاۖ لَكُمۡ فِيهَا دِفۡءٞ وَمَنَٰفِعُ وَمِنۡهَا تَأۡكُلُونَ ﴿٥﴾ وَلَكُمۡ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسۡرَحُونَ ﴿٦﴾ وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَدٖ لَّمۡ تَكُونُواْ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلۡأَنفُسِۚ إِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٞ ﴿٧﴾", "w": [["أتى أمر الله", "دنا وقرب أمر الله بعذابكم أيها المشركون فلا تستعجلوه."], ["ينزّل الملائكة بالروح", "بالوحي الذي به حياة الأرواح، والمراد من الملائكة جبريل."], ["خلق الإنسان من نطفة", "من قطرة من المني."], ["دفء ومنافع", "ما تستدفئون به، ومنافع من اللبن واللحم وغيرهما."], ["حين تريحون", "حين تردّونها من مراعيها إلى مراحها."], ["وحين تسرحون", "حين تخرجونها من مراحها إلى مسارحها."], ["إلا بشق الأنفس", "بجهد الأنفس ومشقة عظيمة."]], "m": "استعجل المشركون بمكة العذاب غير مرة، فقال تعالى: أتى أمر الله بعذابكم أيها المستعجلون، لقد دنا وقرب، فالنضر بن الحارث القائل: «فأمطر علينا حجارة من السماء» هلك ببدر بعد سنيات قلائل، وعذاب يوم القيامة قريب، عبّر عنه بالماضي لتحقق وقوعه، فلا تستعجلوه، سبحانه وتعالى عما يشركون. ينزّل جبريل بالوحي من أمره على من يشاء من عباده، وهو محمد ﷺ: أن أنذروا المشركين عاقبة شركهم، أنه لا إله إلا أنا فاتقون بترك الشرك والمعاصي. خلق السماوات والأرض بالحق وحده دون معين، فحقّ أن يُعبد لا تلك الآلهة الميتة. خلق الإنسان من أضعف شيء، قطرة المني، فإذا هو بعد أن ربّاه خصيم مبين يجادل ربه ويقول: من يحيي العظام وهي رميم؟ والأنعام، الإبل والبقر والغنم، خلقها لكم: فيها دفء تصنعون من صوفها ووبرها الملابس والفرش، ومنافع كاللبن والزبد والسمن والنسل، ومنها تأكلون، ولكم فيها جمال حين تردّونها مساءً وحين تخرجونها صباحاً، وتحمل أثقالكم إلى بلد لم تكونوا بالغيه إلا بجهد ومشقة عظيمة، فالإبل في الصحراء كالسفن في البحر، إن ربكم لرؤوف رحيم، ولولا لطفه بالإنسان لما عاش ساعة.", "h": ["قرب يوم القيامة، فلا معنى لاستعجاله، فإنه آتٍ لا محالة، وكل آت قريب.", "تسمية الوحي بالروح من أجل أنه يحيي القلوب كما تحيا الأجسام بالأرواح.", "تقرير التوحيد والنبوة والبعث الآخر بذكر مظاهر القدرة الإلهية والعلم والحكمة والرأفة."], "k": "«إن ربكم لرؤوف رحيم»… في كل نعمة استعملتها اليوم أثر من رأفته؛ فهل لاحظت ذلك؟"}, {"lbl": "الآيات ٨ – ١٣", "q": "وَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةٗۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ ﴿٨﴾ وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ وَمِنۡهَا جَآئِرٞۚ وَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ ﴿٩﴾ هُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗۖ لَّكُم مِّنۡهُ شَرَابٞ وَمِنۡهُ شَجَرٞ فِيهِ تُسِيمُونَ ﴿١٠﴾ يُنۢبِتُ لَكُم بِهِ ٱلزَّرۡعَ وَٱلزَّيۡتُونَ وَٱلنَّخِيلَ وَٱلۡأَعۡنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿١١﴾ وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ وَٱلنُّجُومُ مُسَخَّرَٰتُۢ بِأَمۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ﴿١٢﴾ وَمَا ذَرَأَ لَكُمۡ فِي ٱلۡأَرۡضِ مُخۡتَلِفًا أَلۡوَٰنُهُۥٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَذَّكَّرُونَ ﴿١٣﴾", "w": [["ويخلق ما لا تعلمون", "من سائر الحيوانات، ومن ذلك السيارات والطائرات والقطارات."], ["وعلى الله قصد السبيل", "تفضّلاً منه وامتناناً ببيان السبيل القاصد، وهي الإسلام."], ["ومنها جائر", "عادل عن القصد، وهو سائر الملل كاليهودية والنصرانية."], ["ومنه شجر", "وبسببه يكون الشجر، وهو هنا عام في سائر النباتات."], ["فيه تسيمون", "ترعون مواشيكم."], ["مسخّرات بأمره", "بإذنه وقدرته."], ["وما ذرأ لكم في الأرض", "ما خلق لكم في الأرض من الحيوان والنباتات المختلفة."]], "m": "ما زال السياق في تقرير التوحيد بذكر مظاهر قدرة الله وعلمه وحكمته ورحمته: وخلق الخيل والبغال والحمير لتركبوها وزينة لكم، ويخلق ما لا تعلمون من مركوب وغير مركوب، ومن المركوب هذه السيارات والطائرات والقطارات، فهل يليق بعباده أن يكفروه أو يشركوا به؟ ومن إفضاله أن بيّن السبيل القاصد الموصل إلى رضاه، وهو الإسلام، وما عداه من الملل سبل جائرة عن العدل، ولو شاء لهداكم أجمعين، إلا أن حكمته اقتضت أن يهدي من رغب في الهداية، ويضل من رغب في الضلال. هو الذي أنزل من السماء ماءً لكم منه شراب، ومنه شجر ونبات فيه ترعون مواشيكم، ينبت لكم به الزرع والزيتون والنخيل والأعناب ومن كل الثمرات، إن في ذلك لآية لقوم يتفكرون، أما أشباه البهائم فلا يجدون في الكون آية. وسخّر لكم الليل للسكون والنهار للعمل، والشمس والقمر للضوء والحرارة ومعرفة الحساب، والنجوم مسخّرات بأمره للاهتداء بها وزينة للسماء، إن في ذلك لآيات لقوم يعقلون، وما خلق لكم في الأرض من إنسان وحيوان ونبات مختلفاً ألوانه ومنافعه، إن في ذلك لآية لقوم يتذكّرون فيعبدونه وحده.", "h": ["كون الخيل والبغال والحمير خُلقت للركوب والزينة لا ينفي منفعة أخرى فيها، وهي أكل لحوم الخيل، لثبوت السنة بإباحة لحوم الخيل، ومنع لحوم البغال والحمير.", "الإسلام هو السبيل التي بيّنها الله تعالى فضلاً منه ورحمة، وما عداه فهي سبل جائرة عن العدل والحق.", "فضيلة التفكّر والتذكّر والتعقّل، وذم أضدادها، لأن الآيات الكونية كالآيات القرآنية، إذا لم يتفكر فيها العبد لا يهتدي إلى معرفة الحق المنشود، وهو معرفة الله تعالى ليعبده بالذكر والشكر وحده."], "k": "«ويخلق ما لا تعلمون»… السيارة التي أركبها من نعمه؛ فهل أشكره عليها أم أعدّها من كسبي وحدي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 174;
insert into public.tdb_cards(topic, i, body) select 174, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٧", "q": "أَتَىٰٓ أَمۡرُ ٱللَّهِ فَلَا تَسۡتَعۡجِلُوهُۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿١﴾ يُنَزِّلُ ٱلۡمَلَـٰٓئِكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ أَنۡ أَنذِرُوٓاْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ ﴿٢﴾ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ تَعَٰلَىٰ عَمَّا يُشۡرِكُونَ ﴿٣﴾ خَلَقَ ٱلۡإِنسَٰنَ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ ﴿٤﴾ وَٱلۡأَنۡعَٰمَ خَلَقَهَاۖ لَكُمۡ فِيهَا دِفۡءٞ وَمَنَٰفِعُ وَمِنۡهَا تَأۡكُلُونَ ﴿٥﴾ وَلَكُمۡ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسۡرَحُونَ ﴿٦﴾ وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَدٖ لَّمۡ تَكُونُواْ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلۡأَنفُسِۚ إِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٞ ﴿٧﴾", "w": [["أتى أمر الله", "دنا وقرب أمر الله بعذابكم أيها المشركون فلا تستعجلوه."], ["ينزّل الملائكة بالروح", "بالوحي الذي به حياة الأرواح، والمراد من الملائكة جبريل."], ["خلق الإنسان من نطفة", "من قطرة من المني."], ["دفء ومنافع", "ما تستدفئون به، ومنافع من اللبن واللحم وغيرهما."], ["حين تريحون", "حين تردّونها من مراعيها إلى مراحها."], ["وحين تسرحون", "حين تخرجونها من مراحها إلى مسارحها."], ["إلا بشق الأنفس", "بجهد الأنفس ومشقة عظيمة."]], "m": "استعجل المشركون بمكة العذاب غير مرة، فقال تعالى: أتى أمر الله بعذابكم أيها المستعجلون، لقد دنا وقرب، فالنضر بن الحارث القائل: «فأمطر علينا حجارة من السماء» هلك ببدر بعد سنيات قلائل، وعذاب يوم القيامة قريب، عبّر عنه بالماضي لتحقق وقوعه، فلا تستعجلوه، سبحانه وتعالى عما يشركون. ينزّل جبريل بالوحي من أمره على من يشاء من عباده، وهو محمد ﷺ: أن أنذروا المشركين عاقبة شركهم، أنه لا إله إلا أنا فاتقون بترك الشرك والمعاصي. خلق السماوات والأرض بالحق وحده دون معين، فحقّ أن يُعبد لا تلك الآلهة الميتة. خلق الإنسان من أضعف شيء، قطرة المني، فإذا هو بعد أن ربّاه خصيم مبين يجادل ربه ويقول: من يحيي العظام وهي رميم؟ والأنعام، الإبل والبقر والغنم، خلقها لكم: فيها دفء تصنعون من صوفها ووبرها الملابس والفرش، ومنافع كاللبن والزبد والسمن والنسل، ومنها تأكلون، ولكم فيها جمال حين تردّونها مساءً وحين تخرجونها صباحاً، وتحمل أثقالكم إلى بلد لم تكونوا بالغيه إلا بجهد ومشقة عظيمة، فالإبل في الصحراء كالسفن في البحر، إن ربكم لرؤوف رحيم، ولولا لطفه بالإنسان لما عاش ساعة.", "h": ["قرب يوم القيامة، فلا معنى لاستعجاله، فإنه آتٍ لا محالة، وكل آت قريب.", "تسمية الوحي بالروح من أجل أنه يحيي القلوب كما تحيا الأجسام بالأرواح.", "تقرير التوحيد والنبوة والبعث الآخر بذكر مظاهر القدرة الإلهية والعلم والحكمة والرأفة."], "k": "«إن ربكم لرؤوف رحيم»… في كل نعمة استعملتها اليوم أثر من رأفته؛ فهل لاحظت ذلك؟"}, {"lbl": "الآيات ٨ – ١٣", "q": "وَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةٗۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ ﴿٨﴾ وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ وَمِنۡهَا جَآئِرٞۚ وَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ ﴿٩﴾ هُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗۖ لَّكُم مِّنۡهُ شَرَابٞ وَمِنۡهُ شَجَرٞ فِيهِ تُسِيمُونَ ﴿١٠﴾ يُنۢبِتُ لَكُم بِهِ ٱلزَّرۡعَ وَٱلزَّيۡتُونَ وَٱلنَّخِيلَ وَٱلۡأَعۡنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿١١﴾ وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ وَٱلنُّجُومُ مُسَخَّرَٰتُۢ بِأَمۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ﴿١٢﴾ وَمَا ذَرَأَ لَكُمۡ فِي ٱلۡأَرۡضِ مُخۡتَلِفًا أَلۡوَٰنُهُۥٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَذَّكَّرُونَ ﴿١٣﴾", "w": [["ويخلق ما لا تعلمون", "من سائر الحيوانات، ومن ذلك السيارات والطائرات والقطارات."], ["وعلى الله قصد السبيل", "تفضّلاً منه وامتناناً ببيان السبيل القاصد، وهي الإسلام."], ["ومنها جائر", "عادل عن القصد، وهو سائر الملل كاليهودية والنصرانية."], ["ومنه شجر", "وبسببه يكون الشجر، وهو هنا عام في سائر النباتات."], ["فيه تسيمون", "ترعون مواشيكم."], ["مسخّرات بأمره", "بإذنه وقدرته."], ["وما ذرأ لكم في الأرض", "ما خلق لكم في الأرض من الحيوان والنباتات المختلفة."]], "m": "ما زال السياق في تقرير التوحيد بذكر مظاهر قدرة الله وعلمه وحكمته ورحمته: وخلق الخيل والبغال والحمير لتركبوها وزينة لكم، ويخلق ما لا تعلمون من مركوب وغير مركوب، ومن المركوب هذه السيارات والطائرات والقطارات، فهل يليق بعباده أن يكفروه أو يشركوا به؟ ومن إفضاله أن بيّن السبيل القاصد الموصل إلى رضاه، وهو الإسلام، وما عداه من الملل سبل جائرة عن العدل، ولو شاء لهداكم أجمعين، إلا أن حكمته اقتضت أن يهدي من رغب في الهداية، ويضل من رغب في الضلال. هو الذي أنزل من السماء ماءً لكم منه شراب، ومنه شجر ونبات فيه ترعون مواشيكم، ينبت لكم به الزرع والزيتون والنخيل والأعناب ومن كل الثمرات، إن في ذلك لآية لقوم يتفكرون، أما أشباه البهائم فلا يجدون في الكون آية. وسخّر لكم الليل للسكون والنهار للعمل، والشمس والقمر للضوء والحرارة ومعرفة الحساب، والنجوم مسخّرات بأمره للاهتداء بها وزينة للسماء، إن في ذلك لآيات لقوم يعقلون، وما خلق لكم في الأرض من إنسان وحيوان ونبات مختلفاً ألوانه ومنافعه، إن في ذلك لآية لقوم يتذكّرون فيعبدونه وحده.", "h": ["كون الخيل والبغال والحمير خُلقت للركوب والزينة لا ينفي منفعة أخرى فيها، وهي أكل لحوم الخيل، لثبوت السنة بإباحة لحوم الخيل، ومنع لحوم البغال والحمير.", "الإسلام هو السبيل التي بيّنها الله تعالى فضلاً منه ورحمة، وما عداه فهي سبل جائرة عن العدل والحق.", "فضيلة التفكّر والتذكّر والتعقّل، وذم أضدادها، لأن الآيات الكونية كالآيات القرآنية، إذا لم يتفكر فيها العبد لا يهتدي إلى معرفة الحق المنشود، وهو معرفة الله تعالى ليعبده بالذكر والشكر وحده."], "k": "«ويخلق ما لا تعلمون»… السيارة التي أركبها من نعمه؛ فهل أشكره عليها أم أعدّها من كسبي وحدي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (175, 16, 14, 25, 'سورة النحل ١٤ – ٢٥', 'تسخير البحر، و«أفمن يخلق كمن لا يخلق»، وأوزار من يصدّ عن سبيل الله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 175) = $j$[{"lbl": "الآيات ١٤ – ١٩", "q": "وَهُوَ ٱلَّذِي سَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُواْ مِنۡهُ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُواْ مِنۡهُ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ﴿١٤﴾ وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَأَنۡهَٰرٗا وَسُبُلٗا لَّعَلَّكُمۡ تَهۡتَدُونَ ﴿١٥﴾ وَعَلَٰمَٰتٖۚ وَبِٱلنَّجۡمِ هُمۡ يَهۡتَدُونَ ﴿١٦﴾ أَفَمَن يَخۡلُقُ كَمَن لَّا يَخۡلُقُۚ أَفَلَا تَذَكَّرُونَ ﴿١٧﴾ وَإِن تَعُدُّواْ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱللَّهَ لَغَفُورٞ رَّحِيمٞ ﴿١٨﴾ وَٱللَّهُ يَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَ ﴿١٩﴾", "w": [["حلية تلبسونها", "هي اللؤلؤ والمرجان."], ["مواخر فيه", "تشقّه بجريها فيه مقبلة ومدبرة."], ["أن تميد بكم", "تميل وتتحرك فيخرب ما عليها ويسقط."], ["لا تحصوها", "عدّاً فتضبطوها، فضلاً عن شكرها."], ["ما تسرّون وما تعلنون", "من المكر بالنبي ﷺ وأذاه، والله يعلم كل سر وعلانية في أي أحد."]], "m": "وهو الذي سخّر لكم البحر، كل ماء غمر كثير عذباً أو ملحاً، ويسّر الخوض فيه وجري السفن عليه، لتصيدوا منه السمك فتأكلوه لحماً طرياً، وتستخرجوا منه اللؤلؤ والمرجان حلية لنسائكم، وترى السفن تشقّ الماء ذاهبة وجائية، ولتطلبوا الرزق بالتجارة بنقل البضائع من إقليم إلى إقليم، لعلكم تشكرون الله بحمده والاعتراف بنعمته وصرفها في مرضاته. وألقى في الأرض جبالاً ثوابت كي لا تميد بكم، إذ لو كانت تتحرك لما استقام العيش عليها، وأجرى أنهاراً كالنيل والفرات، وطرقاً لعلكم تهتدون إلى منازلكم، وعلامات كالهضاب والأودية، وبالنجوم يهتدون في ظلمات البر والبحر. أفمن يخلق ويرزق ويدبّر، وهو الله، كمن لا يخلق، كالأحجار والأوثان؟ أفلا تذكّرون فتتوبوا قبل أن يأتيكم العذاب؟ وإن تعدّوا نعمة الله لا تحصوها، فضلاً عن شكرها، إن الله لغفور رحيم، ولولا ذلك لآخذكم على تقصيركم في شكره. والله يعلم ما تسرّون وما تعلنون، وفي هذا تهديد لكفار مكة الماكرين برسوله.", "h": ["بيان العلة في الرزق، وأنها الشكر، فالله سبحانه يرزق ليُشكر.", "إباحة أكل الحوت وكل دواب البحر.", "لا زكاة في اللؤلؤ والمرجان، لأنه من حلية النساء.", "المقارنة بين الحي الخلّاق العليم، وبين الأصنام الميتة المخلوقة، لتقرير بطلان عبادتها.", "عجز الإنسان عن شكر نعم الله تعالى يتطلّب منه أن يشكر ما يمكنه منها، وكلمة «الحمد لله» تُعدّ رأس الشكر، والاعتراف بالعجز عن الشكر من الشكر، والشكر صرف النعم فيما من أجله أنعم الله تعالى بها."], "k": "«لتأكلوا منه لحماً طرياً»… طعامي اليوم من رزقه؛ فهل جعلته عوناً على طاعته؟"}, {"lbl": "الآيات ٢٠ – ٢٥", "q": "وَٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ لَا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ ﴿٢٠﴾ أَمۡوَٰتٌ غَيۡرُ أَحۡيَآءٖۖ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ ﴿٢١﴾ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۚ فَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ قُلُوبُهُم مُّنكِرَةٞ وَهُم مُّسۡتَكۡبِرُونَ ﴿٢٢﴾ لَا جَرَمَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡتَكۡبِرِينَ ﴿٢٣﴾ وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمۡ قَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٢٤﴾ لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ أَلَا سَآءَ مَا يَزِرُونَ ﴿٢٥﴾", "w": [["وهم يُخلقون", "يُصوَّرون من الحجارة وغيرها."], ["وما يشعرون أيان يُبعثون", "لا تشعر الأصنام ولا تعلم الوقت الذي تُبعث فيه، وهو يوم القيامة."], ["قلوبهم منكرة", "جاحدة للوحدانية والنبوة والبعث والجزاء."], ["وهم مستكبرون", "لظلمة قلوبهم بالكفر يتكبّرون."], ["لا جرم", "حقاً."], ["أساطير الأولين", "أكاذيب الأولين."], ["ليحملوا أوزارهم", "ذنوبهم يوم القيامة."], ["ألا ساء ما يزرون", "بئس ما يحملون من الأوزار."]], "m": "في هذا السياق مواجهة صريحة للمشركين: والذين تعبدونهم من دون الله لا يخلقون شيئاً وهم يُخلقون، أموات لا حياة لهم، فلا يسمعون ولا ينطقون، ولا يعلمون متى يُبعثون، فكيف تصح عبادتهم؟ إلهكم إله واحد، هذه النتيجة العقلية التي لا ينكرها العقلاء، فهو الخالق الرازق المدبّر، وما عداه فتأليهه سفه وضلال. فالذين لا يؤمنون بالآخرة قلوبهم منكرة لكل ما يسمعون من الحق، وهم مستكبرون عن قبوله، فعلة الكفر والفساد تكذيبهم بالبعث، إذ لا يستقيم عبد على منهج الحق وهو لا يؤمن بيوم الجزاء. حقاً إن الله يعلم ما يسرّون وما يعلنون، وسيجزيهم به، إنه لا يحب المستكبرين. وإذا سألهم من سمع بالدعوة المحمدية: ماذا أنزل ربكم؟ قالوا: أخبار كاذبة عن الأولين، وبذلك يصدّون عن الإسلام، ليحملوا أوزارهم كاملة يوم القيامة، ومن أوزار الذين يضلّونهم بغير علم، فمن دعا إلى ضلالة كان عليه وزر من عمل بها من غير أن ينقص من أوزارهم شيء، ألا ساء ما يحملون.", "h": ["بطلان الشرك، وتقرير التوحيد.", "التكذيب باليوم الآخر والبعث والجزاء هو سبب كل شر وفساد يأتيه العبد.", "التنديد بجريمة الاستكبار عن الحق والإذعان له.", "بيان إثم وتبعة من يصدّ عن سبيل الله بصرف الناس عن الإسلام.", "بيان تبعة من يدعو إلى ضلالة، فإنه يتحمّل وزر كل من عمل بها."], "k": "«ومن أوزار الذين يضلّونهم بغير علم»… كلمة أو منشور أنشره؛ هل يحمل لي أجراً جارياً أم وزراً جارياً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 175;
