"المقارنة بين الحي الخلّاق العليم، وبين الأصنام الميتة المخلوقة، لتقرير بطلان عبادتها.", "عجز الإنسان عن شكر نعم الله تعالى يتطلّب منه أن يشكر ما يمكنه منها، وكلمة «الحمد لله» تُعدّ رأس الشكر، والاعتراف بالعجز عن الشكر من الشكر، والشكر صرف النعم فيما من أجله أنعم الله تعالى بها."], "k": "«لتأكلوا منه لحماً طرياً»… طعامي اليوم من رزقه؛ فهل جعلته عوناً على طاعته؟"}, {"lbl": "الآيات ٢٠ – ٢٥", "q": "وَٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ لَا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ ﴿٢٠﴾ أَمۡوَٰتٌ غَيۡرُ أَحۡيَآءٖۖ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ ﴿٢١﴾ إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۚ فَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ قُلُوبُهُم مُّنكِرَةٞ وَهُم مُّسۡتَكۡبِرُونَ ﴿٢٢﴾ لَا جَرَمَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡتَكۡبِرِينَ ﴿٢٣﴾ وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمۡ قَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿٢٤﴾ لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ أَلَا سَآءَ مَا يَزِرُونَ ﴿٢٥﴾", "w": [["وهم يُخلقون", "يُصوَّرون من الحجارة وغيرها."], ["وما يشعرون أيان يُبعثون", "لا تشعر الأصنام ولا تعلم الوقت الذي تُبعث فيه، وهو يوم القيامة."], ["قلوبهم منكرة", "جاحدة للوحدانية والنبوة والبعث والجزاء."], ["وهم مستكبرون", "لظلمة قلوبهم بالكفر يتكبّرون."], ["لا جرم", "حقاً."], ["أساطير الأولين", "أكاذيب الأولين."], ["ليحملوا أوزارهم", "ذنوبهم يوم القيامة."], ["ألا ساء ما يزرون", "بئس ما يحملون من الأوزار."]], "m": "في هذا السياق مواجهة صريحة للمشركين: والذين تعبدونهم من دون الله لا يخلقون شيئاً وهم يُخلقون، أموات لا حياة لهم، فلا يسمعون ولا ينطقون، ولا يعلمون متى يُبعثون، فكيف تصح عبادتهم؟ إلهكم إله واحد، هذه النتيجة العقلية التي لا ينكرها العقلاء، فهو الخالق الرازق المدبّر، وما عداه فتأليهه سفه وضلال. فالذين لا يؤمنون بالآخرة قلوبهم منكرة لكل ما يسمعون من الحق، وهم مستكبرون عن قبوله، فعلة الكفر والفساد تكذيبهم بالبعث، إذ لا يستقيم عبد على منهج الحق وهو لا يؤمن بيوم الجزاء. حقاً إن الله يعلم ما يسرّون وما يعلنون، وسيجزيهم به، إنه لا يحب المستكبرين. وإذا سألهم من سمع بالدعوة المحمدية: ماذا أنزل ربكم؟ قالوا: أخبار كاذبة عن الأولين، وبذلك يصدّون عن الإسلام، ليحملوا أوزارهم كاملة يوم القيامة، ومن أوزار الذين يضلّونهم بغير علم، فمن دعا إلى ضلالة كان عليه وزر من عمل بها من غير أن ينقص من أوزارهم شيء، ألا ساء ما يحملون.", "h": ["بطلان الشرك، وتقرير التوحيد.", "التكذيب باليوم الآخر والبعث والجزاء هو سبب كل شر وفساد يأتيه العبد.", "التنديد بجريمة الاستكبار عن الحق والإذعان له.", "بيان إثم وتبعة من يصدّ عن سبيل الله بصرف الناس عن الإسلام.", "بيان تبعة من يدعو إلى ضلالة، فإنه يتحمّل وزر كل من عمل بها."], "k": "«ومن أوزار الذين يضلّونهم بغير علم»… كلمة أو منشور أنشره؛ هل يحمل لي أجراً جارياً أم وزراً جارياً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (176, 16, 26, 40, 'سورة النحل ٢٦ – ٤٠', 'عاقبة مكر الأولين، وتوفّي الملائكة الظالمين والطيبين، و«ولقد بعثنا في كل أمة رسولاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 176) = $j$[{"lbl": "الآيات ٢٦ – ٣٤", "q": "قَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَى ٱللَّهُ بُنۡيَٰنَهُم مِّنَ ٱلۡقَوَاعِدِ فَخَرَّ عَلَيۡهِمُ ٱلسَّقۡفُ مِن فَوۡقِهِمۡ وَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ ﴿٢٦﴾ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يُخۡزِيهِمۡ وَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تُشَـٰٓقُّونَ فِيهِمۡۚ قَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ إِنَّ ٱلۡخِزۡيَ ٱلۡيَوۡمَ وَٱلسُّوٓءَ عَلَى ٱلۡكَٰفِرِينَ ﴿٢٧﴾ ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡۖ فَأَلۡقَوُاْ ٱلسَّلَمَ مَا كُنَّا نَعۡمَلُ مِن سُوٓءِۭۚ بَلَىٰٓۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٢٨﴾ فَٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَلَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ ﴿٢٩﴾ ۞وَقِيلَ لِلَّذِينَ ٱتَّقَوۡاْ مَاذَآ أَنزَلَ رَبُّكُمۡۚ قَالُواْ خَيۡرٗاۗ لِّلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۚ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِينَ ﴿٣٠﴾ جَنَّـٰتُ عَدۡنٖ يَدۡخُلُونَهَا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ لَهُمۡ فِيهَا مَا يَشَآءُونَۚ كَذَٰلِكَ يَجۡزِي ٱللَّهُ ٱلۡمُتَّقِينَ ﴿٣١﴾ ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيۡكُمُ ٱدۡخُلُواْ ٱلۡجَنَّةَ بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٣٢﴾ هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَـٰٓئِكَةُ أَوۡ يَأۡتِيَ أَمۡرُ رَبِّكَۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٣٣﴾ فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٣٤﴾", "w": [["من قبلهم", "من قبل كفار قريش، كالنمرود وغيره."], ["فأتى الله بنيانهم", "قصد إليه ليدمّره، فسلّط عليه الريح والزلزلة فسقط من أسسه."], ["تشاقّون فيهم", "تخالفون المؤمنين فيهم بعبادتكم إياهم وجدالكم عنهم."], ["وقال الذين أوتوا العلم", "الأنبياء والمؤمنون."], ["ظالمي أنفسهم", "بالشرك والمعاصي."], ["فألقوا السلم", "استسلموا وانقادوا."], ["فلبئس مثوى المتكبرين", "قبُح منزل المتكبرين في جهنم."], ["للذين أحسنوا", "أحسنوا أعمالهم وأقوالهم ونياتهم فأتوا بها وفق مراد الله تعالى."], ["حسنة", "الحياة الطيبة، حياة العز والكرامة."], ["ولنعم دار المتقين", "الجنة دار السلام."], ["طيبين", "طيّبي الأرواح بما زكّوها به من الإيمان والعمل الصالح، وبما أبعدوها عنه من الشرك والمعاصي."], ["يقولون سلام عليكم", "يقول لهم ملك الموت وأعوانه."], ["هل ينظرون إلا أن تأتيهم الملائكة", "لقبض أرواحهم، وعند ذلك يؤمنون."], ["أو يأتي أمر ربك", "بالعذاب، أو بقيام الساعة."], ["وحاق بهم", "نزل بهم العذاب وأحاط بهم."]], "m": "ما زال السياق مع كفار قريش: قد مكر الجبابرة من قبلهم كالنمرود الذي ألقى إبراهيم في النار، وفرعون الذي قال: ذروني أقتل موسى، فأتى أمر الله بنيانهم من القواعد فخرّ عليهم السقف من فوقهم وأتاهم العذاب من حيث لا يشعرون، ألم يتّعظ كفرة قريش وهم يمكرون بنبيهم؟ ثم يوم القيامة يذلّهم ويوبّخهم: أين شركائي الذين كنتم تخالفون فيهم أوليائي؟ ويقول الأنبياء والعلماء الربانيون: إن الذل والسوء اليوم على الكافرين، الذين تتوفّاهم الملائكة ظالمي أنفسهم بالشرك والمعاصي، ومنها ترك الهجرة والبقاء بين الكافرين حيث لا يتمكن المؤمن من عبادة ربه، فاستسلموا عند معاينة ملك الموت وقالوا كاذبين: ما كنا نعمل من سوء، فترد الملائكة: بلى، إن الله عليم بما كنتم تعملون، فادخلوا أبواب جهنم خالدين فيها، فلبئس منزل المتكبرين. وقيل للذين اتقوا ربهم: ماذا أنزل ربكم؟ قالوا: خيراً، لأن القرآن خير وبالخير نزل. للذين أحسنوا في هذه الدنيا حياة طيبة حياة الطهر والعزة، ولدار الآخرة خير، ولنعم دار المتقين: جنات إقامة تجري من تحتها الأنهار، لهم فيها ما يشاؤون، وهذا نهاية الإكرام. الذين تتوفّاهم الملائكة طاهري الأرواح يقولون لهم: سلام عليكم، ادخلوا الجنة بأرواحكم اليوم وبأجسامكم غداً، بما كنتم تعملون. هل ينتظر المكذّبون بعد هذه البراهين إلا أن تأتيهم الملائكة لقبض أرواحهم، أو يأتي أمر ربك بإبادتهم؟ كذلك فعل الذين من قبلهم، وما ظلمهم الله ولكن كانوا أنفسهم يظلمون، فأصابهم جزاء سيئات ما عملوا، ونزل بهم ما كانوا به يستهزئون.", "h": ["سوء عاقبة المكر، وأنه يحيق بأهله لا محالة، والمراد به المكر السيئ.", "بيان خزي الله تعالى يوم القيامة لأهل الشرك به والمعاصي له ولرسوله.", "فضل أهل العلم، إذ يُتّخذ منهم شهداء يوم القيامة، ويشمتون بأهل النار.", "بيان استسلام الظلمة عند الموت، وانهزامهم وكذبهم.", "تقرير معتقد البعث والحياة الآخرة بأروع أسلوب وأحكمه وأمتنه.", "إطلاق لفظ «خير» على القرآن، وهو حق خير، فالذي أوتي القرآن أوتي الخير كله، فلا ينبغي أن يرى أحداً من أهل الدنيا خيراً منه، وإلا سخط نعمة الله تعالى عليه.", "سعادة الدارين لأهل الإحسان، وهم أهل الإيمان والإسلام والإحسان: في إيمانهم بالإخلاص، وفي إسلامهم بموافقة الشرع ومراقبة الله تعالى في ذلك.", "بشرى أهل الإيمان والتقوى عند الموت، وعند القيام من القبور، بالنعيم المقيم في جوار رب العالمين.", "أعمال القلوب والجوارح سبب في دخول الجنة، وليست ثمناً لها لغلائها، وإنما الأعمال تزكّي النفس وتطهّر الروح، وبذلك يتأهّل العبد لدخول الجنة.", "ما ينتظر المجرمون بإصرارهم على الظلم والشر والفساد إلا العذاب، عاجلاً أو آجلاً، فهو نازل بهم حتماً إن لم يبادروا إلى التوبة الصادقة."], "k": "«الذين تتوفّاهم الملائكة طيبين»… كيف أريد أن تقبضني الملائكة؟ فماذا أطيّب به روحي من اليوم؟"}, {"lbl": "الآيات ٣٥ – ٤٠", "q": "وَقَالَ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَا عَبَدۡنَا مِن دُونِهِۦ مِن شَيۡءٖ نَّحۡنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن دُونِهِۦ مِن شَيۡءٖۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ فَهَلۡ عَلَى ٱلرُّسُلِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿٣٥﴾ وَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةٖ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱجۡتَنِبُواْ ٱلطَّـٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ حَقَّتۡ عَلَيۡهِ ٱلضَّلَٰلَةُۚ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ﴿٣٦﴾ إِن تَحۡرِصۡ عَلَىٰ هُدَىٰهُمۡ فَإِنَّ ٱللَّهَ لَا يَهۡدِي مَن يُضِلُّۖ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٣٧﴾ وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَا يَبۡعَثُ ٱللَّهُ مَن يَمُوتُۚ بَلَىٰ وَعۡدًا عَلَيۡهِ حَقّٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٣٨﴾ لِيُبَيِّنَ لَهُمُ ٱلَّذِي يَخۡتَلِفُونَ فِيهِ وَلِيَعۡلَمَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ كَانُواْ كَٰذِبِينَ ﴿٣٩﴾ إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ ﴿٤٠﴾", "w": [["ولا حرّمنا من دونه من شيء", "كالسوائب والبحائر والوصائل والحامات."], ["فهل على الرسل إلا البلاغ", "ما على الرسل إلا البلاغ، فالاستفهام للنفي."], ["واجتنبوا الطاغوت", "عبادة الأصنام والأوثان."], ["حقّت عليه الضلالة", "وجبت في علم الله أزلاً."], ["جهد أيمانهم", "غايتها، حيث بذلوا جهدهم فيها مبالغة منهم."], ["بلى وعداً عليه حقاً", "بلى يُبعث من يموت، وقد وعد به وعداً، فهو كائن لا محالة."], ["يختلفون فيه", "بين المؤمنين والمشركين من التوحيد والشرك."], ["أنهم كانوا كاذبين", "في قولهم: لا نُبعث بعد الموت."]], "m": "ما زال السياق في الحجاج مع مشركي قريش: قالوا: لو شاء الله ما عبدنا من دونه من شيء نحن ولا آباؤنا، ولا حرّمنا من دونه شيئاً كالسوائب والبحائر، قالوه احتجاجاً بالمشيئة أو استهزاءً دفاعاً عن شركهم وتشريعهم بالهوى، والرد عليهم بأمرين: أن الله نهاهم عن الشرك والتشريع، وذلك دليل على تحريمه، وأن كونه لم يعذّبهم بعدُ ليس دليلاً على رضاه، فقد قالها من قبلهم حتى ذاقوا بأسه. فهل على الرسل إلا البلاغ المبين؟ ليس عليهم إكراه المشركين، وفي هذا تسلية للرسول ﷺ. ولقد بعثنا في كل أمة رسولاً أن اعبدوا الله واجتنبوا الطاغوت، وهو كل ما عُبد من دون الله، فهذه وحدة دعوة الرسل: لا إله إلا الله. فمنهم من هدى الله فعرف الحق وعمل به، ومنهم من حقّت عليه الضلالة لأنه أصرّ على الضلال وحارب من أجله باختياره، فسيروا في الأرض فانظروا كيف كان عاقبة المكذّبين كعاد وثمود. إن تحرص على هداهم فإن الله لا يهدي من يضل، فهوّن على نفسك وادعُ في غير حرص يضرّك. وأقسموا بالله جهد أيمانهم: لا يبعث الله من يموت، بلى، وعداً عليه حقاً، ولكن أكثر الناس لا يعلمون، ليبيّن لهم الذي يختلفون فيه، فلولا البعث ما عُرف المحقّ من المبطل، وليعلم الذين كفروا أنهم كانوا كاذبين، إنما قولنا لشيء إذا أردناه أن نقول له كن فيكون.", "h": ["الرد على شبهة المشركين في احتجاجهم بالمشيئة الإلهية.", "تفسير «لا إله إلا الله».", "التحذير من تعمّد الضلال وطلبه والحرص عليه.", "بيان بعض الحكم في البعث الآخر.", "لا يُستعظم على الله خلق شيء وإيجاده، لأنه يوجد بكلمة التكوين فقط."], "k": "«إن تحرص على هداهم فإن الله لا يهدي من يضل»… أبلّغ بحرص، ثم أترك القلوب لمقلّبها؛ فهل أرتاح بهذا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 176;
insert into public.tdb_cards(topic, i, body) select 176, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٦ – ٣٤", "q": "قَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَى ٱللَّهُ بُنۡيَٰنَهُم مِّنَ ٱلۡقَوَاعِدِ فَخَرَّ عَلَيۡهِمُ ٱلسَّقۡفُ مِن فَوۡقِهِمۡ وَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ ﴿٢٦﴾ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يُخۡزِيهِمۡ وَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تُشَـٰٓقُّونَ فِيهِمۡۚ قَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ إِنَّ ٱلۡخِزۡيَ ٱلۡيَوۡمَ وَٱلسُّوٓءَ عَلَى ٱلۡكَٰفِرِينَ ﴿٢٧﴾ ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡۖ فَأَلۡقَوُاْ ٱلسَّلَمَ مَا كُنَّا نَعۡمَلُ مِن سُوٓءِۭۚ بَلَىٰٓۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٢٨﴾ فَٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَلَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ ﴿٢٩﴾ ۞وَقِيلَ لِلَّذِينَ ٱتَّقَوۡاْ مَاذَآ أَنزَلَ رَبُّكُمۡۚ قَالُواْ خَيۡرٗاۗ لِّلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۚ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِينَ ﴿٣٠﴾ جَنَّـٰتُ عَدۡنٖ يَدۡخُلُونَهَا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ لَهُمۡ فِيهَا مَا يَشَآءُونَۚ كَذَٰلِكَ يَجۡزِي ٱللَّهُ ٱلۡمُتَّقِينَ ﴿٣١﴾ ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيۡكُمُ ٱدۡخُلُواْ ٱلۡجَنَّةَ بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٣٢﴾ هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَـٰٓئِكَةُ أَوۡ يَأۡتِيَ أَمۡرُ رَبِّكَۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿٣٣﴾ فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٣٤﴾", "w": [["من قبلهم", "من قبل كفار قريش، كالنمرود وغيره."], ["فأتى الله بنيانهم", "قصد إليه ليدمّره، فسلّط عليه الريح والزلزلة فسقط من أسسه."], ["تشاقّون فيهم", "تخالفون المؤمنين فيهم بعبادتكم إياهم وجدالكم عنهم."], ["وقال الذين أوتوا العلم", "الأنبياء والمؤمنون."], ["ظالمي أنفسهم", "بالشرك والمعاصي."], ["فألقوا السلم", "استسلموا وانقادوا."], ["فلبئس مثوى المتكبرين", "قبُح منزل المتكبرين في جهنم."], ["للذين أحسنوا", "أحسنوا أعمالهم وأقوالهم ونياتهم فأتوا بها وفق مراد الله تعالى."], ["حسنة", "الحياة الطيبة، حياة العز والكرامة."], ["ولنعم دار المتقين", "الجنة دار السلام."], ["طيبين", "طيّبي الأرواح بما زكّوها به من الإيمان والعمل الصالح، وبما أبعدوها عنه من الشرك والمعاصي."], ["يقولون سلام عليكم", "يقول لهم ملك الموت وأعوانه."], ["هل ينظرون إلا أن تأتيهم الملائكة", "لقبض أرواحهم، وعند ذلك يؤمنون."], ["أو يأتي أمر ربك", "بالعذاب، أو بقيام الساعة."], ["وحاق بهم", "نزل بهم العذاب وأحاط بهم."]], "m": "ما زال السياق مع كفار قريش: قد مكر الجبابرة من قبلهم كالنمرود الذي ألقى إبراهيم في النار، وفرعون الذي قال: ذروني أقتل موسى، فأتى أمر الله بنيانهم من القواعد فخرّ عليهم السقف من فوقهم وأتاهم العذاب من حيث لا يشعرون، ألم يتّعظ كفرة قريش وهم يمكرون بنبيهم؟ ثم يوم القيامة يذلّهم ويوبّخهم: أين شركائي الذين كنتم تخالفون فيهم أوليائي؟ ويقول الأنبياء والعلماء الربانيون: إن الذل والسوء اليوم على الكافرين، الذين تتوفّاهم الملائكة ظالمي أنفسهم بالشرك والمعاصي، ومنها ترك الهجرة والبقاء بين الكافرين حيث لا يتمكن المؤمن من عبادة ربه، فاستسلموا عند معاينة ملك الموت وقالوا كاذبين: ما كنا نعمل من سوء، فترد الملائكة: بلى، إن الله عليم بما كنتم تعملون، فادخلوا أبواب جهنم خالدين فيها، فلبئس منزل المتكبرين. وقيل للذين اتقوا ربهم: ماذا أنزل ربكم؟ قالوا: خيراً، لأن القرآن خير وبالخير نزل. للذين أحسنوا في هذه الدنيا حياة طيبة حياة الطهر والعزة، ولدار الآخرة خير، ولنعم دار المتقين: جنات إقامة تجري من تحتها الأنهار، لهم فيها ما يشاؤون، وهذا نهاية الإكرام. الذين تتوفّاهم الملائكة طاهري الأرواح يقولون لهم: سلام عليكم، ادخلوا الجنة بأرواحكم اليوم وبأجسامكم غداً، بما كنتم تعملون. هل ينتظر المكذّبون بعد هذه البراهين إلا أن تأتيهم الملائكة لقبض أرواحهم، أو يأتي أمر ربك بإبادتهم؟ كذلك فعل الذين من قبلهم، وما ظلمهم الله ولكن كانوا أنفسهم يظلمون، فأصابهم جزاء سيئات ما عملوا، ونزل بهم ما كانوا به يستهزئون.", "h": ["سوء عاقبة المكر، وأنه يحيق بأهله لا محالة، والمراد به المكر السيئ.", "بيان خزي الله تعالى يوم القيامة لأهل الشرك به والمعاصي له ولرسوله.", "فضل أهل العلم، إذ يُتّخذ منهم شهداء يوم القيامة، ويشمتون بأهل النار.", "بيان استسلام الظلمة عند الموت، وانهزامهم وكذبهم.", "تقرير معتقد البعث والحياة الآخرة بأروع أسلوب وأحكمه وأمتنه.", "إطلاق لفظ «خير» على القرآن، وهو حق خير، فالذي أوتي القرآن أوتي الخير كله، فلا ينبغي أن يرى أحداً من أهل الدنيا خيراً منه، وإلا سخط نعمة الله تعالى عليه.", "سعادة الدارين لأهل الإحسان، وهم أهل الإيمان والإسلام والإحسان: في إيمانهم بالإخلاص، وفي إسلامهم بموافقة الشرع ومراقبة الله تعالى في ذلك.", "بشرى أهل الإيمان والتقوى عند الموت، وعند القيام من القبور، بالنعيم المقيم في جوار رب العالمين.", "أعمال القلوب والجوارح سبب في دخول الجنة، وليست ثمناً لها لغلائها، وإنما الأعمال تزكّي النفس وتطهّر الروح، وبذلك يتأهّل العبد لدخول الجنة.", "ما ينتظر المجرمون بإصرارهم على الظلم والشر والفساد إلا العذاب، عاجلاً أو آجلاً، فهو نازل بهم حتماً إن لم يبادروا إلى التوبة الصادقة."], "k": "«الذين تتوفّاهم الملائكة طيبين»… كيف أريد أن تقبضني الملائكة؟ فماذا أطيّب به روحي من اليوم؟"}, {"lbl": "الآيات ٣٥ – ٤٠", "q": "وَقَالَ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَا عَبَدۡنَا مِن دُونِهِۦ مِن شَيۡءٖ نَّحۡنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن دُونِهِۦ مِن شَيۡءٖۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ فَهَلۡ عَلَى ٱلرُّسُلِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿٣٥﴾ وَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةٖ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱجۡتَنِبُواْ ٱلطَّـٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ حَقَّتۡ عَلَيۡهِ ٱلضَّلَٰلَةُۚ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ ﴿٣٦﴾ إِن تَحۡرِصۡ عَلَىٰ هُدَىٰهُمۡ فَإِنَّ ٱللَّهَ لَا يَهۡدِي مَن يُضِلُّۖ وَمَا لَهُم مِّن نَّـٰصِرِينَ ﴿٣٧﴾ وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَا يَبۡعَثُ ٱللَّهُ مَن يَمُوتُۚ بَلَىٰ وَعۡدًا عَلَيۡهِ حَقّٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ﴿٣٨﴾ لِيُبَيِّنَ لَهُمُ ٱلَّذِي يَخۡتَلِفُونَ فِيهِ وَلِيَعۡلَمَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ كَانُواْ كَٰذِبِينَ ﴿٣٩﴾ إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ ﴿٤٠﴾", "w": [["ولا حرّمنا من دونه من شيء", "كالسوائب والبحائر والوصائل والحامات."], ["فهل على الرسل إلا البلاغ", "ما على الرسل إلا البلاغ، فالاستفهام للنفي."], ["واجتنبوا الطاغوت", "عبادة الأصنام والأوثان."], ["حقّت عليه الضلالة", "وجبت في علم الله أزلاً."], ["جهد أيمانهم", "غايتها، حيث بذلوا جهدهم فيها مبالغة منهم."], ["بلى وعداً عليه حقاً", "بلى يُبعث من يموت، وقد وعد به وعداً، فهو كائن لا محالة."], ["يختلفون فيه", "بين المؤمنين والمشركين من التوحيد والشرك."], ["أنهم كانوا كاذبين", "في قولهم: لا نُبعث بعد الموت."]], "m": "ما زال السياق في الحجاج مع مشركي قريش: قالوا: لو شاء الله ما عبدنا من دونه من شيء نحن ولا آباؤنا، ولا حرّمنا من دونه شيئاً كالسوائب والبحائر، قالوه احتجاجاً بالمشيئة أو استهزاءً دفاعاً عن شركهم وتشريعهم بالهوى، والرد عليهم بأمرين: أن الله نهاهم عن الشرك والتشريع، وذلك دليل على تحريمه، وأن كونه لم يعذّبهم بعدُ ليس دليلاً على رضاه، فقد قالها من قبلهم حتى ذاقوا بأسه. فهل على الرسل إلا البلاغ المبين؟ ليس عليهم إكراه المشركين، وفي هذا تسلية للرسول ﷺ. ولقد بعثنا في كل أمة رسولاً أن اعبدوا الله واجتنبوا الطاغوت، وهو كل ما عُبد من دون الله، فهذه وحدة دعوة الرسل: لا إله إلا الله. فمنهم من هدى الله فعرف الحق وعمل به، ومنهم من حقّت عليه الضلالة لأنه أصرّ على الضلال وحارب من أجله باختياره، فسيروا في الأرض فانظروا كيف كان عاقبة المكذّبين كعاد وثمود. إن تحرص على هداهم فإن الله لا يهدي من يضل، فهوّن على نفسك وادعُ في غير حرص يضرّك. وأقسموا بالله جهد أيمانهم: لا يبعث الله من يموت، بلى، وعداً عليه حقاً، ولكن أكثر الناس لا يعلمون، ليبيّن لهم الذي يختلفون فيه، فلولا البعث ما عُرف المحقّ من المبطل، وليعلم الذين كفروا أنهم كانوا كاذبين، إنما قولنا لشيء إذا أردناه أن نقول له كن فيكون.", "h": ["الرد على شبهة المشركين في احتجاجهم بالمشيئة الإلهية.", "تفسير «لا إله إلا الله».", "التحذير من تعمّد الضلال وطلبه والحرص عليه.", "بيان بعض الحكم في البعث الآخر.", "لا يُستعظم على الله خلق شيء وإيجاده، لأنه يوجد بكلمة التكوين فقط."], "k": "«إن تحرص على هداهم فإن الله لا يهدي من يضل»… أبلّغ بحرص، ثم أترك القلوب لمقلّبها؛ فهل أرتاح بهذا؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (177, 16, 41, 50, 'سورة النحل ٤١ – ٥٠', 'فضل الهجرة، و«فاسألوا أهل الذكر»، وسجود كل شيء لله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 177) = $j$[{"lbl": "الآيات ٤١ – ٤٤", "q": "وَٱلَّذِينَ هَاجَرُواْ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُواْ لَنُبَوِّئَنَّهُمۡ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَلَأَجۡرُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٤١﴾ ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٤٢﴾ وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ﴿٤٣﴾ بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَآ إِلَيۡكَ ٱلذِّكۡرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيۡهِمۡ وَلَعَلَّهُمۡ يَتَفَكَّرُونَ ﴿٤٤﴾", "w": [["والذين هاجروا في الله", "خرجوا من مكة في سبيل الله نصرةً لدينه وإقامته بين الناس."], ["لنبوّئنّهم في الدنيا حسنة", "لننزلنّهم داراً حسنة هي المدينة النبوية، هذا بالنسبة لمن نزلت فيهم الآية."], ["الذين صبروا وعلى ربهم يتوكلون", "صبروا على أذى المشركين، وهاجروا متوكلين على ربهم في دار هجرتهم."], ["فاسألوا أهل الذكر", "أيها الشاكّون فيما جاء به محمد ﷺ، اسألوا أهل التوراة والإنجيل: هل كان الرسل قبله بشراً مثله؟"], ["بالبينات والزبر", "أرسلناهم بشراً بالبيّنات والكتب لهداية الناس."], ["وأنزلنا إليك الذكر", "القرآن."], ["لتبيّن للناس ما نُزّل إليهم", "علة لإنزال الذكر، إذ وظيفة الرسل البيان."]], "m": "بعد اشتداد الأذى على المؤمنين أذن الله لهم بالهجرة إلى الحبشة ثم إلى المدينة، فأثنى على المهاجرين تشجيعاً على الهجرة من دار الكفر: والذين هاجروا في الله، في ذاته ومن أجل عبادته ونصرة دينه، من بعد ما ظلمهم المشركون، لننزلنّهم في الدنيا داراً حسنة هي المدينة النبوية، ولنرزقنّهم فيها رزقاً حسناً، وكل من هاجر في الله ينجز له الرب هذا الوعد، ولأجر الآخرة المعدّ لهم أكبر لو كانوا يعلمون، الذين صبروا على الأذى بمكة ثم هاجروا متوكلين على ربهم مفوّضين أمورهم إليه. ثم أبطل شبهة المشركين: كيف يرسل الله بشراً؟ فقال: وما أرسلنا من قبلك إلا رجالاً لا ملائكة نوحي إليهم، فاسألوا علماء أهل الكتاب إن كنتم لا تعلمون، وما موسى ولا عيسى إلا بشر، أرسلناهم بالحجج الدالة على وجوب عبادتنا وبالكتب، وأنزلنا إليك القرآن لتبيّن للناس ما نُزّل إليهم، ولعلهم يتفكرون فيعرفوا صدق ما جئتهم به فيؤمنوا.", "h": ["فضل الهجرة، ووجوبها عند اضطهاد المؤمن وعدم تمكّنه من عبادة الله تعالى.", "وجوب سؤال أهل العلم على كل من لا يعلم أمور دينه من عقيدة وعبادة وحكم.", "السنة لا غنى عنها، لأنها المبيّنة لمجمل القرآن والموضّحة لمعانيه."], "k": "«فاسألوا أهل الذكر إن كنتم لا تعلمون»… مسألة في ديني أعمل فيها بالظن؛ متى أسأل عنها أهل العلم؟"}, {"lbl": "الآيات ٤٥ – ٥٠", "q": "أَفَأَمِنَ ٱلَّذِينَ مَكَرُواْ ٱلسَّيِّـَٔاتِ أَن يَخۡسِفَ ٱللَّهُ بِهِمُ ٱلۡأَرۡضَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ ﴿٤٥﴾ أَوۡ يَأۡخُذَهُمۡ فِي تَقَلُّبِهِمۡ فَمَا هُم بِمُعۡجِزِينَ ﴿٤٦﴾ أَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفٖ فَإِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٌ ﴿٤٧﴾ أَوَلَمۡ يَرَوۡاْ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ يَتَفَيَّؤُاْ ظِلَٰلُهُۥ عَنِ ٱلۡيَمِينِ وَٱلشَّمَآئِلِ سُجَّدٗا لِّلَّهِ وَهُمۡ دَٰخِرُونَ ﴿٤٨﴾ وَلِلَّهِۤ يَسۡجُدُۤ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ مِن دَآبَّةٖ وَٱلۡمَلَـٰٓئِكَةُ وَهُمۡ لَا يَسۡتَكۡبِرُونَ ﴿٤٩﴾ يَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ۩ ﴿٥٠﴾", "w": [["مكروا السيئات", "مكروا المكرات السيئات، فالسيئات وصف للمكرات التي مكروها."], ["في تقلّبهم", "في البلاد مسافرين للتجارة وغيرها."], ["على تخوّف", "على تنقّص، بأن يهلكهم واحداً بعد واحد."], ["سجّداً لله", "خضّعاً لله كما أراد منهم."], ["داخرون", "صاغرون ذليلون."], ["من فوقهم", "من أعلى منهم، إذ هو تعالى فوق كل شيء ذاتاً وسلطاناً وقهراً."], ["ما يؤمرون", "ما يأمرهم ربهم تعالى به."]], "m": "ما زال السياق في تخويف المشركين لعلهم يرجعون: أفأمن الذين مكروا المكرات السيئات، من محاولة قتل النبي ﷺ والشرك وظلم المؤمنين، أن يخسف الله بهم الأرض، أو يأتيهم العذاب من حيث لا يتوقعون من ريح عاصف أو وباء أو قحط، أو يأخذهم في أسفارهم وتجارتهم فما هم بفائتيه، أو يأخذهم على تنقّص واحداً بعد واحد حتى لا يبقى منهم أحد، وقد أخذ منهم ببدر وأحد من أخذ؟ فإن ربكم لرؤوف رحيم، ولولا رأفته لأنزل بهم نقمته بلا إمهال. أوَلم يروا إلى ما خلق الله من شجر وجبل وإنسان وحيوان تتفيّأ ظلاله بالصباح والمساء عن اليمين والشمائل خضّعاً لله وهم صاغرون؟ أما يكفيهم ذلك دلالة فيؤمنوا؟ ولله يسجد، أي يخضع وينقاد لما يريده من إحياء أو إماتة أو صحة أو مرض، ما في السماوات وما في الأرض من دابة، والملائكة على شرفهم يسجدون وهم لا يستكبرون، يخافون ربهم من فوقهم، إذ هو العلي الأعلى، ويفعلون ما يؤمرون، فما بال هؤلاء المشركين يلجّون في الاستكبار وهم أحقر المخلوقات؟", "h": ["حرمة الأمن من مكر الله.", "كل شيء ساجد لله، أي خاضع لما يريده منه، إلا أن السجود الطوعي الاختياري هو الذي يُثاب عليه العبد، أما الطاعة اللاإرادية فلا ثواب فيها ولا عقاب.", "فضل السجود الطوعي الاختياري.", "مشروعية السجود عند هذه الآية: إذا قرأ القارئ أو المستمع «ويخافون ربهم من فوقهم ويفعلون ما يؤمرون» عليه أن يسجد إن كان متطهراً، إلى القبلة إن أمكن، ويسبّح في السجود، ويكبّر في الخفض والرفع، ولا يسلّم."], "k": "«ويخافون ربهم من فوقهم ويفعلون ما يؤمرون»… الملائكة على قربها تخاف وتطيع؛ فأين خوفي وطاعتي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 177;
insert into public.tdb_cards(topic, i, body) select 177, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤١ – ٤٤", "q": "وَٱلَّذِينَ هَاجَرُواْ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُواْ لَنُبَوِّئَنَّهُمۡ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَلَأَجۡرُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ﴿٤١﴾ ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٤٢﴾ وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ﴿٤٣﴾ بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَآ إِلَيۡكَ ٱلذِّكۡرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيۡهِمۡ وَلَعَلَّهُمۡ يَتَفَكَّرُونَ ﴿٤٤﴾", "w": [["والذين هاجروا في الله", "خرجوا من مكة في سبيل الله نصرةً لدينه وإقامته بين الناس."], ["لنبوّئنّهم في الدنيا حسنة", "لننزلنّهم داراً حسنة هي المدينة النبوية، هذا بالنسبة لمن نزلت فيهم الآية."], ["الذين صبروا وعلى ربهم يتوكلون", "صبروا على أذى المشركين، وهاجروا متوكلين على ربهم في دار هجرتهم."], ["فاسألوا أهل الذكر", "أيها الشاكّون فيما جاء به محمد ﷺ، اسألوا أهل التوراة والإنجيل: هل كان الرسل قبله بشراً مثله؟"], ["بالبينات والزبر", "أرسلناهم بشراً بالبيّنات والكتب لهداية الناس."], ["وأنزلنا إليك الذكر", "القرآن."], ["لتبيّن للناس ما نُزّل إليهم", "علة لإنزال الذكر، إذ وظيفة الرسل البيان."]], "m": "بعد اشتداد الأذى على المؤمنين أذن الله لهم بالهجرة إلى الحبشة ثم إلى المدينة، فأثنى على المهاجرين تشجيعاً على الهجرة من دار الكفر: والذين هاجروا في الله، في ذاته ومن أجل عبادته ونصرة دينه، من بعد ما ظلمهم المشركون، لننزلنّهم في الدنيا داراً حسنة هي المدينة النبوية، ولنرزقنّهم فيها رزقاً حسناً، وكل من هاجر في الله ينجز له الرب هذا الوعد، ولأجر الآخرة المعدّ لهم أكبر لو كانوا يعلمون، الذين صبروا على الأذى بمكة ثم هاجروا متوكلين على ربهم مفوّضين أمورهم إليه. ثم أبطل شبهة المشركين: كيف يرسل الله بشراً؟ فقال: وما أرسلنا من قبلك إلا رجالاً لا ملائكة نوحي إليهم، فاسألوا علماء أهل الكتاب إن كنتم لا تعلمون، وما موسى ولا عيسى إلا بشر، أرسلناهم بالحجج الدالة على وجوب عبادتنا وبالكتب، وأنزلنا إليك القرآن لتبيّن للناس ما نُزّل إليهم، ولعلهم يتفكرون فيعرفوا صدق ما جئتهم به فيؤمنوا.", "h": ["فضل الهجرة، ووجوبها عند اضطهاد المؤمن وعدم تمكّنه من عبادة الله تعالى.", "وجوب سؤال أهل العلم على كل من لا يعلم أمور دينه من عقيدة وعبادة وحكم.", "السنة لا غنى عنها، لأنها المبيّنة لمجمل القرآن والموضّحة لمعانيه."], "k": "«فاسألوا أهل الذكر إن كنتم لا تعلمون»… مسألة في ديني أعمل فيها بالظن؛ متى أسأل عنها أهل العلم؟"}, {"lbl": "الآيات ٤٥ – ٥٠", "q": "أَفَأَمِنَ ٱلَّذِينَ مَكَرُواْ ٱلسَّيِّـَٔاتِ أَن يَخۡسِفَ ٱللَّهُ بِهِمُ ٱلۡأَرۡضَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ ﴿٤٥﴾ أَوۡ يَأۡخُذَهُمۡ فِي تَقَلُّبِهِمۡ فَمَا هُم بِمُعۡجِزِينَ ﴿٤٦﴾ أَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفٖ فَإِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٌ ﴿٤٧﴾ أَوَلَمۡ يَرَوۡاْ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ يَتَفَيَّؤُاْ ظِلَٰلُهُۥ عَنِ ٱلۡيَمِينِ وَٱلشَّمَآئِلِ سُجَّدٗا لِّلَّهِ وَهُمۡ دَٰخِرُونَ ﴿٤٨﴾ وَلِلَّهِۤ يَسۡجُدُۤ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ مِن دَآبَّةٖ وَٱلۡمَلَـٰٓئِكَةُ وَهُمۡ لَا يَسۡتَكۡبِرُونَ ﴿٤٩﴾ يَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ۩ ﴿٥٠﴾", "w": [["مكروا السيئات", "مكروا المكرات السيئات، فالسيئات وصف للمكرات التي مكروها."], ["في تقلّبهم", "في البلاد مسافرين للتجارة وغيرها."], ["على تخوّف", "على تنقّص، بأن يهلكهم واحداً بعد واحد."], ["سجّداً لله", "خضّعاً لله كما أراد منهم."], ["داخرون", "صاغرون ذليلون."], ["من فوقهم", "من أعلى منهم، إذ هو تعالى فوق كل شيء ذاتاً وسلطاناً وقهراً."], ["ما يؤمرون", "ما يأمرهم ربهم تعالى به."]], "m": "ما زال السياق في تخويف المشركين لعلهم يرجعون: أفأمن الذين مكروا المكرات السيئات، من محاولة قتل النبي ﷺ والشرك وظلم المؤمنين، أن يخسف الله بهم الأرض، أو يأتيهم العذاب من حيث لا يتوقعون من ريح عاصف أو وباء أو قحط، أو يأخذهم في أسفارهم وتجارتهم فما هم بفائتيه، أو يأخذهم على تنقّص واحداً بعد واحد حتى لا يبقى منهم أحد، وقد أخذ منهم ببدر وأحد من أخذ؟ فإن ربكم لرؤوف رحيم، ولولا رأفته لأنزل بهم نقمته بلا إمهال. أوَلم يروا إلى ما خلق الله من شجر وجبل وإنسان وحيوان تتفيّأ ظلاله بالصباح والمساء عن اليمين والشمائل خضّعاً لله وهم صاغرون؟ أما يكفيهم ذلك دلالة فيؤمنوا؟ ولله يسجد، أي يخضع وينقاد لما يريده من إحياء أو إماتة أو صحة أو مرض، ما في السماوات وما في الأرض من دابة، والملائكة على شرفهم يسجدون وهم لا يستكبرون، يخافون ربهم من فوقهم، إذ هو العلي الأعلى، ويفعلون ما يؤمرون، فما بال هؤلاء المشركين يلجّون في الاستكبار وهم أحقر المخلوقات؟", "h": ["حرمة الأمن من مكر الله.", "كل شيء ساجد لله، أي خاضع لما يريده منه، إلا أن السجود الطوعي الاختياري هو الذي يُثاب عليه العبد، أما الطاعة اللاإرادية فلا ثواب فيها ولا عقاب.", "فضل السجود الطوعي الاختياري.", "مشروعية السجود عند هذه الآية: إذا قرأ القارئ أو المستمع «ويخافون ربهم من فوقهم ويفعلون ما يؤمرون» عليه أن يسجد إن كان متطهراً، إلى القبلة إن أمكن، ويسبّح في السجود، ويكبّر في الخفض والرفع، ولا يسلّم."], "k": "«ويخافون ربهم من فوقهم ويفعلون ما يؤمرون»… الملائكة على قربها تخاف وتطيع؛ فأين خوفي وطاعتي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (178, 16, 51, 62, 'سورة النحل ٥١ – ٦٢', '«وما بكم من نعمة فمن الله»، وجعلهم لله البنات، و«ولله المثل الأعلى»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 178) = $j$[{"lbl": "الآيات ٥١ – ٥٦", "q": "۞وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيۡنِ ٱثۡنَيۡنِۖ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ فَإِيَّـٰيَ فَٱرۡهَبُونِ ﴿٥١﴾ وَلَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَهُ ٱلدِّينُ وَاصِبًاۚ أَفَغَيۡرَ ٱللَّهِ تَتَّقُونَ ﴿٥٢﴾ وَمَا بِكُم مِّن نِّعۡمَةٖ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيۡهِ تَجۡـَٔرُونَ ﴿٥٣﴾ ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمۡ إِذَا فَرِيقٞ مِّنكُم بِرَبِّهِمۡ يُشۡرِكُونَ ﴿٥٤﴾ لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ ﴿٥٥﴾ وَيَجۡعَلُونَ لِمَا لَا يَعۡلَمُونَ نَصِيبٗا مِّمَّا رَزَقۡنَٰهُمۡۗ تَٱللَّهِ لَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَفۡتَرُونَ ﴿٥٦﴾", "w": [["لا تتخذوا إلهين", "لا تعبدوهما، إذ ليس لكم إلا إله واحد."], ["وله ما في السماوات والأرض", "خلقاً وملكاً، فما تعبدونه مع الله هو لله."], ["وله الدين واصباً", "خالصاً دائماً واجباً."], ["فإليه تجأرون", "ترفعون أصواتكم بدعائه طالبين الشفاء منه."], ["فتمتعوا فسوف تعلمون", "تهديد على كفرهم وشركهم ونسيانهم دعاء الله تعالى."], ["ويجعلون لما لا يعلمون نصيباً", "يجعلون لآلهتهم نصيباً من الحرث والأنعام."], ["عما كنتم تفترون", "تختلقون بالكذب على الله عز وجل."]], "m": "بعد إقامة الحجج على التوحيد قال لهم ربهم: لا تتخذوا إلهين اثنين، إنما هو إله واحد، فإياي فارهبون وحدي، فبيدي كل شيء وليس لغيري شيء، أنا المحيي المميت الضار النافع. وله ما في السماوات والأرض خلقاً وملكاً، وله العبادة والطاعة خالصة دائمة واجبة، أفغير الله تتّقون وتخافون، وهو الملك الحق القادر على إعطاء النعم وسلبها؟ وما بكم من نعمة، صغرت أو كبرت، من صحة أو مال أو ولد، فمن الله، ودليل ذلك شعوركم الفطري: إذا مسّكم الضر من فقر أو مرض أو خوف غرق فإليه وحده ترفعون أصواتكم بالدعاء، ثم إذا كشف الضر عنكم إذا فريق منكم بربهم يشركون، ليؤول أمرهم إلى كفران ما آتاهم الله، أفهكذا يكون الجزاء؟ فتمتعوا فسوف تعلمون عاقبة كفركم. ويجعلون لأوثانهم التي لا يعلمون عنها شيئاً نصيباً من أموالهم: سيّبوا لها السوائب وبحروا البحائر وجعلوا لها من الحرث، تالله لتُسألنّ يوم القيامة عما كنتم تفترون من هذا التشريع الباطل.", "h": ["تقرير التوحيد بعبادة الله تعالى وحده.", "وجوب الرهبة من الله دون سواه.", "وجوب الدين لله، إذ هو الإله الحق دون غيره.", "كل نعمة بالعبد، صغرت أو كبرت، فهي من الله سبحانه وتعالى.", "تهديد المشركين إن أصرّوا على شركهم وعدم توبتهم.", "التنديد بالمشركين وتشريعهم الباطل بالتحليل والتحريم والإعطاء والمنع."], "k": "«ثم إذا كشف الضر عنكم إذا فريق منكم بربهم يشركون»… دعوت ربي في ضيق فكشفه؛ فهل بقيت على قربي منه بعد الفرج؟"}, {"lbl": "الآيات ٥٧ – ٦٢", "q": "وَيَجۡعَلُونَ لِلَّهِ ٱلۡبَنَٰتِ سُبۡحَٰنَهُۥ وَلَهُم مَّا يَشۡتَهُونَ ﴿٥٧﴾ وَإِذَا بُشِّرَ أَحَدُهُم بِٱلۡأُنثَىٰ ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٞ ﴿٥٨﴾ يَتَوَٰرَىٰ مِنَ ٱلۡقَوۡمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓۚ أَيُمۡسِكُهُۥ عَلَىٰ هُونٍ أَمۡ يَدُسُّهُۥ فِي ٱلتُّرَابِۗ أَلَا سَآءَ مَا يَحۡكُمُونَ ﴿٥٩﴾ لِلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ مَثَلُ ٱلسَّوۡءِۖ وَلِلَّهِ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٦٠﴾ وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ ﴿٦١﴾ وَيَجۡعَلُونَ لِلَّهِ مَا يَكۡرَهُونَۚ وَتَصِفُ أَلۡسِنَتُهُمُ ٱلۡكَذِبَ أَنَّ لَهُمُ ٱلۡحُسۡنَىٰۚ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفۡرَطُونَ ﴿٦٢﴾", "w": [["ويجعلون لله البنات", "إذ قالوا: الملائكة بنات الله."], ["ولهم ما يشتهون", "الذكور من الأولاد."], ["ظلّ وجهه مسودّاً", "متغيّراً بالسواد لما عليه من كرب."], ["وهو كظيم", "ممتلئ بالغم."], ["أم يدسّه في التراب", "يدفن تلك المولودة حية، وهو الوأد."], ["مثل السوء", "الصفة القبيحة."], ["ولله المثل الأعلى", "الصفة العليا، وهي لا إله إلا الله."], ["أن لهم الحسنى", "الجنة، إذ قال بعضهم: ولئن رُجعت إلى ربي إن لي عنده للحسنى."], ["وأنهم مفرطون", "مقدّمون إلى جهنم متروكون فيها."]], "m": "ما زال السياق في بيان أخطاء المشركين في اعتقادهم وسلوكهم: ويجعلون لله البنات، إذ قالوا: الملائكة بنات الله، سبحانه، تنزّه عن الولد والصاحبة، ولهم ما يشتهون من الذكور، في الوقت الذي يكرهون نسبة البنات إليهم، فإذا بُشّر أحدهم بأنثى ظلّ نهاره مسودّ الوجه من الغم، ممتلئاً بالهم، يستتر عن أعين الناس خوفاً من العار، وهو بين أمرين: أن يمسكها في بيته على مذلة وهوان، أو يدفنها حية، ألا ساء ما يحكمون. للذين لا يؤمنون بالآخرة الصفة السوء، لأنهم لا يعملون خيراً ولا يتركون شراً لعدم إيمانهم بالحساب، ولله الصفة الحسنى: لا إله إلا هو، المنزّه عن النقائص، وهو العزيز الحكيم. ولو يؤاخذ الله الناس بظلمهم ما ترك على الأرض من دابة، ولكن يؤخّرهم إلى أجل مسمى لحكم عالية، فإذا جاء أجلهم لا يستأخرون ساعة ولا يستقدمون. ويجعلون لله ما يكرهونه لأنفسهم من البنات والشركاء، وتصف ألسنتهم الكذب أن لهم الجنة، لا جرم أن لهم النار، وأنهم مقدّمون إليها متروكون فيها.", "h": ["بيان الحال الاجتماعية التي كان عليها المشركون، وهي كراهيتهم للبنات خوف العار.", "بيان جهلهم بالرب تعالى، فهم يؤمنون به ويجهلون صفاته حتى نسبوا إليه الولد.", "بيان العلة في ترك الظلمة يتمادون زمناً في الظلم والشر والفساد.", "بيان سوء اعتقاد الذين لا يؤمنون بالآخرة، وهو أنهم ينسبون إلى نفوسهم الحسنى، ويجعلون لله ما يكرهون من البنات والشركاء."], "k": "«وإذا بُشّر أحدهم بالأنثى ظلّ وجهه مسودّاً»… البنت هبة من الله؛ فهل أستقبل عطاياه كلها بالرضا والشكر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 178;
insert into public.tdb_cards(topic, i, body) select 178, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥١ – ٥٦", "q": "۞وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيۡنِ ٱثۡنَيۡنِۖ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ فَإِيَّـٰيَ فَٱرۡهَبُونِ ﴿٥١﴾ وَلَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَهُ ٱلدِّينُ وَاصِبًاۚ أَفَغَيۡرَ ٱللَّهِ تَتَّقُونَ ﴿٥٢﴾ وَمَا بِكُم مِّن نِّعۡمَةٖ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيۡهِ تَجۡـَٔرُونَ ﴿٥٣﴾ ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمۡ إِذَا فَرِيقٞ مِّنكُم بِرَبِّهِمۡ يُشۡرِكُونَ ﴿٥٤﴾ لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ ﴿٥٥﴾ وَيَجۡعَلُونَ لِمَا لَا يَعۡلَمُونَ نَصِيبٗا مِّمَّا رَزَقۡنَٰهُمۡۗ تَٱللَّهِ لَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَفۡتَرُونَ ﴿٥٦﴾", "w": [["لا تتخذوا إلهين", "لا تعبدوهما، إذ ليس لكم إلا إله واحد."], ["وله ما في السماوات والأرض", "خلقاً وملكاً، فما تعبدونه مع الله هو لله."], ["وله الدين واصباً", "خالصاً دائماً واجباً."], ["فإليه تجأرون", "ترفعون أصواتكم بدعائه طالبين الشفاء منه."], ["فتمتعوا فسوف تعلمون", "تهديد على كفرهم وشركهم ونسيانهم دعاء الله تعالى."], ["ويجعلون لما لا يعلمون نصيباً", "يجعلون لآلهتهم نصيباً من الحرث والأنعام."], ["عما كنتم تفترون", "تختلقون بالكذب على الله عز وجل."]], "m": "بعد إقامة الحجج على التوحيد قال لهم ربهم: لا تتخذوا إلهين اثنين، إنما هو إله واحد، فإياي فارهبون وحدي، فبيدي كل شيء وليس لغيري شيء، أنا المحيي المميت الضار النافع. وله ما في السماوات والأرض خلقاً وملكاً، وله العبادة والطاعة خالصة دائمة واجبة، أفغير الله تتّقون وتخافون، وهو الملك الحق القادر على إعطاء النعم وسلبها؟ وما بكم من نعمة، صغرت أو كبرت، من صحة أو مال أو ولد، فمن الله، ودليل ذلك شعوركم الفطري: إذا مسّكم الضر من فقر أو مرض أو خوف غرق فإليه وحده ترفعون أصواتكم بالدعاء، ثم إذا كشف الضر عنكم إذا فريق منكم بربهم يشركون، ليؤول أمرهم إلى كفران ما آتاهم الله، أفهكذا يكون الجزاء؟ فتمتعوا فسوف تعلمون عاقبة كفركم. ويجعلون لأوثانهم التي لا يعلمون عنها شيئاً نصيباً من أموالهم: سيّبوا لها السوائب وبحروا البحائر وجعلوا لها من الحرث، تالله لتُسألنّ يوم القيامة عما كنتم تفترون من هذا التشريع الباطل.", "h": ["تقرير التوحيد بعبادة الله تعالى وحده.", "وجوب الرهبة من الله دون سواه.", "وجوب الدين لله، إذ هو الإله الحق دون غيره.", "كل نعمة بالعبد، صغرت أو كبرت، فهي من الله سبحانه وتعالى.", "تهديد المشركين إن أصرّوا على شركهم وعدم توبتهم.", "التنديد بالمشركين وتشريعهم الباطل بالتحليل والتحريم والإعطاء والمنع."], "k": "«ثم إذا كشف الضر عنكم إذا فريق منكم بربهم يشركون»… دعوت ربي في ضيق فكشفه؛ فهل بقيت على قربي منه بعد الفرج؟"}, {"lbl": "الآيات ٥٧ – ٦٢", "q": "وَيَجۡعَلُونَ لِلَّهِ ٱلۡبَنَٰتِ سُبۡحَٰنَهُۥ وَلَهُم مَّا يَشۡتَهُونَ ﴿٥٧﴾ وَإِذَا بُشِّرَ أَحَدُهُم بِٱلۡأُنثَىٰ ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٞ ﴿٥٨﴾ يَتَوَٰرَىٰ مِنَ ٱلۡقَوۡمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓۚ أَيُمۡسِكُهُۥ عَلَىٰ هُونٍ أَمۡ يَدُسُّهُۥ فِي ٱلتُّرَابِۗ أَلَا سَآءَ مَا يَحۡكُمُونَ ﴿٥٩﴾ لِلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ مَثَلُ ٱلسَّوۡءِۖ وَلِلَّهِ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ﴿٦٠﴾ وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ ﴿٦١﴾ وَيَجۡعَلُونَ لِلَّهِ مَا يَكۡرَهُونَۚ وَتَصِفُ أَلۡسِنَتُهُمُ ٱلۡكَذِبَ أَنَّ لَهُمُ ٱلۡحُسۡنَىٰۚ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفۡرَطُونَ ﴿٦٢﴾", "w": [["ويجعلون لله البنات", "إذ قالوا: الملائكة بنات الله."], ["ولهم ما يشتهون", "الذكور من الأولاد."], ["ظلّ وجهه مسودّاً", "متغيّراً بالسواد لما عليه من كرب."], ["وهو كظيم", "ممتلئ بالغم."], ["أم يدسّه في التراب", "يدفن تلك المولودة حية، وهو الوأد."], ["مثل السوء", "الصفة القبيحة."], ["ولله المثل الأعلى", "الصفة العليا، وهي لا إله إلا الله."], ["أن لهم الحسنى", "الجنة، إذ قال بعضهم: ولئن رُجعت إلى ربي إن لي عنده للحسنى."], ["وأنهم مفرطون", "مقدّمون إلى جهنم متروكون فيها."]], "m": "ما زال السياق في بيان أخطاء المشركين في اعتقادهم وسلوكهم: ويجعلون لله البنات، إذ قالوا: الملائكة بنات الله، سبحانه، تنزّه عن الولد والصاحبة، ولهم ما يشتهون من الذكور، في الوقت الذي يكرهون نسبة البنات إليهم، فإذا بُشّر أحدهم بأنثى ظلّ نهاره مسودّ الوجه من الغم، ممتلئاً بالهم، يستتر عن أعين الناس خوفاً من العار، وهو بين أمرين: أن يمسكها في بيته على مذلة وهوان، أو يدفنها حية، ألا ساء ما يحكمون. للذين لا يؤمنون بالآخرة الصفة السوء، لأنهم لا يعملون خيراً ولا يتركون شراً لعدم إيمانهم بالحساب، ولله الصفة الحسنى: لا إله إلا هو، المنزّه عن النقائص، وهو العزيز الحكيم. ولو يؤاخذ الله الناس بظلمهم ما ترك على الأرض من دابة، ولكن يؤخّرهم إلى أجل مسمى لحكم عالية، فإذا جاء أجلهم لا يستأخرون ساعة ولا يستقدمون. ويجعلون لله ما يكرهونه لأنفسهم من البنات والشركاء، وتصف ألسنتهم الكذب أن لهم الجنة، لا جرم أن لهم النار، وأنهم مقدّمون إليها متروكون فيها.", "h": ["بيان الحال الاجتماعية التي كان عليها المشركون، وهي كراهيتهم للبنات خوف العار.", "بيان جهلهم بالرب تعالى، فهم يؤمنون به ويجهلون صفاته حتى نسبوا إليه الولد.", "بيان العلة في ترك الظلمة يتمادون زمناً في الظلم والشر والفساد.", "بيان سوء اعتقاد الذين لا يؤمنون بالآخرة، وهو أنهم ينسبون إلى نفوسهم الحسنى، ويجعلون لله ما يكرهون من البنات والشركاء."], "k": "«وإذا بُشّر أحدهم بالأنثى ظلّ وجهه مسودّاً»… البنت هبة من الله؛ فهل أستقبل عطاياه كلها بالرضا والشكر؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (179, 16, 63, 70, 'سورة النحل ٦٣ – ٧٠', 'إحياء الأرض بالماء، واللبن من بين فرث ودم، والنحل وشفاء العسل', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 179) = $j$[{"lbl": "الآيات ٦٣ – ٦٦", "q": "تَٱللَّهِ لَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٦٣﴾ وَمَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِي ٱخۡتَلَفُواْ فِيهِ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٦٤﴾ وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَسۡمَعُونَ ﴿٦٥﴾ وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثٖ وَدَمٖ لَّبَنًا خَالِصٗا سَآئِغٗا لِّلشَّـٰرِبِينَ ﴿٦٦﴾", "w": [["تالله", "والله."], ["أرسلنا إلى أمم من قبلك", "أرسلنا رسلاً."], ["فزيّن لهم الشيطان أعمالهم", "فكذّبوا لذلك الرسل."], ["فهو وليّهم اليوم", "الشيطان هو وليّهم اليوم، أي في الدنيا."], ["إن في ذلك لآية", "دلالة واضحة على صحة عقيدة البعث الآخر."], ["لقوم يسمعون", "سماع تدبّر وتفهّم."], ["لعبرة", "دلالة قوية يُعبر بها من الجهل إلى العلم، لأن العبرة من العبور."], ["من بين فرث", "ثُفل الكرش، أي الروث الموجود فيه."], ["لبناً خالصاً", "ليس فيه شيء من الفرث ولا الدم، لا لونه ولا رائحته ولا طعمه."]], "m": "يقسم الله تعالى بنفسه لرسوله: تالله لقد أرسلنا رسلاً إلى أمم من قبلك كانوا مشركين كأمتك، فزيّن لهم الشيطان أعمالهم فقاوموا الرسل وأصرّوا على الكفر، فهو وليّهم اليوم في الدنيا، ولهم في الآخرة عذاب أليم، والسياق في تسلية الرسول ﷺ. وما أنزلنا عليك الكتاب لإرهاقك، ولكن لتبيّن للناس الذي اختلفوا فيه من التوحيد والشرك والهدى والضلال، وهدى ورحمة لقوم يؤمنون، فيعيشون متراحمين تسودهم الأخوة والمحبة. ثم عاد السياق إلى الدعوة إلى التوحيد والبعث: والله أنزل من السماء ماء المطر فأحيا به الأرض بالنبات بعد موتها، إن في ذلك لآية على وجوده وقدرته ورحمته، وعلى البعث بعد الموت من باب أولى، لقوم يسمعون سماع تدبّر. وإن لكم في الأنعام لعبرة تعبرون بها إلى العلم بالله: نسقيكم مما في بطونها من بين فرث ودم لبناً خالصاً سائغاً للشاربين، فالدم ينتقل إلى الكبد فتوزّعه على العروق، واللبن يُساق إلى الضرع، والفرث يبقى أسفل الكرش، ويخرج اللبن خالصاً لا يُرى أثرهما في لونه ولا يُشمّ في رائحته ولا يوجد في طعمه، فلا يغصّ به شارب، إنها عبرة تورث محبة الله وتدفع إلى طاعته.", "h": ["بيان أن الله يقسم بنفسه وبما شاء من خلقه.", "بيان أن الله أرسل رسلاً إلى أمم سبقت، وأن الشيطان زيّن لها أعمالها فخذلها.", "تقرير النبوة، وتسلية رسول الله ﷺ من جراء ما يلقاه من المشركين.", "بيان مهمة رسول الله ﷺ، وأنها بيان ما أنزل الله تعالى لعباده من وحيه في كتابه.", "دليل البعث والحياة الثانية إحياء الأرض بعد موتها، فالقادر على إحياء الأرض بعد موتها قادر على إحياء الأموات بعد فنائهم وبلاهم."], "k": "«لبناً خالصاً سائغاً للشاربين»… كوب لبن واحد يحمل آية؛ فهل أشربه شاكراً متفكراً؟"}, {"lbl": "الآيات ٦٧ – ٧٠", "q": "وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرٗا وَرِزۡقًا حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٦٧﴾ وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتٗا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ ﴿٦٨﴾ ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿٦٩﴾ وَٱللَّهُ خَلَقَكُمۡ ثُمَّ يَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡ لَا يَعۡلَمَ بَعۡدَ عِلۡمٖ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمٞ قَدِيرٞ ﴿٧٠﴾", "w": [["ومن ثمرات النخيل والأعناب", "ومن بعض ثمراتها ثمر تتخذون منه سكراً، أي خمراً، ورزقاً حسناً كالتمر والزبيب والخل والدبس."], ["وأوحى ربك إلى النحل", "ألهمها أن تفعل ما تفعله بإلهام منه تعالى."], ["ومما يعرشون", "مما يبنون لها."], ["سبل ربك ذللاً", "طرق ربك مذلّلة، فلا يعسر عليك السير فيها."], ["شراب", "عسل."], ["فيه شفاء للناس", "من الأمراض إن شُرب بنية الشفاء، أو بضميمته إلى عقار آخر."], ["إلى أرذل العمر", "أخسّه، من الهرم والخرف، والخرف فساد العقل."]], "m": "ما زال السياق في ذكر مظاهر قدرة الله وعلمه وحكمته ورحمته بأسلوب الامتنان المقتضي للشكر: ومن ثمرات النخيل والأعناب تتخذون منه سكراً، وهذا كان قبل تحريم الخمر، ورزقاً حسناً كالزبيب والخل والتمر والدبس، إن في ذلك لآية لقوم يعقلون. وأوحى ربك إلى النحل، ألهمها، أن اتخذي من الجبال بيوتاً ومن الشجر ومما يبني لك الناس من العرائش، ثم كلي من أزهار كل الثمرات، فاسلكي طرق ربك مذلّلة، تنتقلين من مكان إلى آخر ثم تعودين إلى بيوتك لا تعجزين ولا تضلين، يخرج من بطونها عسل مختلف ألوانه، ما بين أبيض وأحمر وأصفر، فيه شفاء للناس، وفي الصحيح أن رجلاً شكا إلى رسول الله ﷺ استطلاق بطن أخيه، فقال: «اسقه العسل»، فسقاه فلم يبرأ، حتى قال في الثالثة: «صدق الله وكذب بطن أخيك، اسقه العسل»، فسقاه فبرأ. إن في ذلك لآية لقوم يتفكرون. والله خلقكم ثم يتوفّاكم في آجال مختلفة اقتضتها الحكمة، فمنكم من يموت طفلاً، ومنكم من يموت شاباً، ومنكم من يُردّ إلى أرذل العمر فيهرم ويخرف لكي لا يعلم بعد علم شيئاً، إن الله عليم قدير.", "h": ["بيان منّة الله تعالى على العباد بذكر بعض أرزاقهم لهم ليشكروا الله على نعمه.", "بيان آيات الله تعالى الدالة على قدرته وعلمه وحكمته في خلق شراب الإنسان وغذائه.", "فضيلة العقل والتعقّل، والفكر والتفكّر.", "تقرير عقيدة الإيمان باليوم الآخر الدال عليه القدرة والعلم الإلهيان، إذ من خلق وأمات لا يُستنكر منه أن يخلق مرة أخرى."], "k": "«ومنكم من يُردّ إلى أرذل العمر»… القوة التي معي اليوم لن تدوم؛ ففي أي شيء أستثمرها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 179;
insert into public.tdb_cards(topic, i, body) select 179, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٣ – ٦٦", "q": "تَٱللَّهِ لَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿٦٣﴾ وَمَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِي ٱخۡتَلَفُواْ فِيهِ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٦٤﴾ وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَسۡمَعُونَ ﴿٦٥﴾ وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثٖ وَدَمٖ لَّبَنًا خَالِصٗا سَآئِغٗا لِّلشَّـٰرِبِينَ ﴿٦٦﴾", "w": [["تالله", "والله."], ["أرسلنا إلى أمم من قبلك", "أرسلنا رسلاً."], ["فزيّن لهم الشيطان أعمالهم", "فكذّبوا لذلك الرسل."], ["فهو وليّهم اليوم", "الشيطان هو وليّهم اليوم، أي في الدنيا."], ["إن في ذلك لآية", "دلالة واضحة على صحة عقيدة البعث الآخر."], ["لقوم يسمعون", "سماع تدبّر وتفهّم."], ["لعبرة", "دلالة قوية يُعبر بها من الجهل إلى العلم، لأن العبرة من العبور."], ["من بين فرث", "ثُفل الكرش، أي الروث الموجود فيه."], ["لبناً خالصاً", "ليس فيه شيء من الفرث ولا الدم، لا لونه ولا رائحته ولا طعمه."]], "m": "يقسم الله تعالى بنفسه لرسوله: تالله لقد أرسلنا رسلاً إلى أمم من قبلك كانوا مشركين كأمتك، فزيّن لهم الشيطان أعمالهم فقاوموا الرسل وأصرّوا على الكفر، فهو وليّهم اليوم في الدنيا، ولهم في الآخرة عذاب أليم، والسياق في تسلية الرسول ﷺ. وما أنزلنا عليك الكتاب لإرهاقك، ولكن لتبيّن للناس الذي اختلفوا فيه من التوحيد والشرك والهدى والضلال، وهدى ورحمة لقوم يؤمنون، فيعيشون متراحمين تسودهم الأخوة والمحبة. ثم عاد السياق إلى الدعوة إلى التوحيد والبعث: والله أنزل من السماء ماء المطر فأحيا به الأرض بالنبات بعد موتها، إن في ذلك لآية على وجوده وقدرته ورحمته، وعلى البعث بعد الموت من باب أولى، لقوم يسمعون سماع تدبّر. وإن لكم في الأنعام لعبرة تعبرون بها إلى العلم بالله: نسقيكم مما في بطونها من بين فرث ودم لبناً خالصاً سائغاً للشاربين، فالدم ينتقل إلى الكبد فتوزّعه على العروق، واللبن يُساق إلى الضرع، والفرث يبقى أسفل الكرش، ويخرج اللبن خالصاً لا يُرى أثرهما في لونه ولا يُشمّ في رائحته ولا يوجد في طعمه، فلا يغصّ به شارب، إنها عبرة تورث محبة الله وتدفع إلى طاعته.", "h": ["بيان أن الله يقسم بنفسه وبما شاء من خلقه.", "بيان أن الله أرسل رسلاً إلى أمم سبقت، وأن الشيطان زيّن لها أعمالها فخذلها.", "تقرير النبوة، وتسلية رسول الله ﷺ من جراء ما يلقاه من المشركين.", "بيان مهمة رسول الله ﷺ، وأنها بيان ما أنزل الله تعالى لعباده من وحيه في كتابه.", "دليل البعث والحياة الثانية إحياء الأرض بعد موتها، فالقادر على إحياء الأرض بعد موتها قادر على إحياء الأموات بعد فنائهم وبلاهم."], "k": "«لبناً خالصاً سائغاً للشاربين»… كوب لبن واحد يحمل آية؛ فهل أشربه شاكراً متفكراً؟"}, {"lbl": "الآيات ٦٧ – ٧٠", "q": "وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرٗا وَرِزۡقًا حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡقِلُونَ ﴿٦٧﴾ وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتٗا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ ﴿٦٨﴾ ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ ﴿٦٩﴾ وَٱللَّهُ خَلَقَكُمۡ ثُمَّ يَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡ لَا يَعۡلَمَ بَعۡدَ عِلۡمٖ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمٞ قَدِيرٞ ﴿٧٠﴾", "w": [["ومن ثمرات النخيل والأعناب", "ومن بعض ثمراتها ثمر تتخذون منه سكراً، أي خمراً، ورزقاً حسناً كالتمر والزبيب والخل والدبس."], ["وأوحى ربك إلى النحل", "ألهمها أن تفعل ما تفعله بإلهام منه تعالى."], ["ومما يعرشون", "مما يبنون لها."], ["سبل ربك ذللاً", "طرق ربك مذلّلة، فلا يعسر عليك السير فيها."], ["شراب", "عسل."], ["فيه شفاء للناس", "من الأمراض إن شُرب بنية الشفاء، أو بضميمته إلى عقار آخر."], ["إلى أرذل العمر", "أخسّه، من الهرم والخرف، والخرف فساد العقل."]], "m": "ما زال السياق في ذكر مظاهر قدرة الله وعلمه وحكمته ورحمته بأسلوب الامتنان المقتضي للشكر: ومن ثمرات النخيل والأعناب تتخذون منه سكراً، وهذا كان قبل تحريم الخمر، ورزقاً حسناً كالزبيب والخل والتمر والدبس، إن في ذلك لآية لقوم يعقلون. وأوحى ربك إلى النحل، ألهمها، أن اتخذي من الجبال بيوتاً ومن الشجر ومما يبني لك الناس من العرائش، ثم كلي من أزهار كل الثمرات، فاسلكي طرق ربك مذلّلة، تنتقلين من مكان إلى آخر ثم تعودين إلى بيوتك لا تعجزين ولا تضلين، يخرج من بطونها عسل مختلف ألوانه، ما بين أبيض وأحمر وأصفر، فيه شفاء للناس، وفي الصحيح أن رجلاً شكا إلى رسول الله ﷺ استطلاق بطن أخيه، فقال: «اسقه العسل»، فسقاه فلم يبرأ، حتى قال في الثالثة: «صدق الله وكذب بطن أخيك، اسقه العسل»، فسقاه فبرأ. إن في ذلك لآية لقوم يتفكرون. والله خلقكم ثم يتوفّاكم في آجال مختلفة اقتضتها الحكمة، فمنكم من يموت طفلاً، ومنكم من يموت شاباً، ومنكم من يُردّ إلى أرذل العمر فيهرم ويخرف لكي لا يعلم بعد علم شيئاً، إن الله عليم قدير.", "h": ["بيان منّة الله تعالى على العباد بذكر بعض أرزاقهم لهم ليشكروا الله على نعمه.", "بيان آيات الله تعالى الدالة على قدرته وعلمه وحكمته في خلق شراب الإنسان وغذائه.", "فضيلة العقل والتعقّل، والفكر والتفكّر.", "تقرير عقيدة الإيمان باليوم الآخر الدال عليه القدرة والعلم الإلهيان، إذ من خلق وأمات لا يُستنكر منه أن يخلق مرة أخرى."], "k": "«ومنكم من يُردّ إلى أرذل العمر»… القوة التي معي اليوم لن تدوم؛ ففي أي شيء أستثمرها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (180, 16, 71, 78, 'سورة النحل ٧١ – ٧٨', '«والله فضّل بعضكم على بعض في الرزق»، والأزواج والحفدة، ومثلا العبد المملوك والأبكم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 180) = $j$[{"lbl": "الآيات ٧١ – ٧٤", "q": "وَٱللَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖ فِي ٱلرِّزۡقِۚ فَمَا ٱلَّذِينَ فُضِّلُواْ بِرَآدِّي رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَهُمۡ فِيهِ سَوَآءٌۚ أَفَبِنِعۡمَةِ ٱللَّهِ يَجۡحَدُونَ ﴿٧١﴾ وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةٗ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَتِ ٱللَّهِ هُمۡ يَكۡفُرُونَ ﴿٧٢﴾ وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَهُمۡ رِزۡقٗا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ شَيۡـٔٗا وَلَا يَسۡتَطِيعُونَ ﴿٧٣﴾ فَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ﴿٧٤﴾", "w": [["فضّل بعضكم على بعض في الرزق", "فمنكم الغني ومنكم الفقير، ومنكم المالك ومنكم المملوك."], ["برادّي رزقهم على ما ملكت أيمانهم", "بجاعلي ما رزقناهم شركة بينهم وبين مماليكهم من العبيد."], ["جعل لكم من أنفسكم أزواجاً", "إذ حواء خُلقت من آدم، وسائر النساء من نطف الرجال."], ["وحفدة", "خدماً من زوج وولد وولد ولد وخادم وختن."], ["أفبالباطل يؤمنون", "بعبادة الأصنام يؤمنون."], ["رزقاً من السماوات والأرض", "بإنزال المطر من السماء، وإنبات النبات من الأرض."]], "m": "ما زال السياق في تقرير التوحيد وإبطال الشرك: والله فضّل بعضكم على بعض في الرزق، فمنكم الغني ومنكم الفقير، وقد يكون لأحدكم عبيد مملوكون، فلا يرضى أن يشركهم في ماله حتى يكونوا فيه سواء، ويقول: كيف أسوّي مملوكي في رزقي؟ فكيف جوّزتم إشراك آلهتكم في عبادة ربكم وهي مملوكة له؟ أفبنعمة الله يجحدون؟ جحدوا نعمة العقل فلم يفكروا، وجحدوا نعمة الخلق والرزق فعبدوا غيره. والله جعل لكم من أنفسكم أزواجاً من جنسكم تسكنون إليهن وتتعاونون، وجعل لكم منهن بنين وحفدة، كل من يسارع في خدمتك من زوجة وولد وولد ولد وصهر وخادم، ورزقكم من الطيبات من حلال الطعام والشراب، أفبالباطل يؤمنون وبنعمة الله هم يكفرون؟ ويعبدون من دون الله ما لا يملك لهم رزقاً من السماء بالمطر، ولا من الأرض بالنبات، ولا يستطيعون، لأنها تماثيل منحوتة. فلا تضربوا لله الأمثال، باتخاذ الأصنام آلهة، واعتقاد أنها شفعاء تقرّبهم إليه، وأنها واسطة كالوزير للأمير، إن الله يعلم أنه لا مثل له، وأنتم لا تعلمون فلذا أنتم متخبّطون في ظلمات الشرك.", "h": ["قطع دابر الشرك في المثل الذي حوته الآية الأولى: «والله فضّل بعضكم على بعض في الرزق».", "وجوب شكر الله تعالى على نعمه، وذلك بذكره وشكره وإخلاص ذلك له.", "قبح كفر النعم وتجاهل المنعم بترك شكره عليها.", "التنديد بمن يضربون لله الأمثال وهم لا يعلمون، باتخاذ وسائط له تشبيهاً لله تعالى بعباده، فهم يتوسّطون بالأولياء والأنبياء بدعائهم والاستغاثة بهم."], "k": "«وجعل لكم من أزواجكم بنين وحفدة»… أهل بيتي الذين يخدمونني نعمة؛ فهل أشكر الله عليهم وأحسن إليهم؟"}, {"lbl": "الآيات ٧٥ – ٧٨", "q": "۞ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدٗا مَّمۡلُوكٗا لَّا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنٗا فَهُوَ يُنفِقُ مِنۡهُ سِرّٗا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿٧٥﴾ وَضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلَيۡنِ أَحَدُهُمَآ أَبۡكَمُ لَا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ هَلۡ يَسۡتَوِي هُوَ وَمَن يَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٧٦﴾ وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَآ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ ٱلۡبَصَرِ أَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٧٧﴾ وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمۡ لَا تَعۡلَمُونَ شَيۡـٔٗا وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٧٨﴾", "w": [["ضرب الله مثلاً عبداً مملوكاً", "ليس بحرّ، بل هو عبد مملوك لغيره."], ["هل يستوون", "العبيد العجزة والحر المتصرّف؟ والجواب: لا يستوون قطعاً."], ["أبكم", "أخرس، وأصمّ لا يسمع."], ["لا يقدر على شيء", "لا يُفهم غيره ولا يَفهم."], ["ولله غيب السماوات والأرض", "ما غاب فيهما."], ["وما أمر الساعة", "أمر قيامها، وذلك بإماتة الأحياء وإحيائهم مع من مات قبل، وتبديل صور الأكوان كلها."], ["الأفئدة", "القلوب."]], "m": "ما زال السياق في تقرير التوحيد وإبطال الشرك، وقد جهّل الله المشركين في ضرب الأمثال له، وهنا ضرب تعالى مثلين وهو العليم الخبير: عبداً مملوكاً لا يقدر على شيء، لا حق له في التصرف في مال سيده، وحراً رزقناه رزقاً حسناً فهو ينفق منه سراً وجهراً، هل يستوون؟ لا، الحمد لله، بل أكثرهم لا يعلمون، والمثل للكافر الأسير للأصنام لا ينفق في سبيل الله لأنه لا يؤمن بالآخرة، والمؤمن الحر يعمل بطاعة الله وينفق سراً وجهراً يبتغي الآخرة. والمثل الثاني: رجلان أحدهما أبكم أصمّ لا يقدر على شيء، وهو عالة على من يتولاه، أينما يوجّهه لا يأت بخير، وهذا مثل الأصنام لا تسمع ولا تفهم وهي محتاجة إلى عابديها في صنعها وحملها وحمايتها، هل يستوي هو ومن يأمر بالعدل، وهو الله، وهو على صراط مستقيم يدعو الناس إلى سلوكه؟ لا يستويان بحال. ولله غيب السماوات والأرض، وما أمر الساعة إلا كلمح البصر أو هو أقرب، إذ لا يتوقف إلا على كلمة «كن». والله أخرجكم من بطون أمهاتكم لا تعلمون شيئاً، وجعل لكم السمع والأبصار والأفئدة، لعلكم تشكرون، فقد جعلنا نسمع ونبصر ونعقل ليكلّفنا فنطيعه، وذلك شكره منا، وهو إعداد للسعادة في الدارين.", "h": ["مشروعية ضرب الأمثال، وهو تشبيه حال بحال، على أن يكون ضارب المثل عالماً.", "بيان مثل المؤمن في كماله، والكافر في نقصانه.", "بيان مثل الأصنام في جمودها، وتعب عبدتها عليها في الحماية، وعدم انتفاعهم بها.", "مثل الرب تبارك وتعالى في عدله، ودعوته إلى الإسلام، وقيامه على ذلك، مع استجابة دعاء أوليائه ورعايتهم ونصرتهم، ولله المثل الأعلى وهو العزيز الحكيم."], "k": "«وجعل لكم السمع والأبصار والأفئدة لعلكم تشكرون»… ماذا سمعت وأبصرت اليوم؟ وهل كان شكراً أم غفلة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 180;
insert into public.tdb_cards(topic, i, body) select 180, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧١ – ٧٤", "q": "وَٱللَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖ فِي ٱلرِّزۡقِۚ فَمَا ٱلَّذِينَ فُضِّلُواْ بِرَآدِّي رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَهُمۡ فِيهِ سَوَآءٌۚ أَفَبِنِعۡمَةِ ٱللَّهِ يَجۡحَدُونَ ﴿٧١﴾ وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةٗ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَتِ ٱللَّهِ هُمۡ يَكۡفُرُونَ ﴿٧٢﴾ وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَهُمۡ رِزۡقٗا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ شَيۡـٔٗا وَلَا يَسۡتَطِيعُونَ ﴿٧٣﴾ فَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ﴿٧٤﴾", "w": [["فضّل بعضكم على بعض في الرزق", "فمنكم الغني ومنكم الفقير، ومنكم المالك ومنكم المملوك."], ["برادّي رزقهم على ما ملكت أيمانهم", "بجاعلي ما رزقناهم شركة بينهم وبين مماليكهم من العبيد."], ["جعل لكم من أنفسكم أزواجاً", "إذ حواء خُلقت من آدم، وسائر النساء من نطف الرجال."], ["وحفدة", "خدماً من زوج وولد وولد ولد وخادم وختن."], ["أفبالباطل يؤمنون", "بعبادة الأصنام يؤمنون."], ["رزقاً من السماوات والأرض", "بإنزال المطر من السماء، وإنبات النبات من الأرض."]], "m": "ما زال السياق في تقرير التوحيد وإبطال الشرك: والله فضّل بعضكم على بعض في الرزق، فمنكم الغني ومنكم الفقير، وقد يكون لأحدكم عبيد مملوكون، فلا يرضى أن يشركهم في ماله حتى يكونوا فيه سواء، ويقول: كيف أسوّي مملوكي في رزقي؟ فكيف جوّزتم إشراك آلهتكم في عبادة ربكم وهي مملوكة له؟ أفبنعمة الله يجحدون؟ جحدوا نعمة العقل فلم يفكروا، وجحدوا نعمة الخلق والرزق فعبدوا غيره. والله جعل لكم من أنفسكم أزواجاً من جنسكم تسكنون إليهن وتتعاونون، وجعل لكم منهن بنين وحفدة، كل من يسارع في خدمتك من زوجة وولد وولد ولد وصهر وخادم، ورزقكم من الطيبات من حلال الطعام والشراب، أفبالباطل يؤمنون وبنعمة الله هم يكفرون؟ ويعبدون من دون الله ما لا يملك لهم رزقاً من السماء بالمطر، ولا من الأرض بالنبات، ولا يستطيعون، لأنها تماثيل منحوتة. فلا تضربوا لله الأمثال، باتخاذ الأصنام آلهة، واعتقاد أنها شفعاء تقرّبهم إليه، وأنها واسطة كالوزير للأمير، إن الله يعلم أنه لا مثل له، وأنتم لا تعلمون فلذا أنتم متخبّطون في ظلمات الشرك.", "h": ["قطع دابر الشرك في المثل الذي حوته الآية الأولى: «والله فضّل بعضكم على بعض في الرزق».", "وجوب شكر الله تعالى على نعمه، وذلك بذكره وشكره وإخلاص ذلك له.", "قبح كفر النعم وتجاهل المنعم بترك شكره عليها.", "التنديد بمن يضربون لله الأمثال وهم لا يعلمون، باتخاذ وسائط له تشبيهاً لله تعالى بعباده، فهم يتوسّطون بالأولياء والأنبياء بدعائهم والاستغاثة بهم."], "k": "«وجعل لكم من أزواجكم بنين وحفدة»… أهل بيتي الذين يخدمونني نعمة؛ فهل أشكر الله عليهم وأحسن إليهم؟"}, {"lbl": "الآيات ٧٥ – ٧٨", "q": "۞ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدٗا مَّمۡلُوكٗا لَّا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنٗا فَهُوَ يُنفِقُ مِنۡهُ سِرّٗا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿٧٥﴾ وَضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلَيۡنِ أَحَدُهُمَآ أَبۡكَمُ لَا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ هَلۡ يَسۡتَوِي هُوَ وَمَن يَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿٧٦﴾ وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَآ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ ٱلۡبَصَرِ أَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٧٧﴾ وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمۡ لَا تَعۡلَمُونَ شَيۡـٔٗا وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ ﴿٧٨﴾", "w": [["ضرب الله مثلاً عبداً مملوكاً", "ليس بحرّ، بل هو عبد مملوك لغيره."], ["هل يستوون", "العبيد العجزة والحر المتصرّف؟ والجواب: لا يستوون قطعاً."], ["أبكم", "أخرس، وأصمّ لا يسمع."], ["لا يقدر على شيء", "لا يُفهم غيره ولا يَفهم."], ["ولله غيب السماوات والأرض", "ما غاب فيهما."], ["وما أمر الساعة", "أمر قيامها، وذلك بإماتة الأحياء وإحيائهم مع من مات قبل، وتبديل صور الأكوان كلها."], ["الأفئدة", "القلوب."]], "m": "ما زال السياق في تقرير التوحيد وإبطال الشرك، وقد جهّل الله المشركين في ضرب الأمثال له، وهنا ضرب تعالى مثلين وهو العليم الخبير: عبداً مملوكاً لا يقدر على شيء، لا حق له في التصرف في مال سيده، وحراً رزقناه رزقاً حسناً فهو ينفق منه سراً وجهراً، هل يستوون؟ لا، الحمد لله، بل أكثرهم لا يعلمون، والمثل للكافر الأسير للأصنام لا ينفق في سبيل الله لأنه لا يؤمن بالآخرة، والمؤمن الحر يعمل بطاعة الله وينفق سراً وجهراً يبتغي الآخرة. والمثل الثاني: رجلان أحدهما أبكم أصمّ لا يقدر على شيء، وهو عالة على من يتولاه، أينما يوجّهه لا يأت بخير، وهذا مثل الأصنام لا تسمع ولا تفهم وهي محتاجة إلى عابديها في صنعها وحملها وحمايتها، هل يستوي هو ومن يأمر بالعدل، وهو الله، وهو على صراط مستقيم يدعو الناس إلى سلوكه؟ لا يستويان بحال. ولله غيب السماوات والأرض، وما أمر الساعة إلا كلمح البصر أو هو أقرب، إذ لا يتوقف إلا على كلمة «كن». والله أخرجكم من بطون أمهاتكم لا تعلمون شيئاً، وجعل لكم السمع والأبصار والأفئدة، لعلكم تشكرون، فقد جعلنا نسمع ونبصر ونعقل ليكلّفنا فنطيعه، وذلك شكره منا، وهو إعداد للسعادة في الدارين.", "h": ["مشروعية ضرب الأمثال، وهو تشبيه حال بحال، على أن يكون ضارب المثل عالماً.", "بيان مثل المؤمن في كماله، والكافر في نقصانه.", "بيان مثل الأصنام في جمودها، وتعب عبدتها عليها في الحماية، وعدم انتفاعهم بها.", "مثل الرب تبارك وتعالى في عدله، ودعوته إلى الإسلام، وقيامه على ذلك، مع استجابة دعاء أوليائه ورعايتهم ونصرتهم، ولله المثل الأعلى وهو العزيز الحكيم."], "k": "«وجعل لكم السمع والأبصار والأفئدة لعلكم تشكرون»… ماذا سمعت وأبصرت اليوم؟ وهل كان شكراً أم غفلة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (181, 16, 79, 89, 'سورة النحل ٧٩ – ٨٩', 'الطير المسخّرات والبيوت والسرابيل، و«ونزّلنا عليك الكتاب تبياناً لكل شيء»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 181) = $j$[{"lbl": "الآيات ٧٩ – ٨٣", "q": "أَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ مُسَخَّرَٰتٖ فِي جَوِّ ٱلسَّمَآءِ مَا يُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٧٩﴾ وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمۡ سَكَنٗا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلۡأَنۡعَٰمِ بُيُوتٗا تَسۡتَخِفُّونَهَا يَوۡمَ ظَعۡنِكُمۡ وَيَوۡمَ إِقَامَتِكُمۡ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَآ أَثَٰثٗا وَمَتَٰعًا إِلَىٰ حِينٖ ﴿٨٠﴾ وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلٗا وَجَعَلَ لَكُم مِّنَ ٱلۡجِبَالِ أَكۡنَٰنٗا وَجَعَلَ لَكُمۡ سَرَٰبِيلَ تَقِيكُمُ ٱلۡحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأۡسَكُمۡۚ كَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ ﴿٨١﴾ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿٨٢﴾ يَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكۡثَرُهُمُ ٱلۡكَٰفِرُونَ ﴿٨٣﴾", "w": [["مسخّرات في جو السماء", "مذلّلات في الفضاء بين السماء والأرض، وهو الهواء."], ["ما يمسكهن", "عند قبض أجنحتها وبسطها إلا الله تعالى بقدرته وسننه في خلقه."], ["من بيوتكم سكناً", "مكاناً تسكنون فيه وتخلدون للراحة."], ["من جلود الأنعام بيوتاً", "خياماً وقباباً."], ["يوم ظعنكم", "يوم ارتحالكم في أسفاركم."], ["أثاثاً ومتاعاً إلى حين", "كبُسُط وأكسية تبلى وتتمزّق وتُرمى."], ["ظلالاً ومن الجبال أكناناً", "ما تستظلّون به من حر الشمس، وما تسكنون فيه من غيران الجبال."], ["وسرابيل", "قمصاناً تقيكم الحر والبرد."], ["وسرابيل تقيكم بأسكم", "دروعاً تقيكم الضرب والطعان في الحرب."], ["لعلكم تسلمون", "رجاء أن تسلموا له قلوبكم ووجوهكم فتعبدوه وحده."]], "m": "ما زال السياق في تقرير التوحيد: ألم يروا إلى الطير، على اختلاف أنواعه وكثرة أفراده، مسخّرات في الهواء، تقبض أجنحتها وتبسطها ولا تقع، ما يمسكهن إلا الله، إن في ذلك لآيات لقوم يؤمنون، أحياء القلوب يدركون ويفهمون. والله جعل لكم من بيوتكم موضع سكون وراحة، وجعل لكم من جلود الإبل والبقر والغنم خياماً تجدونها خفيفة المحمل يوم ارتحالكم ويوم إقامتكم، ومن أصوافها وأوبارها وأشعارها أثاثاً كالبُسُط والأكسية تتمتعون به إلى حين بلاه، والله جعل لكم مما خلق ظلالاً تستظلّون بها من حر الشمس، وجعل لكم من الجبال غيراناً وكهوفاً تكنّون فيها من المطر والبرد والحر، وجعل لكم قمصاناً تقيكم الحر والبرد، ودروعاً تقيكم ضرب السيوف وطعن الرماح في الحرب، كذلك يتم نعمته عليكم ببعث رسوله وإنزال كتابه لعلكم تسلمون. فإن أعرضوا عما ذكّرتهم به فلا تحزن، إنما عليك البلاغ المبين وقد بلّغت. يعرفون نعمة الله عليهم ثم ينكرونها فيعبدون غير المنعم بها، وأكثرهم الجاحدون المكذّبون بنبوتك.", "h": ["لا ينتفع بالآيات إلا المؤمنون لحياة قلوبهم، أما الكافرون فهم في ظلمة الكفر لا يرون شيئاً من الآيات ولا يبصرون.", "مظاهر قدرة الله وعلمه وحكمته ورحمته ونعمه تتجلّى في هذه الآيات، ومن العجب أن المشركين كالكافرين عُمي لا يبصرون شيئاً منها.", "مهمة الرسول ﷺ ليست هداية القلوب، وإنما هي بيان الطريق بالبلاغ المبين."], "k": "«يعرفون نعمة الله ثم ينكرونها»… نعمة أعرفها جيداً ثم أنساها حين أعصي؛ ما هي؟"}, {"lbl": "الآيات ٨٤ – ٨٩", "q": "وَيَوۡمَ نَبۡعَثُ مِن كُلِّ أُمَّةٖ شَهِيدٗا ثُمَّ لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُواْ وَلَا هُمۡ يُسۡتَعۡتَبُونَ ﴿٨٤﴾ وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُواْ ٱلۡعَذَابَ فَلَا يُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ يُنظَرُونَ ﴿٨٥﴾ وَإِذَا رَءَا ٱلَّذِينَ أَشۡرَكُواْ شُرَكَآءَهُمۡ قَالُواْ رَبَّنَا هَـٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدۡعُواْ مِن دُونِكَۖ فَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَٰذِبُونَ ﴿٨٦﴾ وَأَلۡقَوۡاْ إِلَى ٱللَّهِ يَوۡمَئِذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٨٧﴾ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ زِدۡنَٰهُمۡ عَذَابٗا فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُواْ يُفۡسِدُونَ ﴿٨٨﴾ وَيَوۡمَ نَبۡعَثُ فِي كُلِّ أُمَّةٖ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ هَـٰٓؤُلَآءِۚ وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ ﴿٨٩﴾", "w": [["ويوم نبعث", "اذكر يوم نبعث."], ["شهيداً", "هو نبيّها."], ["لا يؤذن للذين كفروا", "بالاعتذار فيعتذرون."], ["ولا هم يُستعتبون", "لا يُطلب منهم العُتبى، أي الرجوع إلى اعتقاد وقول وعمل يرضي الله عنهم."], ["وإذا رأى الذين أشركوا شركاءهم", "الذين كانوا يعبدونهم من دون الله كالأصنام."], ["فألقوا إليهم القول", "ردّوا عليهم قائلين لهم: إنكم لكاذبون."], ["وألقوا إلى الله يومئذ السلم", "ذلّوا له وخضعوا لحكمه واستسلموا."], ["وضلّ عنهم ما كانوا يفترون", "من أن آلهتهم تشفع لهم عند الله وتنجيهم من عذابه، ومعنى ضلّ: غاب."], ["عذاباً فوق العذاب", "عقارب وحيّات."], ["ونزّلنا عليك الكتاب", "القرآن."], ["تبياناً لكل شيء", "لكل ما بالأمة من حاجة إليه في معرفة الحلال والحرام، والحق والباطل، والثواب والعقاب."]], "m": "انحصر السياق في هذه الآيات في تقرير البعث والجزاء مع النبوة: اذكر يوم نبعث من كل أمة نبيّها شهيداً عليها، ثم لا يؤذن للذين كفروا بالاعتذار، ولا يُطلب منهم الرجوع إلى ما يرضي الله، لأن الآخرة ليست دار تكليف. وإذا رأى الذين ظلموا العذاب فلا يُخفّف عنهم ولا هم يُمهلون. وإذا رأى المشركون شركاءهم قالوا: ربنا هؤلاء شركاؤنا الذين كنا ندعو من دونك، فردّت عليهم الشركاء: إنكم لكاذبون، واستسلموا لله يومئذ، وغاب عنهم ما كانوا يفترون من أنهم شفعاؤهم ووسيلتهم إلى الله. الذين كفروا وصدّوا غيرهم عن سبيل الله زدناهم عذاباً فوق العذاب الذي استوجبوه بكفرهم، بما كانوا يفسدون. واذكر يوم نبعث في كل أمة شهيداً عليهم من أنفسهم، وجئنا بك شهيداً على أمتك، تشهد على أهل الإيمان بالإيمان، وعلى أهل الشرك بالشرك، إنه لموقف تعظم فيه الحسرة. ونزّلنا عليك القرآن تبياناً لكل ما تحتاج الأمة إلى معرفته من الحلال والحرام والأحكام، وهدى من كل ضلال، ورحمة لمن يعملون به، وبشرى للمسلمين بالأجر العظيم يوم القيامة وبالنصر والكرامة في الدنيا، فلم يبق من عذر لمن يريد أن يعتذر.", "h": ["تقرير عقيدة البعث الآخر بما لا مزيد عليه، لكثرة ألوان العرض لما يجري في ذلك اليوم.", "براءة الشياطين والأصنام الذين أشركهم الناس في عبادة الله من المشركين بهم، والتبرؤ منهم وتكذيبهم.", "زيادة العذاب لمن دعا إلى الشرك والكفر وحمل الناس على ذلك.", "لا عذر لأحد بعد أن أنزل الله تعالى القرآن تبياناً لكل شيء وهدى ورحمة وبشرى للمسلمين."], "k": "«وجئنا بك شهيداً على هؤلاء»… يشهد عليّ رسول الله ﷺ يوم القيامة؛ فبماذا أحب أن يشهد؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 181;
insert into public.tdb_cards(topic, i, body) select 181, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٩ – ٨٣", "q": "أَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ مُسَخَّرَٰتٖ فِي جَوِّ ٱلسَّمَآءِ مَا يُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٧٩﴾ وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمۡ سَكَنٗا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلۡأَنۡعَٰمِ بُيُوتٗا تَسۡتَخِفُّونَهَا يَوۡمَ ظَعۡنِكُمۡ وَيَوۡمَ إِقَامَتِكُمۡ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَآ أَثَٰثٗا وَمَتَٰعًا إِلَىٰ حِينٖ ﴿٨٠﴾ وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلٗا وَجَعَلَ لَكُم مِّنَ ٱلۡجِبَالِ أَكۡنَٰنٗا وَجَعَلَ لَكُمۡ سَرَٰبِيلَ تَقِيكُمُ ٱلۡحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأۡسَكُمۡۚ كَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ ﴿٨١﴾ فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ ٱلۡمُبِينُ ﴿٨٢﴾ يَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكۡثَرُهُمُ ٱلۡكَٰفِرُونَ ﴿٨٣﴾", "w": [["مسخّرات في جو السماء", "مذلّلات في الفضاء بين السماء والأرض، وهو الهواء."], ["ما يمسكهن", "عند قبض أجنحتها وبسطها إلا الله تعالى بقدرته وسننه في خلقه."], ["من بيوتكم سكناً", "مكاناً تسكنون فيه وتخلدون للراحة."], ["من جلود الأنعام بيوتاً", "خياماً وقباباً."], ["يوم ظعنكم", "يوم ارتحالكم في أسفاركم."], ["أثاثاً ومتاعاً إلى حين", "كبُسُط وأكسية تبلى وتتمزّق وتُرمى."], ["ظلالاً ومن الجبال أكناناً", "ما تستظلّون به من حر الشمس، وما تسكنون فيه من غيران الجبال."], ["وسرابيل", "قمصاناً تقيكم الحر والبرد."], ["وسرابيل تقيكم بأسكم", "دروعاً تقيكم الضرب والطعان في الحرب."], ["لعلكم تسلمون", "رجاء أن تسلموا له قلوبكم ووجوهكم فتعبدوه وحده."]], "m": "ما زال السياق في تقرير التوحيد: ألم يروا إلى الطير، على اختلاف أنواعه وكثرة أفراده، مسخّرات في الهواء، تقبض أجنحتها وتبسطها ولا تقع، ما يمسكهن إلا الله، إن في ذلك لآيات لقوم يؤمنون، أحياء القلوب يدركون ويفهمون. والله جعل لكم من بيوتكم موضع سكون وراحة، وجعل لكم من جلود الإبل والبقر والغنم خياماً تجدونها خفيفة المحمل يوم ارتحالكم ويوم إقامتكم، ومن أصوافها وأوبارها وأشعارها أثاثاً كالبُسُط والأكسية تتمتعون به إلى حين بلاه، والله جعل لكم مما خلق ظلالاً تستظلّون بها من حر الشمس، وجعل لكم من الجبال غيراناً وكهوفاً تكنّون فيها من المطر والبرد والحر، وجعل لكم قمصاناً تقيكم الحر والبرد، ودروعاً تقيكم ضرب السيوف وطعن الرماح في الحرب، كذلك يتم نعمته عليكم ببعث رسوله وإنزال كتابه لعلكم تسلمون. فإن أعرضوا عما ذكّرتهم به فلا تحزن، إنما عليك البلاغ المبين وقد بلّغت. يعرفون نعمة الله عليهم ثم ينكرونها فيعبدون غير المنعم بها، وأكثرهم الجاحدون المكذّبون بنبوتك.", "h": ["لا ينتفع بالآيات إلا المؤمنون لحياة قلوبهم، أما الكافرون فهم في ظلمة الكفر لا يرون شيئاً من الآيات ولا يبصرون.", "مظاهر قدرة الله وعلمه وحكمته ورحمته ونعمه تتجلّى في هذه الآيات، ومن العجب أن المشركين كالكافرين عُمي لا يبصرون شيئاً منها.", "مهمة الرسول ﷺ ليست هداية القلوب، وإنما هي بيان الطريق بالبلاغ المبين."], "k": "«يعرفون نعمة الله ثم ينكرونها»… نعمة أعرفها جيداً ثم أنساها حين أعصي؛ ما هي؟"}, {"lbl": "الآيات ٨٤ – ٨٩", "q": "وَيَوۡمَ نَبۡعَثُ مِن كُلِّ أُمَّةٖ شَهِيدٗا ثُمَّ لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُواْ وَلَا هُمۡ يُسۡتَعۡتَبُونَ ﴿٨٤﴾ وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُواْ ٱلۡعَذَابَ فَلَا يُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ يُنظَرُونَ ﴿٨٥﴾ وَإِذَا رَءَا ٱلَّذِينَ أَشۡرَكُواْ شُرَكَآءَهُمۡ قَالُواْ رَبَّنَا هَـٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدۡعُواْ مِن دُونِكَۖ فَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَٰذِبُونَ ﴿٨٦﴾ وَأَلۡقَوۡاْ إِلَى ٱللَّهِ يَوۡمَئِذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٨٧﴾ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ زِدۡنَٰهُمۡ عَذَابٗا فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُواْ يُفۡسِدُونَ ﴿٨٨﴾ وَيَوۡمَ نَبۡعَثُ فِي كُلِّ أُمَّةٖ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ هَـٰٓؤُلَآءِۚ وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ ﴿٨٩﴾", "w": [["ويوم نبعث", "اذكر يوم نبعث."], ["شهيداً", "هو نبيّها."], ["لا يؤذن للذين كفروا", "بالاعتذار فيعتذرون."], ["ولا هم يُستعتبون", "لا يُطلب منهم العُتبى، أي الرجوع إلى اعتقاد وقول وعمل يرضي الله عنهم."], ["وإذا رأى الذين أشركوا شركاءهم", "الذين كانوا يعبدونهم من دون الله كالأصنام."], ["فألقوا إليهم القول", "ردّوا عليهم قائلين لهم: إنكم لكاذبون."], ["وألقوا إلى الله يومئذ السلم", "ذلّوا له وخضعوا لحكمه واستسلموا."], ["وضلّ عنهم ما كانوا يفترون", "من أن آلهتهم تشفع لهم عند الله وتنجيهم من عذابه، ومعنى ضلّ: غاب."], ["عذاباً فوق العذاب", "عقارب وحيّات."], ["ونزّلنا عليك الكتاب", "القرآن."], ["تبياناً لكل شيء", "لكل ما بالأمة من حاجة إليه في معرفة الحلال والحرام، والحق والباطل، والثواب والعقاب."]], "m": "انحصر السياق في هذه الآيات في تقرير البعث والجزاء مع النبوة: اذكر يوم نبعث من كل أمة نبيّها شهيداً عليها، ثم لا يؤذن للذين كفروا بالاعتذار، ولا يُطلب منهم الرجوع إلى ما يرضي الله، لأن الآخرة ليست دار تكليف. وإذا رأى الذين ظلموا العذاب فلا يُخفّف عنهم ولا هم يُمهلون. وإذا رأى المشركون شركاءهم قالوا: ربنا هؤلاء شركاؤنا الذين كنا ندعو من دونك، فردّت عليهم الشركاء: إنكم لكاذبون، واستسلموا لله يومئذ، وغاب عنهم ما كانوا يفترون من أنهم شفعاؤهم ووسيلتهم إلى الله. الذين كفروا وصدّوا غيرهم عن سبيل الله زدناهم عذاباً فوق العذاب الذي استوجبوه بكفرهم، بما كانوا يفسدون. واذكر يوم نبعث في كل أمة شهيداً عليهم من أنفسهم، وجئنا بك شهيداً على أمتك، تشهد على أهل الإيمان بالإيمان، وعلى أهل الشرك بالشرك، إنه لموقف تعظم فيه الحسرة. ونزّلنا عليك القرآن تبياناً لكل ما تحتاج الأمة إلى معرفته من الحلال والحرام والأحكام، وهدى من كل ضلال، ورحمة لمن يعملون به، وبشرى للمسلمين بالأجر العظيم يوم القيامة وبالنصر والكرامة في الدنيا، فلم يبق من عذر لمن يريد أن يعتذر.", "h": ["تقرير عقيدة البعث الآخر بما لا مزيد عليه، لكثرة ألوان العرض لما يجري في ذلك اليوم.", "براءة الشياطين والأصنام الذين أشركهم الناس في عبادة الله من المشركين بهم، والتبرؤ منهم وتكذيبهم.", "زيادة العذاب لمن دعا إلى الشرك والكفر وحمل الناس على ذلك.", "لا عذر لأحد بعد أن أنزل الله تعالى القرآن تبياناً لكل شيء وهدى ورحمة وبشرى للمسلمين."], "k": "«وجئنا بك شهيداً على هؤلاء»… يشهد عليّ رسول الله ﷺ يوم القيامة؛ فبماذا أحب أن يشهد؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (182, 16, 90, 97, 'سورة النحل ٩٠ – ٩٧', '«إن الله يأمر بالعدل والإحسان»، والوفاء بالعهد، و«فلنحيينّه حياة طيبة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 182) = $j$[{"lbl": "الآيات ٩٠ – ٩٣", "q": "۞إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿٩٠﴾ وَأَوۡفُواْ بِعَهۡدِ ٱللَّهِ إِذَا عَٰهَدتُّمۡ وَلَا تَنقُضُواْ ٱلۡأَيۡمَٰنَ بَعۡدَ تَوۡكِيدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَيۡكُمۡ كَفِيلًاۚ إِنَّ ٱللَّهَ يَعۡلَمُ مَا تَفۡعَلُونَ ﴿٩١﴾ وَلَا تَكُونُواْ كَٱلَّتِي نَقَضَتۡ غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَٰثٗا تَتَّخِذُونَ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِيَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا يَبۡلُوكُمُ ٱللَّهُ بِهِۦۚ وَلَيُبَيِّنَنَّ لَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ مَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿٩٢﴾ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ ﴿٩٣﴾", "w": [["العدل", "الإنصاف، ومنه التوحيد."], ["الإحسان", "أداء الفرائض وترك المحارم مع مراقبة الله تعالى."], ["وإيتاء ذي القربى", "إعطاء ذي القربى حقوقهم من الصلة والبر."], ["عن الفحشاء", "الزنا."], ["يعظكم", "يأمركم وينهاكم."], ["توكيدها", "تغليظها."], ["نقضت غزلها", "أفسدت غزلها بعدما غزلته."], ["من بعد قوة", "إحكام له وبرم."], ["أنكاثاً", "جمع نِكث، وهو ما يُنكث ويُحلّ بعد الإبرام."], ["كالتي نقضت غزلها", "هي حمقاء مكة، وتدعى ريطة بنت سعد بن تيم القرشية."], ["دخلاً بينكم", "الدخل ما يدخل في الشيء وهو ليس منه، للإفساد والخديعة."], ["أربى من أمة", "أكثر منها عدداً وقوة."]], "m": "إن الله يأمر في الكتاب الذي أنزله تبياناً لكل شيء بالعدل، وهو الإنصاف، ومنه أن يُعبد الله وحده لأنه الخالق المنعم، ولذا فُسّر بلا إله إلا الله، وبالإحسان، وهو أداء الفرائض واجتناب المحرمات مع مراقبة الله حتى يكون الأداء إتقاناً وجودة والاجتناب حياءً منه، وبإيتاء ذوي القرابات حقوقهم من البر والصلة، وينهى عن الفحشاء، الزنا واللواط وكل قبيح اشتد قبحه، والمنكر، كل ما أنكره الشرع والفطر السليمة، والبغي، الظلم ومجاوزة الحد، يعظكم لعلكم تذكّرون فتمتثلوا، ولذا ورد أن هذه الآية أجمع آية في كتاب الله للخير والشر. وأوفوا بعهد الله إذا عاهدتم، فمن بايع إماماً أو عاهد أحداً وجب عليه الوفاء، إذ لا دين لمن لا عهد له، ولا تنقضوا الأيمان بعد تغليظها وقد جعلتم الله عليكم وكيلاً، إن الله يعلم ما تفعلون. ولا تكونوا كحمقاء مكة التي تغزل ثم تنكث غزلها بعد إحكامه، تتخذون أيمانكم خديعة بينكم، تعاهدون جماعة ثم تنقضون عهدكم لأن جماعة أخرى أكثر رجالاً ومالاً، إنما يختبركم الله بذلك، وليبيّننّ لكم يوم القيامة ما كنتم فيه تختلفون. ولو شاء الله لجعلكم أمة واحدة، ولكن يضل من يشاء ويهدي من يشاء، ولتُسألنّ سؤال توبيخ عما كنتم تعملون.", "h": ["بيان أجمع آية للخير والشر في القرآن، وهي آية: «إن الله يأمر بالعدل والإحسان».", "وجوب العدل والإحسان، وإعطاء ذوي القربى حقوقهم الواجبة من البر والصلة.", "تحريم الزنا واللواط، وكل قبيح اشتد قبحه من الفواحش الظاهرة والباطنة.", "تحريم البغي، وهو الظلم بجميع صوره وأشكاله.", "وجوب الوفاء بالعهود، وحرمة نقضها.", "حرمة نقض الأيمان بعد توكيدها وتوطين النفس عليها، ليخرج لغو اليمين.", "من بايع أميراً أو عاهد أحداً يجب عليه الوفاء، ولا يجوز النقض والنكث لمنافع دنيوية أبداً."], "k": "«ولا تكونوا كالتي نقضت غزلها»… عهد أو وعد أعطيته ثم تهاونت فيه؛ متى أوفي به؟"}, {"lbl": "الآيات ٩٤ – ٩٧", "q": "وَلَا تَتَّخِذُوٓاْ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا وَتَذُوقُواْ ٱلسُّوٓءَ بِمَا صَدَدتُّمۡ عَن سَبِيلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ عَظِيمٞ ﴿٩٤﴾ وَلَا تَشۡتَرُواْ بِعَهۡدِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٩٥﴾ مَا عِندَكُمۡ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٖۗ وَلَنَجۡزِيَنَّ ٱلَّذِينَ صَبَرُوٓاْ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ ﴿٩٦﴾ مَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ ﴿٩٧﴾", "w": [["دخلاً بينكم", "لأجل الإفساد والخديعة."], ["وتذوقوا السوء", "العذاب."], ["ما عندكم ينفد", "يفنى وينتهي."], ["وهو مؤمن", "والحال أنه عندما عمل صالحاً كان مؤمناً."], ["حياة طيبة", "في الدنيا بالقناعة والرزق الحلال، وفي الآخرة هي حياة الجنة."], ["بأحسن ما كانوا يعملون", "يجزيهم على كل أعمالهم بحسب أحسنها."]], "m": "ما زال السياق في تربية المؤمنين أهل القرآن: ولا تتخذوا أيمانكم خديعة بينكم لتتوصلوا بها إلى غرض دنيوي، فتزلّ قدم أحدكم بعد ثبوتها في الإسلام، وتذوقوا السوء في الدنيا بما صددتم عن سبيل الله من عاهدتموهم ثم نقضتم، فينصرفون عن الإسلام بسبب ما رأوا منكم، ولكم عذاب عظيم يوم القيامة. ولا تشتروا بعهد الله ثمناً قليلاً، وكل ما في الدنيا قليل، إنما عند الله هو خير لكم إن كنتم تعلمون، ما عندكم من مال ومتاع ينفد ويفنى، وما عند الله باقٍ لا نفاد له، فلا تبيعوا الباقي بالفاني. ولنجزينّ الذين صبروا على عهودهم أجرهم بأحسن ما كانوا يعملون، فيضاعف لهم الأجر حتى يكون أجر النافلة كأجر الفريضة. من عمل صالحاً من ذكر أو أنثى وهو مؤمن، الإيمان الحق الذي يدفع إلى العمل الصالح ويخلّيه من الشرك والمعاصي، فلنحيينّه حياة طيبة في الدنيا، لا خبث فيها: قناعة وطيب طعام وشراب ورضا، وفي الآخرة الجنة، ولنجزينّهم أجرهم بأحسن ما كانوا يعملون، في الصلاة كأفضل صلاة، وفي الصدقة كأفضل صدقة.", "h": ["حرمة اتخاذ الأيمان طريقاً إلى الغش والخديعة والإفساد.", "ما عند الله خير مما يحصل عليه الإنسان بمعصية الرحمن من حطام الدنيا.", "عظم أجر الصبر على طاعة الله تعالى فعلاً وتركاً.", "وعد الصدق لمن آمن وعمل صالحاً من ذكر وأنثى بالحياة الطيبة في الدنيا والآخرة."], "k": "«فلنحيينّه حياة طيبة»… أبحث عن طيب الحياة في كثرة المال، وهو في الإيمان والعمل الصالح؛ فأين أبحث اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 182;
insert into public.tdb_cards(topic, i, body) select 182, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩٠ – ٩٣", "q": "۞إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿٩٠﴾ وَأَوۡفُواْ بِعَهۡدِ ٱللَّهِ إِذَا عَٰهَدتُّمۡ وَلَا تَنقُضُواْ ٱلۡأَيۡمَٰنَ بَعۡدَ تَوۡكِيدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَيۡكُمۡ كَفِيلًاۚ إِنَّ ٱللَّهَ يَعۡلَمُ مَا تَفۡعَلُونَ ﴿٩١﴾ وَلَا تَكُونُواْ كَٱلَّتِي نَقَضَتۡ غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَٰثٗا تَتَّخِذُونَ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِيَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا يَبۡلُوكُمُ ٱللَّهُ بِهِۦۚ وَلَيُبَيِّنَنَّ لَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ مَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ ﴿٩٢﴾ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ ﴿٩٣﴾", "w": [["العدل", "الإنصاف، ومنه التوحيد."], ["الإحسان", "أداء الفرائض وترك المحارم مع مراقبة الله تعالى."], ["وإيتاء ذي القربى", "إعطاء ذي القربى حقوقهم من الصلة والبر."], ["عن الفحشاء", "الزنا."], ["يعظكم", "يأمركم وينهاكم."], ["توكيدها", "تغليظها."], ["نقضت غزلها", "أفسدت غزلها بعدما غزلته."], ["من بعد قوة", "إحكام له وبرم."], ["أنكاثاً", "جمع نِكث، وهو ما يُنكث ويُحلّ بعد الإبرام."], ["كالتي نقضت غزلها", "هي حمقاء مكة، وتدعى ريطة بنت سعد بن تيم القرشية."], ["دخلاً بينكم", "الدخل ما يدخل في الشيء وهو ليس منه، للإفساد والخديعة."], ["أربى من أمة", "أكثر منها عدداً وقوة."]], "m": "إن الله يأمر في الكتاب الذي أنزله تبياناً لكل شيء بالعدل، وهو الإنصاف، ومنه أن يُعبد الله وحده لأنه الخالق المنعم، ولذا فُسّر بلا إله إلا الله، وبالإحسان، وهو أداء الفرائض واجتناب المحرمات مع مراقبة الله حتى يكون الأداء إتقاناً وجودة والاجتناب حياءً منه، وبإيتاء ذوي القرابات حقوقهم من البر والصلة، وينهى عن الفحشاء، الزنا واللواط وكل قبيح اشتد قبحه، والمنكر، كل ما أنكره الشرع والفطر السليمة، والبغي، الظلم ومجاوزة الحد، يعظكم لعلكم تذكّرون فتمتثلوا، ولذا ورد أن هذه الآية أجمع آية في كتاب الله للخير والشر. وأوفوا بعهد الله إذا عاهدتم، فمن بايع إماماً أو عاهد أحداً وجب عليه الوفاء، إذ لا دين لمن لا عهد له، ولا تنقضوا الأيمان بعد تغليظها وقد جعلتم الله عليكم وكيلاً، إن الله يعلم ما تفعلون. ولا تكونوا كحمقاء مكة التي تغزل ثم تنكث غزلها بعد إحكامه، تتخذون أيمانكم خديعة بينكم، تعاهدون جماعة ثم تنقضون عهدكم لأن جماعة أخرى أكثر رجالاً ومالاً، إنما يختبركم الله بذلك، وليبيّننّ لكم يوم القيامة ما كنتم فيه تختلفون. ولو شاء الله لجعلكم أمة واحدة، ولكن يضل من يشاء ويهدي من يشاء، ولتُسألنّ سؤال توبيخ عما كنتم تعملون.", "h": ["بيان أجمع آية للخير والشر في القرآن، وهي آية: «إن الله يأمر بالعدل والإحسان».", "وجوب العدل والإحسان، وإعطاء ذوي القربى حقوقهم الواجبة من البر والصلة.", "تحريم الزنا واللواط، وكل قبيح اشتد قبحه من الفواحش الظاهرة والباطنة.", "تحريم البغي، وهو الظلم بجميع صوره وأشكاله.", "وجوب الوفاء بالعهود، وحرمة نقضها.", "حرمة نقض الأيمان بعد توكيدها وتوطين النفس عليها، ليخرج لغو اليمين.", "من بايع أميراً أو عاهد أحداً يجب عليه الوفاء، ولا يجوز النقض والنكث لمنافع دنيوية أبداً."], "k": "«ولا تكونوا كالتي نقضت غزلها»… عهد أو وعد أعطيته ثم تهاونت فيه؛ متى أوفي به؟"}, {"lbl": "الآيات ٩٤ – ٩٧", "q": "وَلَا تَتَّخِذُوٓاْ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا وَتَذُوقُواْ ٱلسُّوٓءَ بِمَا صَدَدتُّمۡ عَن سَبِيلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ عَظِيمٞ ﴿٩٤﴾ وَلَا تَشۡتَرُواْ بِعَهۡدِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ﴿٩٥﴾ مَا عِندَكُمۡ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٖۗ وَلَنَجۡزِيَنَّ ٱلَّذِينَ صَبَرُوٓاْ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ ﴿٩٦﴾ مَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ ﴿٩٧﴾", "w": [["دخلاً بينكم", "لأجل الإفساد والخديعة."], ["وتذوقوا السوء", "العذاب."], ["ما عندكم ينفد", "يفنى وينتهي."], ["وهو مؤمن", "والحال أنه عندما عمل صالحاً كان مؤمناً."], ["حياة طيبة", "في الدنيا بالقناعة والرزق الحلال، وفي الآخرة هي حياة الجنة."], ["بأحسن ما كانوا يعملون", "يجزيهم على كل أعمالهم بحسب أحسنها."]], "m": "ما زال السياق في تربية المؤمنين أهل القرآن: ولا تتخذوا أيمانكم خديعة بينكم لتتوصلوا بها إلى غرض دنيوي، فتزلّ قدم أحدكم بعد ثبوتها في الإسلام، وتذوقوا السوء في الدنيا بما صددتم عن سبيل الله من عاهدتموهم ثم نقضتم، فينصرفون عن الإسلام بسبب ما رأوا منكم، ولكم عذاب عظيم يوم القيامة. ولا تشتروا بعهد الله ثمناً قليلاً، وكل ما في الدنيا قليل، إنما عند الله هو خير لكم إن كنتم تعلمون، ما عندكم من مال ومتاع ينفد ويفنى، وما عند الله باقٍ لا نفاد له، فلا تبيعوا الباقي بالفاني. ولنجزينّ الذين صبروا على عهودهم أجرهم بأحسن ما كانوا يعملون، فيضاعف لهم الأجر حتى يكون أجر النافلة كأجر الفريضة. من عمل صالحاً من ذكر أو أنثى وهو مؤمن، الإيمان الحق الذي يدفع إلى العمل الصالح ويخلّيه من الشرك والمعاصي، فلنحيينّه حياة طيبة في الدنيا، لا خبث فيها: قناعة وطيب طعام وشراب ورضا، وفي الآخرة الجنة، ولنجزينّهم أجرهم بأحسن ما كانوا يعملون، في الصلاة كأفضل صلاة، وفي الصدقة كأفضل صدقة.", "h": ["حرمة اتخاذ الأيمان طريقاً إلى الغش والخديعة والإفساد.", "ما عند الله خير مما يحصل عليه الإنسان بمعصية الرحمن من حطام الدنيا.", "عظم أجر الصبر على طاعة الله تعالى فعلاً وتركاً.", "وعد الصدق لمن آمن وعمل صالحاً من ذكر وأنثى بالحياة الطيبة في الدنيا والآخرة."], "k": "«فلنحيينّه حياة طيبة»… أبحث عن طيب الحياة في كثرة المال، وهو في الإيمان والعمل الصالح؛ فأين أبحث اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (183, 16, 98, 109, 'سورة النحل ٩٨ – ١٠٩', 'الاستعاذة عند القراءة، والنسخ، وافتراء «إنما يعلّمه بشر»، و«إلا من أُكره وقلبه مطمئن بالإيمان»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 183) = $j$[{"lbl": "الآيات ٩٨ – ١٠٢", "q": "فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ ﴿٩٨﴾ إِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٩٩﴾ إِنَّمَا سُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشۡرِكُونَ ﴿١٠٠﴾ وَإِذَا بَدَّلۡنَآ ءَايَةٗ مَّكَانَ ءَايَةٖ وَٱللَّهُ أَعۡلَمُ بِمَا يُنَزِّلُ قَالُوٓاْ إِنَّمَآ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿١٠١﴾ قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُواْ وَهُدٗى وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ ﴿١٠٢﴾", "w": [["فإذا قرأت القرآن", "أردت أن تقرأ القرآن."], ["فاستعذ بالله من الشيطان", "قل: أعوذ بالله من الشيطان الرجيم، لحمايتك من وسواسه."], ["إنه ليس له سلطان", "قوة وتسلّط على إفساد الذين آمنوا وإضلالهم ما داموا متوكلين على الله."], ["وإذا بدّلنا آية مكان آية", "بنسخها وإنزال آية أخرى غيرها لمصلحة العباد."], ["قل نزّله روح القدس", "جبريل ﵇."], ["ليثبّت الذين آمنوا", "على إيمانهم."]], "m": "ما زال السياق في هداية المسلمين وتكميلهم: فإذا أردت قراءة القرآن، أنت أو أحد من المؤمنين، فقل: أعوذ بالله من الشيطان الرجيم، فإن ذلك يقيك من وسواسه الذي قد يفسد عليك تلاوتك. إنه ليس له تسلّط وغلبة على الذين آمنوا وعلى ربهم يتوكلون، وهذه بشرى خير للمؤمنين، إنما سلطانه على الذين يتولّونه بطاعته والعمل بتزيينه، والذين هم به مشركون، فيغويهم حتى يهلكهم. وإذا بدّلنا آية مكان آية، نسخنا حكماً بحكم آخر، قال المكذّبون: إنما أنت مفترٍ تقول اليوم شيئاً وغداً خلافه، والله أعلم بما ينزّل لمصلحة عباده، بل أكثرهم لا يعلمون. قل: نزّله جبريل من ربك بالحق الثابت، فلست أنت الذي تقول ما تشاء، ليثبّت الذين آمنوا على إيمانهم، فكلما نزل قرآن ازداد المؤمنون إيماناً، كالغيث كلما نزل على الأرض ازدادت حياتها نضرة، وهدى من كل ضلالة، وبشرى للمسلمين بفلاح الدنيا وفوز الآخرة.", "h": ["استحباب الاستعاذة عند قراءة القرآن بلفظ: أعوذ بالله من الشيطان الرجيم.", "بيان أنه لا تسلّط للشيطان على المؤمنين المتوكلين على ربهم.", "بيان أن سلطان الشيطان على أوليائه العاملين بطاعته المشركين بربهم.", "بيان أن القرآن فيه الناسخ والمنسوخ.", "بيان فائدة نزول القرآن بالناسخ والمنسوخ، وهي تثبيت الذين آمنوا على إيمانهم، وهدى من الضلالة، وبشرى للمسلمين بالفوز والفلاح في الدارين."], "k": "«إنه ليس له سلطان على الذين آمنوا وعلى ربهم يتوكلون»… حين أشعر بغلبة الوسوسة، هل أفزع إلى الاستعاذة والتوكل؟"}, {"lbl": "الآيات ١٠٣ – ١٠٩", "q": "وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٞۗ لِّسَانُ ٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيّٞ وَهَٰذَا لِسَانٌ عَرَبِيّٞ مُّبِينٌ ﴿١٠٣﴾ إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهۡدِيهِمُ ٱللَّهُ وَلَهُمۡ عَذَابٌ أَلِيمٌ ﴿١٠٤﴾ إِنَّمَا يَفۡتَرِي ٱلۡكَذِبَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰذِبُونَ ﴿١٠٥﴾ مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرٗا فَعَلَيۡهِمۡ غَضَبٞ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمٞ ﴿١٠٦﴾ ذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ﴿١٠٧﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ ﴿١٠٨﴾ لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡخَٰسِرُونَ ﴿١٠٩﴾", "w": [["بشر", "يعنون قيناً، حدّاداً نصرانياً في مكة."], ["لسان الذي يلحدون إليه", "الذي يميلون إليه."], ["وهذا لسان عربي", "القرآن، فكيف يعلّمه أعجمي؟"], ["إلا من أُكره", "على التلفظ بالكفر فتلفّظ به."], ["ولكن من شرح بالكفر صدراً", "فتح صدره للكفر وشرحه له فطابت نفسه له."], ["وأولئك هم الغافلون", "عما يُراد بهم."], ["لا جرم", "حقاً."], ["هم الخاسرون", "لمصيرهم إلى النار خالدين فيها أبداً."]], "m": "ما زال السياق في الرد على المشركين الذين اتهموا الرسول ﷺ بالافتراء: ولقد نعلم أنهم يقولون: إنما يعلّمه إنسان من الناس، لا وحي يتلقّاه من الله، فأبطل الله الفرية: لسان الذي يميلون إليه أعجمي لأنه عبد رومي، وهذا القرآن لسان عربي مبين ذو فصاحة وبلاغة، فكيف يعلّمه أعجمي؟ إن الذين لا يؤمنون بآيات الله، وهي نور وهدى وحجج قواطع، لا يهديهم الله إلى معرفة الحق لأنهم أعرضوا عن طريق الهداية، ولهم عذاب أليم. إنما يفتري الكذب الذين لا يؤمنون بآيات الله، لأنهم لا يرجون ثواباً ولا يخافون عقاباً، أما المؤمن فيرجو ثواب الصدق ويخاف عقاب الكذب فلا يكذب أبداً، فتعيّن أن النبي ﷺ لم يفتر، وأولئك هم الكاذبون. من كفر بالله من بعد إيمانه، إلا من أُكره على التلفظ بالكفر وقلبه مطمئن بالإيمان لا يخامره شك، كعمار بن ياسر أكرهته قريش فأذن له الرسول ﷺ في قولها بلسانه، ولكن من رضي بالكفر وطابت به نفسه فعليهم غضب من الله ولهم عذاب عظيم، ذلك بأنهم استحبّوا الحياة الدنيا على الآخرة لما في الكفر من التحرّر من العبادات، أولئك الذين طبع الله على قلوبهم فلا يفهمون، وسمعهم فلا يسمعون المواعظ، وأبصارهم فلا يبصرون آياته، بسبب إعراضهم المتعمّد وعنادهم، وأولئك هم الغافلون عما خُلقوا له، حقاً أنهم في الآخرة هم الخاسرون.", "h": ["دفاع الله تعالى عن رسوله، ودرء كل تهمة توجّه إلى رسول الله ﷺ.", "المكذّبون بآيات الله يُحرمون هداية الله، لأن طريق الهداية هو الإيمان بالقرآن، فلما كفروا به فعلى أي شيء يهتدون؟", "المؤمنون لا يكذبون لإيمانهم بثواب الصدق وعقاب الكذب، ولكن الكافرين هم الذين يكذبون لعدم ما يمنعهم من الكذب، إذ لا يرجون ثواباً ولا يخافون عقاباً.", "الرخصة في كلمة الكفر في حال التعذيب بشرط اطمئنان القلب إلى الإيمان، وعدم انشراح الصدر بكلمة الكفر."], "k": "«إنما يفتري الكذب الذين لا يؤمنون»… الصدق علامة الإيمان؛ فهل صدقت في كل ما قلته اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 183;
insert into public.tdb_cards(topic, i, body) select 183, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩٨ – ١٠٢", "q": "فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ ﴿٩٨﴾ إِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ ﴿٩٩﴾ إِنَّمَا سُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشۡرِكُونَ ﴿١٠٠﴾ وَإِذَا بَدَّلۡنَآ ءَايَةٗ مَّكَانَ ءَايَةٖ وَٱللَّهُ أَعۡلَمُ بِمَا يُنَزِّلُ قَالُوٓاْ إِنَّمَآ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ ﴿١٠١﴾ قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُواْ وَهُدٗى وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ ﴿١٠٢﴾", "w": [["فإذا قرأت القرآن", "أردت أن تقرأ القرآن."], ["فاستعذ بالله من الشيطان", "قل: أعوذ بالله من الشيطان الرجيم، لحمايتك من وسواسه."], ["إنه ليس له سلطان", "قوة وتسلّط على إفساد الذين آمنوا وإضلالهم ما داموا متوكلين على الله."], ["وإذا بدّلنا آية مكان آية", "بنسخها وإنزال آية أخرى غيرها لمصلحة العباد."], ["قل نزّله روح القدس", "جبريل ﵇."], ["ليثبّت الذين آمنوا", "على إيمانهم."]], "m": "ما زال السياق في هداية المسلمين وتكميلهم: فإذا أردت قراءة القرآن، أنت أو أحد من المؤمنين، فقل: أعوذ بالله من الشيطان الرجيم، فإن ذلك يقيك من وسواسه الذي قد يفسد عليك تلاوتك. إنه ليس له تسلّط وغلبة على الذين آمنوا وعلى ربهم يتوكلون، وهذه بشرى خير للمؤمنين، إنما سلطانه على الذين يتولّونه بطاعته والعمل بتزيينه، والذين هم به مشركون، فيغويهم حتى يهلكهم. وإذا بدّلنا آية مكان آية، نسخنا حكماً بحكم آخر، قال المكذّبون: إنما أنت مفترٍ تقول اليوم شيئاً وغداً خلافه، والله أعلم بما ينزّل لمصلحة عباده، بل أكثرهم لا يعلمون. قل: نزّله جبريل من ربك بالحق الثابت، فلست أنت الذي تقول ما تشاء، ليثبّت الذين آمنوا على إيمانهم، فكلما نزل قرآن ازداد المؤمنون إيماناً، كالغيث كلما نزل على الأرض ازدادت حياتها نضرة، وهدى من كل ضلالة، وبشرى للمسلمين بفلاح الدنيا وفوز الآخرة.", "h": ["استحباب الاستعاذة عند قراءة القرآن بلفظ: أعوذ بالله من الشيطان الرجيم.", "بيان أنه لا تسلّط للشيطان على المؤمنين المتوكلين على ربهم.", "بيان أن سلطان الشيطان على أوليائه العاملين بطاعته المشركين بربهم.", "بيان أن القرآن فيه الناسخ والمنسوخ.", "بيان فائدة نزول القرآن بالناسخ والمنسوخ، وهي تثبيت الذين آمنوا على إيمانهم، وهدى من الضلالة، وبشرى للمسلمين بالفوز والفلاح في الدارين."], "k": "«إنه ليس له سلطان على الذين آمنوا وعلى ربهم يتوكلون»… حين أشعر بغلبة الوسوسة، هل أفزع إلى الاستعاذة والتوكل؟"}, {"lbl": "الآيات ١٠٣ – ١٠٩", "q": "وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٞۗ لِّسَانُ ٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيّٞ وَهَٰذَا لِسَانٌ عَرَبِيّٞ مُّبِينٌ ﴿١٠٣﴾ إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهۡدِيهِمُ ٱللَّهُ وَلَهُمۡ عَذَابٌ أَلِيمٌ ﴿١٠٤﴾ إِنَّمَا يَفۡتَرِي ٱلۡكَذِبَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰذِبُونَ ﴿١٠٥﴾ مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرٗا فَعَلَيۡهِمۡ غَضَبٞ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمٞ ﴿١٠٦﴾ ذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ ﴿١٠٧﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ وَأُوْلَـٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ ﴿١٠٨﴾ لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡخَٰسِرُونَ ﴿١٠٩﴾", "w": [["بشر", "يعنون قيناً، حدّاداً نصرانياً في مكة."], ["لسان الذي يلحدون إليه", "الذي يميلون إليه."], ["وهذا لسان عربي", "القرآن، فكيف يعلّمه أعجمي؟"], ["إلا من أُكره", "على التلفظ بالكفر فتلفّظ به."], ["ولكن من شرح بالكفر صدراً", "فتح صدره للكفر وشرحه له فطابت نفسه له."], ["وأولئك هم الغافلون", "عما يُراد بهم."], ["لا جرم", "حقاً."], ["هم الخاسرون", "لمصيرهم إلى النار خالدين فيها أبداً."]], "m": "ما زال السياق في الرد على المشركين الذين اتهموا الرسول ﷺ بالافتراء: ولقد نعلم أنهم يقولون: إنما يعلّمه إنسان من الناس، لا وحي يتلقّاه من الله، فأبطل الله الفرية: لسان الذي يميلون إليه أعجمي لأنه عبد رومي، وهذا القرآن لسان عربي مبين ذو فصاحة وبلاغة، فكيف يعلّمه أعجمي؟ إن الذين لا يؤمنون بآيات الله، وهي نور وهدى وحجج قواطع، لا يهديهم الله إلى معرفة الحق لأنهم أعرضوا عن طريق الهداية، ولهم عذاب أليم. إنما يفتري الكذب الذين لا يؤمنون بآيات الله، لأنهم لا يرجون ثواباً ولا يخافون عقاباً، أما المؤمن فيرجو ثواب الصدق ويخاف عقاب الكذب فلا يكذب أبداً، فتعيّن أن النبي ﷺ لم يفتر، وأولئك هم الكاذبون. من كفر بالله من بعد إيمانه، إلا من أُكره على التلفظ بالكفر وقلبه مطمئن بالإيمان لا يخامره شك، كعمار بن ياسر أكرهته قريش فأذن له الرسول ﷺ في قولها بلسانه، ولكن من رضي بالكفر وطابت به نفسه فعليهم غضب من الله ولهم عذاب عظيم، ذلك بأنهم استحبّوا الحياة الدنيا على الآخرة لما في الكفر من التحرّر من العبادات، أولئك الذين طبع الله على قلوبهم فلا يفهمون، وسمعهم فلا يسمعون المواعظ، وأبصارهم فلا يبصرون آياته، بسبب إعراضهم المتعمّد وعنادهم، وأولئك هم الغافلون عما خُلقوا له، حقاً أنهم في الآخرة هم الخاسرون.", "h": ["دفاع الله تعالى عن رسوله، ودرء كل تهمة توجّه إلى رسول الله ﷺ.", "المكذّبون بآيات الله يُحرمون هداية الله، لأن طريق الهداية هو الإيمان بالقرآن، فلما كفروا به فعلى أي شيء يهتدون؟", "المؤمنون لا يكذبون لإيمانهم بثواب الصدق وعقاب الكذب، ولكن الكافرين هم الذين يكذبون لعدم ما يمنعهم من الكذب، إذ لا يرجون ثواباً ولا يخافون عقاباً.", "الرخصة في كلمة الكفر في حال التعذيب بشرط اطمئنان القلب إلى الإيمان، وعدم انشراح الصدر بكلمة الكفر."], "k": "«إنما يفتري الكذب الذين لا يؤمنون»… الصدق علامة الإيمان؛ فهل صدقت في كل ما قلته اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (184, 16, 110, 118, 'سورة النحل ١١٠ – ١١٨', 'مثل القرية الآمنة التي كفرت بأنعم الله، و«فكلوا مما رزقكم الله حلالاً طيباً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 184) = $j$[{"lbl": "الآيات ١١٠ – ١١٣", "q": "ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُواْ مِنۢ بَعۡدِ مَا فُتِنُواْ ثُمَّ جَٰهَدُواْ وَصَبَرُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ ﴿١١٠﴾ ۞يَوۡمَ تَأۡتِي كُلُّ نَفۡسٖ تُجَٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿١١١﴾ وَضَرَبَ ٱللَّهُ مَثَلٗا قَرۡيَةٗ كَانَتۡ ءَامِنَةٗ مُّطۡمَئِنَّةٗ يَأۡتِيهَا رِزۡقُهَا رَغَدٗا مِّن كُلِّ مَكَانٖ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُواْ يَصۡنَعُونَ ﴿١١٢﴾ وَلَقَدۡ جَآءَهُمۡ رَسُولٞ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ ظَٰلِمُونَ ﴿١١٣﴾", "w": [["هاجروا", "إلى المدينة."], ["من بعد ما فُتنوا", "فتنهم المشركون بمكة فعذّبوهم حتى قالوا كلمة الكفر مكرهين."], ["إن ربك من بعدها", "من بعد الهجرة والجهاد والصبر على الإيمان."], ["لغفور رحيم", "غفور لهم، رحيم بهم."], ["يوم تأتي", "اذكر يا محمد يوم تأتي كل نفس تجادل عن نفسها."], ["مثلاً قرية", "هي مكة."], ["رزقها رغداً", "واسعاً."], ["فكفرت بأنعم الله", "بالرسول والقرآن والأمن ورغد العيش."], ["فأذاقها الله لباس الجوع", "بسبب قحط أصابهم حتى أكلوا العهن لمدة سبع سنين."], ["والخوف", "حيث أصبحت سرايا الإسلام تغزوهم وتقطع عنهم سبل تجارتهم."]], "m": "بعدما ذكر رخصة كلمة الكفر عند الإكراه، ذكر بعض المؤمنين تخلّفوا عن الهجرة، فلما أرادوها منعتهم قريش وعذّبتهم حتى قالوا كلمة الكفر، ثم تمكّنوا فهاجروا وجاهدوا وصبروا: ثم إن ربك للذين هاجروا من بعد ما فُتنوا، ثم جاهدوا وصبروا، إن ربك من بعدها لغفور لهم رحيم بهم. واذكر يوم تأتي كل نفس تخاصم طالبة النجاة لنفسها، وتُوفّى كل نفس ما عملت من خير أو شر وهم لا يُظلمون. وضرب الله مثلاً قرية، مكة، كانت آمنة من غارات الأعداء، مطمئنة لما جعل الله في قلوب العرب من تعظيم الحرم، يأتيها رزقها واسعاً من كل مكان، فكفرت بأنعم الله بتكذيب رسوله وإنكار التوحيد وحرب الإسلام، فدعا عليهم الرسول ﷺ: «اللهم اجعلها عليهم سنين كسني يوسف»، فأذاقها الله لباس الجوع سبع سنين حتى أكلوا الجيف والعهن، ولباس الخوف إذ أصبحت سرايا الإسلام تعترض تجارتها، بما كانوا يصنعون من اضطهاد المؤمنين. ولقد جاءهم رسول منهم، محمد ﷺ، فكذّبوه، فأخذهم العذاب وهم ظالمون.", "h": ["فضل الهجرة والجهاد والصبر، وما تكفّر هذه العبادات من الذنوب.", "وجوب التذكير باليوم الآخر وما يتم فيه من ثواب وعقاب للتجافي عن الدنيا.", "استحسان ضرب الأمثال من أهل العلم.", "كفر النعم سبب زوالها، والانتقام من أهلها.", "تكذيب الرسول ﷺ فيما جاء به، ولو بالإعراض عنه وعدم العمل به، يجرّ البلاء."], "k": "«فكفرت بأنعم الله فأذاقها الله لباس الجوع والخوف»… الأمن والرزق اللذان أعيش فيهما؛ هل أحرسهما بالشكر؟"}, {"lbl": "الآيات ١١٤ – ١١٨", "q": "فَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗا وَٱشۡكُرُواْ نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ ﴿١١٤﴾ إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿١١٥﴾ وَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَٰذَا حَلَٰلٞ وَهَٰذَا حَرَامٞ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ ﴿١١٦﴾ مَتَٰعٞ قَلِيلٞ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿١١٧﴾ وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا مَا قَصَصۡنَا عَلَيۡكَ مِن قَبۡلُۖ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿١١٨﴾", "w": [["فكلوا", "أيها الناس."], ["حلالاً طيباً", "غير حرام ولا مستقذر."], ["واشكروا نعمة الله", "بعبادته وحده، وبالانتهاء إلى ما أحلّ لكم عما حرّمه عليكم."], ["إن كنتم إياه تعبدون", "إن كنتم تعبدونه وحده فامتثلوا أمره."], ["الميتة", "ما مات من الحيوان حتف أنفه من غير تذكية شرعية."], ["والدم", "الدم المسفوح السائل، لا المختلط باللحم والعظم."], ["وما أُهلّ لغير الله به", "ما ذُكر عليه غير اسم الله تعالى."], ["غير باغ ولا عاد", "غير باغ على أحد، ولا متجاوز حدّ الضرورة."], ["ولا تقولوا لما تصف ألسنتكم الكذب", "لا تحلّلوا ولا تحرّموا بألسنتكم كذباً على الله."], ["وعلى الذين هادوا", "اليهود."], ["حرّمنا ما قصصنا عليك من قبل", "أي في سورة الأنعام."]], "m": "امتنّ الله على عباده فأذن لهم أن يأكلوا مما رزقهم من الحلال الطيب، ويشكروه على ذلك بعبادته وحده. إنما حرّم عليكم الميتة والدم ولحم الخنزير وما ذُكر عليه غير اسم الله، فلا تحرّموا ما لم يحرّمه كالسائبة والبحيرة التي حرّمها المشركون افتراءً، فمن خاف على نفسه الهلاك لشدة الجوع غير باغٍ على أحد ولا متجاوز حد الضرورة، فليأكل ما يدفع به غائلة الجوع، فإن الله غفور رحيم. ولا تقولوا لما تصف ألسنتكم الكذب: هذا حلال وهذا حرام، بلا وحي ولا شرع، فتؤول بكم إلى الافتراء على الله، إن الذين يفترون على الله الكذب لا يفلحون، وإن تمتعوا في الدنيا بمال أو ولد أو سلطان فذلك متاع قليل، ولهم عذاب أليم. وعلى اليهود حرّمنا ما قصصنا عليك من قبل في سورة الأنعام: كل ذي ظفر، وشحوم البقر والغنم إلا ما استُثني، وما ظلمناهم بذلك، ولكن كانوا أنفسهم يظلمون، فحرّم عليهم طيبات بسبب ظلمهم.", "h": ["يجب مقابلة النعم بالشكر، فمن غير العدل أن يكفر العبد نعم الله تعالى عليه فلا يشكره عليها بذكره وحمده وطاعته.", "بيان المحرّمات من المطاعم، وهي الميتة والدم ولحم الخنزير وما أُهلّ لغير الله به.", "بيان الرخصة في الأكل من المحرّمات المذكورة لدفع غائلة الموت.", "حرمة التحريم والتحليل بغير دليل شرعي.", "حرمة الكذب على الله، وأن الكاذب على الله لا يفلح في الآخرة، وفلاحه في الدنيا جزئي قليل لا قيمة له، هذا إن أفلح.", "قد يُحرم العبد النعم بسبب ظلمه، فكم حُرمت أمة الإسلام من نعم بسبب ظلمها في عصور انحطاطها."], "k": "«فكلوا مما رزقكم الله حلالاً طيباً واشكروا»… هل أتحرّى الحلال في رزقي كما أتحرّاه في طعامي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 184;
insert into public.tdb_cards(topic, i, body) select 184, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١٠ – ١١٣", "q": "ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُواْ مِنۢ بَعۡدِ مَا فُتِنُواْ ثُمَّ جَٰهَدُواْ وَصَبَرُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ ﴿١١٠﴾ ۞يَوۡمَ تَأۡتِي كُلُّ نَفۡسٖ تُجَٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿١١١﴾ وَضَرَبَ ٱللَّهُ مَثَلٗا قَرۡيَةٗ كَانَتۡ ءَامِنَةٗ مُّطۡمَئِنَّةٗ يَأۡتِيهَا رِزۡقُهَا رَغَدٗا مِّن كُلِّ مَكَانٖ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُواْ يَصۡنَعُونَ ﴿١١٢﴾ وَلَقَدۡ جَآءَهُمۡ رَسُولٞ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ ظَٰلِمُونَ ﴿١١٣﴾", "w": [["هاجروا", "إلى المدينة."], ["من بعد ما فُتنوا", "فتنهم المشركون بمكة فعذّبوهم حتى قالوا كلمة الكفر مكرهين."], ["إن ربك من بعدها", "من بعد الهجرة والجهاد والصبر على الإيمان."], ["لغفور رحيم", "غفور لهم، رحيم بهم."], ["يوم تأتي", "اذكر يا محمد يوم تأتي كل نفس تجادل عن نفسها."], ["مثلاً قرية", "هي مكة."], ["رزقها رغداً", "واسعاً."], ["فكفرت بأنعم الله", "بالرسول والقرآن والأمن ورغد العيش."], ["فأذاقها الله لباس الجوع", "بسبب قحط أصابهم حتى أكلوا العهن لمدة سبع سنين."], ["والخوف", "حيث أصبحت سرايا الإسلام تغزوهم وتقطع عنهم سبل تجارتهم."]], "m": "بعدما ذكر رخصة كلمة الكفر عند الإكراه، ذكر بعض المؤمنين تخلّفوا عن الهجرة، فلما أرادوها منعتهم قريش وعذّبتهم حتى قالوا كلمة الكفر، ثم تمكّنوا فهاجروا وجاهدوا وصبروا: ثم إن ربك للذين هاجروا من بعد ما فُتنوا، ثم جاهدوا وصبروا، إن ربك من بعدها لغفور لهم رحيم بهم. واذكر يوم تأتي كل نفس تخاصم طالبة النجاة لنفسها، وتُوفّى كل نفس ما عملت من خير أو شر وهم لا يُظلمون. وضرب الله مثلاً قرية، مكة، كانت آمنة من غارات الأعداء، مطمئنة لما جعل الله في قلوب العرب من تعظيم الحرم، يأتيها رزقها واسعاً من كل مكان، فكفرت بأنعم الله بتكذيب رسوله وإنكار التوحيد وحرب الإسلام، فدعا عليهم الرسول ﷺ: «اللهم اجعلها عليهم سنين كسني يوسف»، فأذاقها الله لباس الجوع سبع سنين حتى أكلوا الجيف والعهن، ولباس الخوف إذ أصبحت سرايا الإسلام تعترض تجارتها، بما كانوا يصنعون من اضطهاد المؤمنين. ولقد جاءهم رسول منهم، محمد ﷺ، فكذّبوه، فأخذهم العذاب وهم ظالمون.", "h": ["فضل الهجرة والجهاد والصبر، وما تكفّر هذه العبادات من الذنوب.", "وجوب التذكير باليوم الآخر وما يتم فيه من ثواب وعقاب للتجافي عن الدنيا.", "استحسان ضرب الأمثال من أهل العلم.", "كفر النعم سبب زوالها، والانتقام من أهلها.", "تكذيب الرسول ﷺ فيما جاء به، ولو بالإعراض عنه وعدم العمل به، يجرّ البلاء."], "k": "«فكفرت بأنعم الله فأذاقها الله لباس الجوع والخوف»… الأمن والرزق اللذان أعيش فيهما؛ هل أحرسهما بالشكر؟"}, {"lbl": "الآيات ١١٤ – ١١٨", "q": "فَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗا وَٱشۡكُرُواْ نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ ﴿١١٤﴾ إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ ﴿١١٥﴾ وَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَٰذَا حَلَٰلٞ وَهَٰذَا حَرَامٞ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ ﴿١١٦﴾ مَتَٰعٞ قَلِيلٞ وَلَهُمۡ عَذَابٌ أَلِيمٞ ﴿١١٧﴾ وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا مَا قَصَصۡنَا عَلَيۡكَ مِن قَبۡلُۖ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ﴿١١٨﴾", "w": [["فكلوا", "أيها الناس."], ["حلالاً طيباً", "غير حرام ولا مستقذر."], ["واشكروا نعمة الله", "بعبادته وحده، وبالانتهاء إلى ما أحلّ لكم عما حرّمه عليكم."], ["إن كنتم إياه تعبدون", "إن كنتم تعبدونه وحده فامتثلوا أمره."], ["الميتة", "ما مات من الحيوان حتف أنفه من غير تذكية شرعية."], ["والدم", "الدم المسفوح السائل، لا المختلط باللحم والعظم."], ["وما أُهلّ لغير الله به", "ما ذُكر عليه غير اسم الله تعالى."], ["غير باغ ولا عاد", "غير باغ على أحد، ولا متجاوز حدّ الضرورة."], ["ولا تقولوا لما تصف ألسنتكم الكذب", "لا تحلّلوا ولا تحرّموا بألسنتكم كذباً على الله."], ["وعلى الذين هادوا", "اليهود."], ["حرّمنا ما قصصنا عليك من قبل", "أي في سورة الأنعام."]], "m": "امتنّ الله على عباده فأذن لهم أن يأكلوا مما رزقهم من الحلال الطيب، ويشكروه على ذلك بعبادته وحده. إنما حرّم عليكم الميتة والدم ولحم الخنزير وما ذُكر عليه غير اسم الله، فلا تحرّموا ما لم يحرّمه كالسائبة والبحيرة التي حرّمها المشركون افتراءً، فمن خاف على نفسه الهلاك لشدة الجوع غير باغٍ على أحد ولا متجاوز حد الضرورة، فليأكل ما يدفع به غائلة الجوع، فإن الله غفور رحيم. ولا تقولوا لما تصف ألسنتكم الكذب: هذا حلال وهذا حرام، بلا وحي ولا شرع، فتؤول بكم إلى الافتراء على الله، إن الذين يفترون على الله الكذب لا يفلحون، وإن تمتعوا في الدنيا بمال أو ولد أو سلطان فذلك متاع قليل، ولهم عذاب أليم. وعلى اليهود حرّمنا ما قصصنا عليك من قبل في سورة الأنعام: كل ذي ظفر، وشحوم البقر والغنم إلا ما استُثني، وما ظلمناهم بذلك، ولكن كانوا أنفسهم يظلمون، فحرّم عليهم طيبات بسبب ظلمهم.", "h": ["يجب مقابلة النعم بالشكر، فمن غير العدل أن يكفر العبد نعم الله تعالى عليه فلا يشكره عليها بذكره وحمده وطاعته.", "بيان المحرّمات من المطاعم، وهي الميتة والدم ولحم الخنزير وما أُهلّ لغير الله به.", "بيان الرخصة في الأكل من المحرّمات المذكورة لدفع غائلة الموت.", "حرمة التحريم والتحليل بغير دليل شرعي.", "حرمة الكذب على الله، وأن الكاذب على الله لا يفلح في الآخرة، وفلاحه في الدنيا جزئي قليل لا قيمة له، هذا إن أفلح.", "قد يُحرم العبد النعم بسبب ظلمه، فكم حُرمت أمة الإسلام من نعم بسبب ظلمها في عصور انحطاطها."], "k": "«فكلوا مما رزقكم الله حلالاً طيباً واشكروا»… هل أتحرّى الحلال في رزقي كما أتحرّاه في طعامي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (185, 16, 119, 128, 'سورة النحل ١١٩ – ١٢٨', '«إن إبراهيم كان أمة»، و«ادع إلى سبيل ربك بالحكمة والموعظة الحسنة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 185) = $j$[{"lbl": "الآيات ١١٩ – ١٢٤", "q": "ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٌ ﴿١١٩﴾ إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ حَنِيفٗا وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٢٠﴾ شَاكِرٗا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿١٢١﴾ وَءَاتَيۡنَٰهُ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ ﴿١٢٢﴾ ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٢٣﴾ إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِۚ وَإِنَّ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿١٢٤﴾", "w": [["للذين عملوا السوء بجهالة", "إن ربك غفور رحيم للذين عملوا السوء بجهالة ثم تابوا."], ["من بعدها", "من بعد الجهالة والتوبة."], ["إن إبراهيم كان أمة", "إماماً جامعاً لخصال الخير كلها، قدوة يُقتدى به في ذلك."], ["قانتاً لله حنيفاً", "مطيعاً لله، مائلاً إلى الدين القيّم الذي هو الإسلام."], ["اجتباه", "اصطفاه ربه للخلّة بعد الرسالة والنبوة."], ["وآتيناه في الدنيا حسنة", "هي الثناء الحسن من كل أهل الأديان السماوية."], ["إنما جُعل السبت على الذين اختلفوا فيه", "أُمر اليهود بتعظيم الجمعة فأبوا إلا السبت، ففرضه الله عليهم وشدّد لهم فيه عقوبة لهم."]], "m": "أوشك سياق السورة على الانتهاء، ففتح باب التوبة للمعاندين: ثم إن ربك للذين عملوا السوء بجهالة، فأشركوا وكذّبوا، ثم تابوا من بعد ذلك فوحّدوه وآمنوا برسوله ولقائه، وأصلحوا ما أفسدوا من قلوبهم وأعمالهم، إن ربك من بعدها لغفور رحيم. ولما ادّعى المشركون واليهود والنصارى أنهم على ملة إبراهيم، ذكر تعالى من صفاته ما يعرف به كل عاقل هل هو على ملته: كان أمة، إماماً جامعاً لخصال الخير يُقتدى به، قانتاً مطيعاً لربه لا يعصيه، حنيفاً مائلاً إلى الإسلام، ولم يك من المشركين بحال، شاكراً لأنعم الله يصرفها فيما يرضيه، اجتباه ربه لرسالته وخلّته، وهداه إلى صراط مستقيم، وآتيناه في الدنيا الثناء الحسن من جميع أهل الأديان، وإنه في الآخرة لمن الصالحين، ثم أوحينا إليك، مع جلالة قدرك، أن اتبع ملة إبراهيم حنيفاً، فمن أحقّ بالانتساب إليه؟ المسلمون الموحّدون. إنما جُعل تعظيم السبت على الذين اختلفوا فيه، فلم يكن من دين إبراهيم، بل أُمروا بالجمعة فاختلفوا وآثروا السبت عناداً، فكتبه الله عليهم، وإن ربك ليحكم بينهم يوم القيامة فيما كانوا فيه يختلفون.", "h": ["باب التوبة مفتوح لكل ذي ذنب، عظم أو صغر، على شرط صدق التوبة بالإقلاع الفوري والندم والاستغفار الدائم وإصلاح الفاسد.", "تقرير التوحيد، والإعلان عن شأن إبراهيم ﵇، وبيان كمالاته وإنعام الله عليه.", "بيان أن سبت اليهود هو من نقم الله عليهم لا من نعمه وإفضاله عليهم."], "k": "«إن إبراهيم كان أمة قانتاً لله حنيفاً»… رجل واحد كان أمة؛ فأي خصلة من خصاله أبدأ بها؟"}, {"lbl": "الآيات ١٢٥ – ١٢٨", "q": "ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ﴿١٢٥﴾ وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن صَبَرۡتُمۡ لَهُوَ خَيۡرٞ لِّلصَّـٰبِرِينَ ﴿١٢٦﴾ وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ ﴿١٢٧﴾ إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ ﴿١٢٨﴾", "w": [["إلى سبيل ربك", "إلى طاعته، إذ طاعة الله موصلة إلى رضوانه وإنعامه، فهي سبيل الله."], ["بالحكمة", "بالقرآن، والمقالة المحكمة الصحيحة ذات الدليل الموضّح للحق."], ["والموعظة الحسنة", "مواعظ القرآن، والقول الرقيق الحسن."], ["وجادلهم بالتي هي أحسن", "بالمجادلة التي هي أحسن من غيرها."], ["لهو خير للصابرين", "خير من الانتقام عاقبة."], ["ولا تك في ضيق مما يمكرون", "لا تهتم بمكرهم ولا يضق صدرك به."], ["مع الذين اتقوا", "اتقوا الشرك والمعاصي."], ["والذين هم محسنون", "في طاعة الله، ومعيّته تعالى هي نصره وتأييده لهم في الدنيا."]], "m": "يخاطب الرب تعالى رسوله تشريفاً وتكليفاً: ادعُ سائر الناس إلى سبيل ربك، الإسلام، بالحكمة التي هي القرآن الكريم، والموعظة الحسنة، مواعظ القرآن وقصصه وأمثاله وترغيبه وترهيبه، وجادلهم بالمخاصمة التي هي أحسن، الخالية من السب والشتم والتعريض بالسوء، فإن ذلك أدعى لقبول الخصم الحق. إن ربك هو أعلم بمن ضلّ عن سبيله وهو أعلم بالمهتدين، فهوّن على نفسك ولا تشطط في دعوتك، فالأمر ليس إليك. وإن عاقبتم فعاقبوا بمثل ما عوقبتم به لا أكثر، ولئن صبرتم وتركتم المعاقبة لهو خير للصابرين. واصبر على ترك ما عزمت عليه من التمثيل بالمشركين جزاء تمثيلهم بعمك حمزة، وما صبرك إلا بتوفيق الله وعونه، ولا تحزن على عدم اهتدائهم، ولا تك في ضيق مما يمكرون، فإن الله كافيك، إن الله بنصره وتأييده مع الذين اتقوا الشرك والمعاصي، والذين هم محسنون في طاعة ربهم إخلاصاً في النية وأداءً على نحو ما شرع.", "h": ["وجوب الدعوة إلى الله تعالى، أي إلى الإسلام، وهو واجب كفائي إذا قامت به جماعة أجزأ عنهم.", "بيان أسلوب الدعوة، وهو أن يكون بالكتاب والسنة، وأن يكون خالياً من العنف والغلظة والشدة، وأن تكون المجادلة بالتي هي أحسن من غيرها.", "جواز المعاقبة بالأخذ بقدر ما أُخذ من المرء، وتركها صبراً واحتساباً أفضل.", "معيّة الله تعالى ثابتة لأهل التقوى والإحسان، وهي معيّة نصر وتأييد وتسديد."], "k": "«ادع إلى سبيل ربك بالحكمة والموعظة الحسنة»… نصيحتي القادمة، كيف أجعلها حكيمة لطيفة لا جارحة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 185;
insert into public.tdb_cards(topic, i, body) select 185, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١٩ – ١٢٤", "q": "ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٌ ﴿١١٩﴾ إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ حَنِيفٗا وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٢٠﴾ شَاكِرٗا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ ﴿١٢١﴾ وَءَاتَيۡنَٰهُ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّـٰلِحِينَ ﴿١٢٢﴾ ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ﴿١٢٣﴾ إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِۚ وَإِنَّ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ ﴿١٢٤﴾", "w": [["للذين عملوا السوء بجهالة", "إن ربك غفور رحيم للذين عملوا السوء بجهالة ثم تابوا."], ["من بعدها", "من بعد الجهالة والتوبة."], ["إن إبراهيم كان أمة", "إماماً جامعاً لخصال الخير كلها، قدوة يُقتدى به في ذلك."], ["قانتاً لله حنيفاً", "مطيعاً لله، مائلاً إلى الدين القيّم الذي هو الإسلام."], ["اجتباه", "اصطفاه ربه للخلّة بعد الرسالة والنبوة."], ["وآتيناه في الدنيا حسنة", "هي الثناء الحسن من كل أهل الأديان السماوية."], ["إنما جُعل السبت على الذين اختلفوا فيه", "أُمر اليهود بتعظيم الجمعة فأبوا إلا السبت، ففرضه الله عليهم وشدّد لهم فيه عقوبة لهم."]], "m": "أوشك سياق السورة على الانتهاء، ففتح باب التوبة للمعاندين: ثم إن ربك للذين عملوا السوء بجهالة، فأشركوا وكذّبوا، ثم تابوا من بعد ذلك فوحّدوه وآمنوا برسوله ولقائه، وأصلحوا ما أفسدوا من قلوبهم وأعمالهم، إن ربك من بعدها لغفور رحيم. ولما ادّعى المشركون واليهود والنصارى أنهم على ملة إبراهيم، ذكر تعالى من صفاته ما يعرف به كل عاقل هل هو على ملته: كان أمة، إماماً جامعاً لخصال الخير يُقتدى به، قانتاً مطيعاً لربه لا يعصيه، حنيفاً مائلاً إلى الإسلام، ولم يك من المشركين بحال، شاكراً لأنعم الله يصرفها فيما يرضيه، اجتباه ربه لرسالته وخلّته، وهداه إلى صراط مستقيم، وآتيناه في الدنيا الثناء الحسن من جميع أهل الأديان، وإنه في الآخرة لمن الصالحين، ثم أوحينا إليك، مع جلالة قدرك، أن اتبع ملة إبراهيم حنيفاً، فمن أحقّ بالانتساب إليه؟ المسلمون الموحّدون. إنما جُعل تعظيم السبت على الذين اختلفوا فيه، فلم يكن من دين إبراهيم، بل أُمروا بالجمعة فاختلفوا وآثروا السبت عناداً، فكتبه الله عليهم، وإن ربك ليحكم بينهم يوم القيامة فيما كانوا فيه يختلفون.", "h": ["باب التوبة مفتوح لكل ذي ذنب، عظم أو صغر، على شرط صدق التوبة بالإقلاع الفوري والندم والاستغفار الدائم وإصلاح الفاسد.", "تقرير التوحيد، والإعلان عن شأن إبراهيم ﵇، وبيان كمالاته وإنعام الله عليه.", "بيان أن سبت اليهود هو من نقم الله عليهم لا من نعمه وإفضاله عليهم."], "k": "«إن إبراهيم كان أمة قانتاً لله حنيفاً»… رجل واحد كان أمة؛ فأي خصلة من خصاله أبدأ بها؟"}, {"lbl": "الآيات ١٢٥ – ١٢٨", "q": "ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ﴿١٢٥﴾ وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن صَبَرۡتُمۡ لَهُوَ خَيۡرٞ لِّلصَّـٰبِرِينَ ﴿١٢٦﴾ وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ ﴿١٢٧﴾ إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ ﴿١٢٨﴾", "w": [["إلى سبيل ربك", "إلى طاعته، إذ طاعة الله موصلة إلى رضوانه وإنعامه، فهي سبيل الله."], ["بالحكمة", "بالقرآن، والمقالة المحكمة الصحيحة ذات الدليل الموضّح للحق."], ["والموعظة الحسنة", "مواعظ القرآن، والقول الرقيق الحسن."], ["وجادلهم بالتي هي أحسن", "بالمجادلة التي هي أحسن من غيرها."], ["لهو خير للصابرين", "خير من الانتقام عاقبة."], ["ولا تك في ضيق مما يمكرون", "لا تهتم بمكرهم ولا يضق صدرك به."], ["مع الذين اتقوا", "اتقوا الشرك والمعاصي."], ["والذين هم محسنون", "في طاعة الله، ومعيّته تعالى هي نصره وتأييده لهم في الدنيا."]], "m": "يخاطب الرب تعالى رسوله تشريفاً وتكليفاً: ادعُ سائر الناس إلى سبيل ربك، الإسلام، بالحكمة التي هي القرآن الكريم، والموعظة الحسنة، مواعظ القرآن وقصصه وأمثاله وترغيبه وترهيبه، وجادلهم بالمخاصمة التي هي أحسن، الخالية من السب والشتم والتعريض بالسوء، فإن ذلك أدعى لقبول الخصم الحق. إن ربك هو أعلم بمن ضلّ عن سبيله وهو أعلم بالمهتدين، فهوّن على نفسك ولا تشطط في دعوتك، فالأمر ليس إليك. وإن عاقبتم فعاقبوا بمثل ما عوقبتم به لا أكثر، ولئن صبرتم وتركتم المعاقبة لهو خير للصابرين. واصبر على ترك ما عزمت عليه من التمثيل بالمشركين جزاء تمثيلهم بعمك حمزة، وما صبرك إلا بتوفيق الله وعونه، ولا تحزن على عدم اهتدائهم، ولا تك في ضيق مما يمكرون، فإن الله كافيك، إن الله بنصره وتأييده مع الذين اتقوا الشرك والمعاصي، والذين هم محسنون في طاعة ربهم إخلاصاً في النية وأداءً على نحو ما شرع.", "h": ["وجوب الدعوة إلى الله تعالى، أي إلى الإسلام، وهو واجب كفائي إذا قامت به جماعة أجزأ عنهم.", "بيان أسلوب الدعوة، وهو أن يكون بالكتاب والسنة، وأن يكون خالياً من العنف والغلظة والشدة، وأن تكون المجادلة بالتي هي أحسن من غيرها.", "جواز المعاقبة بالأخذ بقدر ما أُخذ من المرء، وتركها صبراً واحتساباً أفضل.", "معيّة الله تعالى ثابتة لأهل التقوى والإحسان، وهي معيّة نصر وتأييد وتسديد."], "k": "«ادع إلى سبيل ربك بالحكمة والموعظة الحسنة»… نصيحتي القادمة، كيف أجعلها حكيمة لطيفة لا جارحة؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;